package dev.lmdb.actor;

import java.time.Clock;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;

/**
 * Actor Service Application. Manages actor/cast information, biographies, and filmographies, and
 * serves the TMDB v3 person facade ({@code GET /person/{id}}) — see ARCHITECTURE.md §3.6 and §5.1.
 * Eureka client is auto-configured when eureka-client dependency is present; caching backs the
 * facade's Redis read-through layer. {@code @ConfigurationPropertiesScan} enables record-based
 * {@link dev.lmdb.actor.client.TmdbProperties} binding (Spring Boot 4).
 */
@SpringBootApplication
@EnableCaching
@ConfigurationPropertiesScan
public class ActorServiceApplication {

  /**
   * Application entry point for actor-service.
   *
   * @param args command-line arguments passed to the Spring Boot application
   */
  public static void main(String[] args) {
    // Launch the Spring Boot application context and initialize all configured beans.
    SpringApplication.run(ActorServiceApplication.class, args);
  }

  /**
   * Provides a UTC {@link Clock} bean for time-dependent operations.
   *
   * @return standard UTC system clock
   */
  @Bean
  public Clock clock() {
    return Clock.systemUTC();
  }
}

package dev.lmdb.actor.client;

import java.time.Duration;
import org.jspecify.annotations.NonNull;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.support.RestClientAdapter;
import org.springframework.web.service.invoker.HttpServiceProxyFactory;
import org.springframework.web.util.UriComponentsBuilder;

/**
 * HTTP client configuration for the TMDB API.
 *
 * <p>Defines one shared, rate-limited {@link RestClient} and builds {@link TmdbPersonClient} on top
 * of it — the single typed HTTP interface used by both the native {@code /api/v1/actors} API and
 * the TMDB v3 facade ({@code dev.lmdb.actor.facade}) as of ADR-010, mirroring movie-service's
 * client config.
 *
 * <p>The TMDB API key is injected as a default query parameter on every outbound request via a
 * {@link org.springframework.http.client.ClientHttpRequestInterceptor}, so business-layer code
 * never handles or even sees the key — it is a pure cross-cutting concern of the HTTP transport.
 */
@Configuration
public class TmdbClientConfig {

  private final TmdbProperties tmdbProperties;

  /**
   * @param tmdbProperties type-safe TMDB configuration
   */
  public TmdbClientConfig(TmdbProperties tmdbProperties) {
    this.tmdbProperties = tmdbProperties;
  }

  /**
   * The shared HTTP client for all TMDB traffic from this service: base URL, JSON headers, the
   * rate-limit interceptor, the API-key interceptor, and connect/read timeouts.
   *
   * @param builder Spring-provided builder
   * @param rateLimitInterceptor bucket-based throttle (40 req / 10 s)
   * @return shared TMDB RestClient
   */
  @Bean
  public RestClient tmdbRestClient(
      RestClient.Builder builder, @NonNull TmdbRateLimitInterceptor rateLimitInterceptor) {
    // Configure a request factory with explicit connect and read timeouts
    // so a hung TMDB connection cannot block a Tomcat thread indefinitely.
    org.springframework.http.client.SimpleClientHttpRequestFactory requestFactory =
        new org.springframework.http.client.SimpleClientHttpRequestFactory();
    requestFactory.setConnectTimeout(Duration.ofMillis(tmdbProperties.connectTimeout()));
    requestFactory.setReadTimeout(Duration.ofMillis(tmdbProperties.readTimeout()));

    // Build RestClient with baseUrl, standard JSON accept/content-type headers,
    // rate-limit interceptor, and a transparent API-key interceptor that appends
    // the server-side TMDB key as a query parameter on every outbound request.
    return builder
        .baseUrl(tmdbProperties.baseUrl())
        .defaultHeader("Accept", "application/json")
        .defaultHeader("Content-Type", "application/json")
        .requestFactory(requestFactory)
        .requestInterceptor(rateLimitInterceptor)
        .requestInterceptor(
            (request, body, execution) -> {
              // Append the server-side api_key to every TMDB request. This keeps the
              // key out of business code — callers never pass or know about it.
              var enrichedUri =
                  UriComponentsBuilder.fromUri(request.getURI())
                      .queryParam("api_key", tmdbProperties.key())
                      .build(true)
                      .toUri();
              return execution.execute(
                  new org.springframework.http.client.support.HttpRequestWrapper(request) {
                    @Override
                    public java.net.URI getURI() {
                      return enrichedUri;
                    }
                  },
                  body);
            })
        .build();
  }

  /**
   * Typed TMDB person HTTP interface backed by the shared RestClient.
   *
   * @param tmdbRestClient the shared client bean defined above
   * @return proxy implementing {@link TmdbPersonClient}
   */
  @Bean
  public TmdbPersonClient tmdbPersonClient(RestClient tmdbRestClient) {
    // Adapt RestClient for declarative HTTP interface and build factory.
    RestClientAdapter adapter = RestClientAdapter.create(tmdbRestClient);
    HttpServiceProxyFactory factory = HttpServiceProxyFactory.builderFor(adapter).build();

    // Instantiate the proxy implementation for TmdbPersonClient interface.
    return factory.createClient(TmdbPersonClient.class);
  }
}

package dev.lmdb.actor.client;

import dev.lmdb.actor.client.dto.TmdbPersonImagesResponse;
import dev.lmdb.actor.client.dto.TmdbPersonMovieCreditsResponse;
import dev.lmdb.actor.client.dto.TmdbPersonResponse;
import dev.lmdb.actor.client.dto.TmdbPersonSearchResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.service.annotation.GetExchange;
import org.springframework.web.service.annotation.HttpExchange;

/**
 * Typed HTTP client for the TMDB person endpoints. Backs both the native {@code /api/v1/actors} API
 * and the TMDB-shaped facade (ADR-010) — there is one client and one persisted dataset behind both,
 * matching movie-service's pattern.
 *
 * <p>The TMDB API key is injected transparently by the {@link
 * org.springframework.web.client.RestClient} interceptor configured in {@link TmdbClientConfig}, so
 * these method signatures carry only business-relevant parameters.
 */
@HttpExchange
public interface TmdbPersonClient {

  /**
   * Get person (actor) details by TMDB id.
   *
   * @param personId TMDB person id
   * @return person details
   */
  @GetExchange("/person/{personId}")
  TmdbPersonResponse getPersonDetails(@PathVariable("personId") Long personId);

  /**
   * Get a person's movie cast/crew credits.
   *
   * @param personId TMDB person id
   * @return movie credits
   */
  @GetExchange("/person/{personId}/movie_credits")
  TmdbPersonMovieCreditsResponse getPersonMovieCredits(@PathVariable("personId") Long personId);

  /**
   * Search people by name.
   *
   * @param query free-text name query
   * @param page page number (1-based)
   * @return paged person summaries
   */
  @GetExchange("/search/person")
  TmdbPersonSearchResponse searchPersons(
      @RequestParam("query") String query,
      @RequestParam(value = "page", defaultValue = "1") Integer page);

  /**
   * Get every profile image TMDB holds for a person.
   *
   * @param personId TMDB person id
   * @return profile-image references and their metadata
   */
  @GetExchange("/person/{personId}/images")
  TmdbPersonImagesResponse getPersonImages(@PathVariable("personId") Long personId);

  /**
   * Get the currently popular people, TMDB's ranking.
   *
   * @param page page number (1-based)
   * @return paged person summaries
   */
  @GetExchange("/person/popular")
  TmdbPersonSearchResponse getPopularPersons(
      @RequestParam(value = "page", defaultValue = "1") Integer page);
}

package dev.lmdb.actor.client;

import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import java.io.IOException;
import java.time.Duration;
import lombok.extern.slf4j.Slf4j;
import org.jspecify.annotations.NonNull;
import org.springframework.http.HttpRequest;
import org.springframework.http.client.ClientHttpRequestExecution;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.client.ClientHttpResponse;
import org.springframework.stereotype.Component;

/**
 * Throttles outbound TMDB requests to stay under TMDB's rate limit (40 requests / 10 seconds).
 *
 * <p>Mirrors movie-service's interceptor of the same name — each service instance holds its OWN
 * in-memory bucket, so the effective platform-wide ceiling is 40 req/10 s per service instance.
 * Deliberately duplicated rather than shared: services share contracts, not implementation
 * (microservice boundary discipline); the contract tests (#43) keep the copies honest.
 */
@Component
@Slf4j
public class TmdbRateLimitInterceptor implements ClientHttpRequestInterceptor {

  /** In-memory token bucket: 40 tokens, refilled every 10 seconds. */
  private final Bucket bucket;

  /** Builds the bucket with TMDB's published limit. */
  public TmdbRateLimitInterceptor() {
    Bandwidth limit =
        Bandwidth.builder().capacity(40).refillIntervally(40, Duration.ofSeconds(10)).build();
    this.bucket = Bucket.builder().addLimit(limit).build();
  }

  /**
   * Blocks until a token is available, then executes the request.
   *
   * @param request outbound request
   * @param body request body bytes
   * @param execution downstream execution chain
   * @return the upstream response
   * @throws IOException if interrupted while waiting or on I/O failure
   */
  @Override
  @NonNull
  public ClientHttpResponse intercept(
      @NonNull HttpRequest request,
      byte @NonNull [] body,
      @NonNull ClientHttpRequestExecution execution)
      throws IOException {
    try {
      // Block the calling thread until a token frees — better a slow
      // response than a 429 from TMDB.
      log.debug("Awaiting TMDB rate limit token for: {}", request.getURI());
      bucket.asBlocking().consume(1);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      log.error("Rate limit wait interrupted", e);
      throw new IOException("Request interrupted while waiting for rate limit token", e);
    }

    // Execute outbound HTTP request downstream once rate limit token has been consumed.
    return execution.execute(request, body);
  }
}

package dev.lmdb.actor.controller;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.linkTo;
import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.methodOn;

import dev.lmdb.actor.dto.ActorDtos.ActorDto;
import dev.lmdb.actor.dto.ActorDtos.ActorImageDto;
import dev.lmdb.actor.dto.ActorDtos.ActorSearchResponse;
import dev.lmdb.actor.dto.ActorDtos.FilmographyPageDto;
import dev.lmdb.actor.service.ActorService;
import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.shared.dto.HalResource;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Native typed actor endpoints (issue #18): profile, filmography, search. Uses the shared {@link
 * ApiResponse} envelope like every native LMDB endpoint; the TMDB-shaped facade lives separately in
 * {@code PersonFacadeController}.
 */
@RestController
@RequestMapping("/api/v1/actors")
@RequiredArgsConstructor
@Tag(name = "Actors", description = "Actor profiles, filmography and search")
public class ActorController {

  private final ActorService actorService;

  /**
   * Returns a typed actor profile.
   *
   * @param id TMDB person id
   * @return 200 with the profile
   */
  @GetMapping("/{id}")
  @Operation(summary = "Get actor details by TMDB person id")
  public ResponseEntity<ApiResponse<HalResource<ActorDto>>> getActor(@PathVariable Long id) {
    // HATEOAS: the profile advertises links to itself and its filmography
    // sub-resource, so a client discovers navigation instead of building URLs.
    HalResource<ActorDto> model =
        HalResource.of(actorService.getActor(id))
            .withLink(
                "self",
                linkTo(methodOn(ActorController.class).getActor(id)).withSelfRel().getHref())
            .withLink(
                "movies",
                linkTo(methodOn(ActorController.class).getFilmography(id, 1, 20))
                    .withRel("movies")
                    .getHref())
            .withLink(
                "images",
                linkTo(methodOn(ActorController.class).getImages(id)).withRel("images").getHref());
    return ok(model, "Actor retrieved");
  }

  /**
   * Returns a page of an actor's filmography, newest release first.
   *
   * <p>Paged here even though TMDB's own {@code movie_credits} is not: this is LMDB's native API,
   * so it can page, while the facade keeps serving TMDB's exact unpaginated shape.
   *
   * @param id TMDB person id
   * @param page 1-based page number
   * @param size credits per page
   * @return 200 with one page of cast credits
   */
  @GetMapping("/{id}/movies")
  @Operation(summary = "Get a page of an actor's filmography")
  public ResponseEntity<ApiResponse<FilmographyPageDto>> getFilmography(
      @PathVariable Long id,
      @RequestParam(defaultValue = "1") int page,
      @RequestParam(defaultValue = "20") int size) {
    // Retrieve paged filmography from service (sorted newest first) and wrap in success envelope.
    return ok(actorService.getFilmographyPage(id, page, size), "Filmography retrieved");
  }

  /**
   * Returns every profile image TMDB knows for an actor.
   *
   * @param id TMDB person id
   * @return 200 with image references (empty list if TMDB has none)
   */
  @GetMapping("/{id}/images")
  @Operation(summary = "Get an actor's profile images")
  public ResponseEntity<ApiResponse<List<ActorImageDto>>> getImages(@PathVariable Long id) {
    // Fetch persisted or read-through profile image references for the actor.
    return ok(actorService.getImages(id), "Images retrieved");
  }

  /**
   * Returns the currently popular actors.
   *
   * <p>Mapped before {@code /{id}} by Spring's literal-over-template precedence, so "popular" is
   * never parsed as an id.
   *
   * @param page TMDB page number (1-based)
   * @return 200 with paged summaries
   */
  @GetMapping("/popular")
  @Operation(summary = "Get popular actors")
  public ResponseEntity<ApiResponse<ActorSearchResponse>> getPopular(
      @RequestParam(defaultValue = "1") int page) {
    // Query TMDB popular actors, upsert stub entries, and return native response shape.
    return ok(actorService.getPopular(page), "Popular actors retrieved");
  }

  /**
   * Searches actors by name.
   *
   * @param query free-text name query
   * @param page TMDB page number (1-based)
   * @return 200 with paged summaries
   */
  @GetMapping("/search")
  @Operation(summary = "Search actors by name")
  public ResponseEntity<ApiResponse<ActorSearchResponse>> search(
      @RequestParam String query, @RequestParam(defaultValue = "1") int page) {
    // Perform actor name search against TMDB, upserting results to local database.
    return ok(actorService.search(query, page), "Search completed");
  }

  /**
   * Wraps a payload in the shared success envelope.
   *
   * @param data payload
   * @param message human-readable outcome
   * @param <T> payload type
   * @return 200 response
   */
  private static <T> ResponseEntity<ApiResponse<T>> ok(T data, String message) {
    // Construct 200 OK HTTP response containing the standard ApiResponse envelope.
    return ResponseEntity.ok(ApiResponse.success(data, message, HttpStatus.OK.value()));
  }
}

package dev.lmdb.actor.controller;

import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.shared.exception.ResourceNotFoundException;
import dev.lmdb.shared.exception.ServiceUnavailableException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClientResponseException;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

/**
 * Maps exceptions on the NATIVE {@code /api/v1} endpoints to the shared {@link ApiResponse} error
 * envelope.
 *
 * <p>Scoped to the controller package so it does not intercept the facade's own
 * {@code @ExceptionHandler}s in {@code PersonFacadeController} — facade errors must stay
 * TMDB-shaped, native errors stay ApiResponse-shaped.
 */
@RestControllerAdvice(basePackages = "dev.lmdb.actor.controller")
@Order(1)
@Slf4j
public class GlobalExceptionHandler {

  /**
   * TMDB rejected the underlying fetch (e.g. unknown person id) → mirror the upstream status with a
   * native-shaped body.
   *
   * @param e upstream error captured by Spring's RestClient
   * @return error envelope with TMDB's status code
   */
  @ExceptionHandler(RestClientResponseException.class)
  public ResponseEntity<ApiResponse<Void>> handleUpstream(RestClientResponseException e) {
    // Forward HTTP status code received from upstream TMDB in an ApiResponse envelope.
    return error(
        HttpStatus.valueOf(e.getStatusCode().value()),
        "TMDB rejected the request (HTTP " + e.getStatusCode().value() + ")");
  }

  /**
   * TMDB unreachable with no cached copy → 503.
   *
   * @param e network failure
   * @return 503 error envelope
   */
  @ExceptionHandler({ResourceAccessException.class, ServiceUnavailableException.class})
  public ResponseEntity<ApiResponse<Void>> handleUnavailable(Exception e) {
    // Log connection or service failure details and return 503 Service Unavailable.
    log.error("Upstream unavailable: {}", e.getMessage());
    return error(HttpStatus.SERVICE_UNAVAILABLE, "Actor data is temporarily unavailable");
  }

  /**
   * Missing local resources → 404.
   *
   * @param e not-found error
   * @return 404 error envelope
   */
  @ExceptionHandler(ResourceNotFoundException.class)
  public ResponseEntity<ApiResponse<Void>> handleNotFound(ResourceNotFoundException e) {
    // Return 404 Not Found with the exception's detailed error message.
    return error(HttpStatus.NOT_FOUND, e.getMessage());
  }

  /**
   * A path variable or query param that won't convert to its declared type (e.g. {@code
   * /api/v1/actors/popular} before {@code /popular} had its own mapping, or any non-numeric actor
   * id) → 400, not 500. Spring raises this before the controller runs, so without this handler it
   * would fall through to {@link #handleUnexpected} and report a server fault for what is really a
   * malformed client request.
   *
   * @param e the type-conversion failure
   * @return 400 error envelope naming the offending parameter
   */
  @ExceptionHandler(MethodArgumentTypeMismatchException.class)
  public ResponseEntity<ApiResponse<Void>> handleTypeMismatch(
      MethodArgumentTypeMismatchException e) {
    // Map parameter conversion failures to a client-friendly 400 Bad Request.
    return error(
        HttpStatus.BAD_REQUEST, "Invalid value for '" + e.getName() + "': expected a number");
  }

  /**
   * Anything unanticipated → 500 with a generic message (detail logged).
   *
   * @param e unexpected error
   * @return 500 error envelope
   */
  @ExceptionHandler(Exception.class)
  public ResponseEntity<ApiResponse<Void>> handleUnexpected(Exception e) {
    // Log full stack trace for unexpected exceptions and return generic 500 Internal Server Error.
    log.error("Unhandled exception in actor-service", e);
    return error(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected error occurred");
  }

  /**
   * Builds the standard error response.
   *
   * @param status HTTP status
   * @param message client-safe description
   * @return error envelope response
   */
  private static ResponseEntity<ApiResponse<Void>> error(HttpStatus status, String message) {
    // Assemble ResponseEntity with given HTTP status and ApiResponse error body.
    return ResponseEntity.status(status).body(ApiResponse.error(message, status.value()));
  }
}

package dev.lmdb.actor.facade;

import com.fasterxml.jackson.annotation.JsonProperty;
import dev.lmdb.actor.client.dto.TmdbPersonImagesResponse;
import dev.lmdb.actor.client.dto.TmdbPersonMovieCreditsResponse;
import dev.lmdb.actor.mapper.ActorMapper;
import dev.lmdb.actor.model.Actor;
import dev.lmdb.actor.service.ActorService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClientResponseException;

/**
 * TMDB v3-compatible person facade — actor-service's slice of the primary API (ARCHITECTURE.md §5.1
 * row 8, issues #18/#32).
 *
 * <p>The LMDB React app calls {@code GET /person/{id}} for actor pages. As of ADR-010 (supersedes
 * ADR-003), this serves TMDB's exact field names/shape but the data behind it is {@link
 * ActorService}'s persisted, mapped {@link Actor} catalog — not a raw cached copy of TMDB's bytes.
 * Discover-by-cast ({@code /discover/movie?with_cast=}) is intentionally NOT here — it is a
 * movie-list endpoint and lives in movie-service's facade (#31).
 */
@RestController
@Slf4j
@RequiredArgsConstructor
public class PersonFacadeController {

  /** Logged whenever a non-numeric path id is rejected without reaching TMDB. */
  private static final String REJECTING_NON_NUMERIC_ID =
      "Person facade: rejecting non-numeric id '{}'";

  private final ActorService actorService;
  private final ActorMapper actorMapper;

  /**
   * {@code GET /person/{id}} — person details in TMDB's exact shape, read-through/save-through
   * against the persisted {@link Actor} catalog.
   *
   * @param id numeric TMDB person id (non-numeric → local TMDB-shaped 404)
   * @return TMDB-shaped person JSON
   */
  @GetMapping(value = "/person/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> personDetails(@PathVariable String id) {
    // Reject non-numeric person IDs locally with TMDB-shaped 404 response.
    if (!id.chars().allMatch(Character::isDigit)) {
      log.debug(REJECTING_NON_NUMERIC_ID, id);
      return notFound();
    }

    // Fetch entity locally or from TMDB and map to TMDB's expected person JSON.
    Actor actor = actorService.getOrFetchActorEntity(Long.parseLong(id));
    return ResponseEntity.ok(actorMapper.toTmdbPersonResponse(actor));
  }

  /**
   * {@code GET /person/{id}/movie_credits} — the actor's filmography in TMDB's exact shape. Always
   * live: the referenced movies belong to movie-service's own database (ADR-002).
   *
   * @param id numeric TMDB person id
   * @return TMDB-shaped movie-credits JSON
   */
  @GetMapping(value = "/person/{id}/movie_credits", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> movieCredits(@PathVariable String id) {
    // Validate numeric ID format before querying upstream.
    if (!id.chars().allMatch(Character::isDigit)) {
      log.debug(REJECTING_NON_NUMERIC_ID, id);
      return notFound();
    }

    // Retrieve raw filmography from TMDB client.
    TmdbPersonMovieCreditsResponse credits = actorService.getFilmographyRaw(Long.parseLong(id));
    return ResponseEntity.ok(credits);
  }

  /**
   * {@code GET /person/{id}/images} — the actor's profile images in TMDB's exact shape,
   * read-through/save-through against the persisted catalog. Only TMDB CDN references are stored,
   * never the image bytes (ARCHITECTURE.md §3.8).
   *
   * @param id numeric TMDB person id
   * @return TMDB-shaped person-images JSON
   */
  @GetMapping(value = "/person/{id}/images", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> personImages(@PathVariable String id) {
    // Validate numeric ID format.
    if (!id.chars().allMatch(Character::isDigit)) {
      log.debug(REJECTING_NON_NUMERIC_ID, id);
      return notFound();
    }

    long personId = Long.parseLong(id);
    // Map persisted images into TMDB facade profile image DTOs via MapStruct.
    var profiles = actorMapper.toTmdbProfileImages(actorService.getOrFetchImages(personId));
    return ResponseEntity.ok(new TmdbPersonImagesResponse(personId, profiles));
  }

  /**
   * {@code GET /person/popular} — TMDB's popular-people ranking, in TMDB's exact shape. Live
   * upstream call (TMDB's popularity ordering isn't reimplemented here), but every person returned
   * is upserted into the local catalog.
   *
   * @param page 1-based page number
   * @return TMDB-shaped popular-people JSON
   */
  @GetMapping(value = "/person/popular", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> popularPersons(@RequestParam(defaultValue = "1") int page) {
    // Fetch raw popular persons response from service (upserting returned entries).
    return ResponseEntity.ok(actorService.getPopularRaw(page));
  }

  /**
   * {@code GET /search/person} — TMDB's person search, in TMDB's exact shape. Live ranking call;
   * results are upserted as stubs.
   *
   * @param query free-text name query
   * @param page 1-based page number
   * @return TMDB-shaped person-search JSON
   */
  @GetMapping(value = "/search/person", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> searchPersons(
      @RequestParam String query, @RequestParam(defaultValue = "1") int page) {
    // Fetch raw person search response from service (upserting returned entries).
    return ResponseEntity.ok(actorService.searchRaw(query, page));
  }

  /**
   * Replays a real TMDB error response byte-for-byte: {@link
   * dev.lmdb.actor.client.TmdbPersonClient} calls go through Spring's RestClient, which captures
   * the upstream body on a non-2xx response — reusing it preserves TMDB's exact error shape.
   *
   * @param e the captured upstream HTTP error
   * @return response mirroring TMDB's error exactly
   */
  @ExceptionHandler(RestClientResponseException.class)
  public ResponseEntity<String> upstreamError(RestClientResponseException e) {
    // Forward upstream HTTP status and verbatim error body string.
    return ResponseEntity.status(e.getStatusCode())
        .contentType(MediaType.APPLICATION_JSON)
        .body(e.getResponseBodyAsString());
  }

  /**
   * Maps "TMDB unreachable" to 502 Bad Gateway with a TMDB-shaped error body.
   *
   * @param e network failure reaching TMDB
   * @return 502 response with TMDB-style error JSON
   */
  @ExceptionHandler(ResourceAccessException.class)
  public ResponseEntity<TmdbErrorResponse> tmdbUnreachable(ResourceAccessException e) {
    // Log network error and return 502 Bad Gateway using TMDB error envelope.
    log.error("TMDB unreachable: {}", e.getMessage());
    return ResponseEntity.status(502)
        .body(new TmdbErrorResponse(false, 502, "Upstream TMDB API is unreachable."));
  }

  /**
   * Returns a 404 Not Found response formatted as TMDB's standard error JSON structure.
   *
   * @return 404 response with TMDB error status code 34
   */
  private static ResponseEntity<Object> notFound() {
    // Build 404 response matching TMDB's status code 34 error message.
    return ResponseEntity.status(HttpStatus.NOT_FOUND)
        .body(new TmdbErrorResponse(false, 34, "The resource you requested could not be found."));
  }

  /**
   * TMDB's own error envelope shape, replayed for locally-detected error cases that don't have a
   * captured upstream body to forward verbatim.
   *
   * @param success always false
   * @param statusCode TMDB's numeric status code (not the HTTP status)
   * @param statusMessage human-readable message
   */
  record TmdbErrorResponse(
      boolean success,
      @JsonProperty("status_code") int statusCode,
      @JsonProperty("status_message") String statusMessage) {}
}

package dev.lmdb.actor.mapper;

import dev.lmdb.actor.client.dto.TmdbPersonImagesResponse.TmdbProfileImage;
import dev.lmdb.actor.client.dto.TmdbPersonMovieCreditsResponse.TmdbCastCredit;
import dev.lmdb.actor.client.dto.TmdbPersonResponse;
import dev.lmdb.actor.client.dto.TmdbPersonSearchResponse.TmdbPersonSummary;
import dev.lmdb.actor.dto.ActorDtos.ActorDto;
import dev.lmdb.actor.dto.ActorDtos.ActorImageDto;
import dev.lmdb.actor.dto.ActorDtos.ActorSummaryDto;
import dev.lmdb.actor.dto.ActorDtos.FilmographyEntryDto;
import dev.lmdb.actor.model.Actor;
import dev.lmdb.actor.model.ActorProfileImage;
import java.util.List;
import org.mapstruct.BeanMapping;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValuePropertyMappingStrategy;

/**
 * MapStruct mapper encapsulating all conversions between TMDB API records, domain {@link Actor}
 * entities, and native API DTOs.
 *
 * <p>Generates type-safe mapping code at build time, replacing manual field-by-field copying while
 * preserving zero-reflection execution speed.
 */
@Mapper(componentModel = "spring")
public interface ActorMapper {

  /**
   * Converts a domain {@link Actor} entity into a native {@link ActorDto}.
   *
   * @param actor entity
   * @return DTO representation
   */
  ActorDto toDto(Actor actor);

  /**
   * Converts a TMDB person detail response into an unpersisted domain {@link Actor} entity.
   *
   * @param response TMDB person detail record
   * @return domain entity
   */
  @Mapping(source = "id", target = "tmdbId")
  @Mapping(source = "birthday", target = "birthDate")
  @Mapping(source = "placeOfBirth", target = "birthPlace")
  @Mapping(target = "biography", defaultValue = "")
  @Mapping(target = "profileImages", ignore = true)
  @Mapping(target = "syncedAt", expression = "java(java.time.LocalDateTime.now())")
  Actor toEntity(TmdbPersonResponse response);

  /**
   * Converts a domain {@link Actor} entity into a TMDB person detail response shape for facade
   * serialization.
   *
   * @param actor entity
   * @return TMDB response record shape
   */
  @Mapping(source = "tmdbId", target = "id")
  @Mapping(source = "birthDate", target = "birthday")
  @Mapping(source = "birthPlace", target = "placeOfBirth")
  TmdbPersonResponse toTmdbPersonResponse(Actor actor);

  /**
   * Maps a single search result summary to a native {@link ActorSummaryDto}.
   *
   * @param summary TMDB summary record
   * @return native summary DTO
   */
  @Mapping(source = "id", target = "tmdbId")
  ActorSummaryDto toSummaryDto(TmdbPersonSummary summary);

  /**
   * Maps a list of TMDB search result summaries to a list of native {@link ActorSummaryDto}s.
   *
   * @param summaries TMDB summary records
   * @return native summary DTOs
   */
  List<ActorSummaryDto> toSummaryDtos(List<TmdbPersonSummary> summaries);

  /**
   * Maps a single TMDB cast credit to a native {@link FilmographyEntryDto}.
   *
   * @param credit TMDB cast credit record
   * @return native filmography entry DTO
   */
  @Mapping(source = "id", target = "movieId")
  @Mapping(target = "releaseDate", defaultValue = "")
  FilmographyEntryDto toFilmographyEntryDto(TmdbCastCredit credit);

  /**
   * Maps a list of TMDB cast credits to a list of native {@link FilmographyEntryDto}s.
   *
   * @param credits TMDB cast credit records
   * @return native filmography entry DTOs
   */
  List<FilmographyEntryDto> toFilmographyEntryDtos(List<TmdbCastCredit> credits);

  /**
   * Maps a domain {@link ActorProfileImage} to a native {@link ActorImageDto}.
   *
   * @param image domain profile image value object
   * @return native image DTO
   */
  ActorImageDto toImageDto(ActorProfileImage image);

  /**
   * Maps a list of domain {@link ActorProfileImage}s to a list of native {@link ActorImageDto}s.
   *
   * @param images domain profile image value objects
   * @return native image DTOs
   */
  List<ActorImageDto> toImageDtos(List<ActorProfileImage> images);

  /**
   * Maps a TMDB profile image response record to a domain {@link ActorProfileImage} value object.
   *
   * @param profile TMDB profile image record
   * @return domain profile image value object
   */
  ActorProfileImage toProfileImageEntity(TmdbProfileImage profile);

  /**
   * Maps a list of TMDB profile image response records to a list of domain {@link
   * ActorProfileImage}s.
   *
   * @param profiles TMDB profile image records
   * @return domain profile image value objects
   */
  List<ActorProfileImage> toProfileImageEntities(List<TmdbProfileImage> profiles);

  /**
   * Maps a domain {@link ActorProfileImage} to a TMDB facade {@link TmdbProfileImage} record.
   *
   * @param image domain profile image value object
   * @return TMDB profile image record
   */
  TmdbProfileImage toTmdbProfileImage(ActorProfileImage image);

  /**
   * Maps a list of domain {@link ActorProfileImage}s to a list of TMDB facade {@link
   * TmdbProfileImage} records.
   *
   * @param images domain profile image value objects
   * @return TMDB profile image records
   */
  List<TmdbProfileImage> toTmdbProfileImages(List<ActorProfileImage> images);

  /**
   * Partially updates an existing {@link Actor} entity from a search summary stub, ignoring null
   * source fields so that existing detailed profile fields (biography, birth date, etc.) are left
   * untouched.
   *
   * @param summary search summary record (source)
   * @param actor domain entity to update in place (target)
   */
  @BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE)
  @Mapping(source = "id", target = "tmdbId")
  @Mapping(target = "syncedAt", ignore = true)
  @Mapping(target = "biography", ignore = true)
  @Mapping(target = "birthDate", ignore = true)
  @Mapping(target = "birthPlace", ignore = true)
  @Mapping(target = "alsoKnownAs", ignore = true)
  @Mapping(target = "profileImages", ignore = true)
  @Mapping(target = "imdbId", ignore = true)
  @Mapping(target = "homepage", ignore = true)
  void updateEntityFromSummary(TmdbPersonSummary summary, @MappingTarget Actor actor);
}

package dev.lmdb.actor.model;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * A typed, queryable actor profile — the persisted source of truth behind both the native {@code
 * /api/v1/actors} API and the TMDB-shaped facade (ADR-010): a detail fetch from either surface maps
 * TMDB's response into this entity and saves it, and later requests read it back instead of
 * re-fetching. Search results are also upserted (lightweight stubs), so the dataset grows from any
 * endpoint that returns an actor, mirroring movie-service's {@code Movie} entity.
 *
 * <p>DELIBERATE DEVIATION from the original §3.6 sketch: no {@code @ManyToMany} actor↔movie join
 * table. Movies live in movie-service's database (database-per-service, ADR-002) — a local join
 * table would duplicate foreign data with no owner. Filmography is served live from TMDB's {@code
 * person/{id}/movie_credits} on every request instead (like movie-service's list endpoints, TMDB's
 * data isn't re-hosted here).
 */
@Entity
@Table(name = "actors")
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Actor implements Serializable {

  /** TMDB person id — natural primary key (no surrogate needed). */
  @Id
  @Column(name = "tmdb_id")
  private Long tmdbId;

  /** Actor's name. */
  @Column(nullable = false, length = 255)
  private String name;

  /** Biography text (TMDB serves long ones — unbounded TEXT). */
  @Column(columnDefinition = "text")
  private String biography;

  /** Birth date, if TMDB knows it. */
  @Column(name = "birth_date")
  private LocalDate birthDate;

  /** Birthplace, if TMDB knows it. */
  @Column(name = "birth_place", length = 255)
  private String birthPlace;

  /** TMDB profile image path (client builds the full image URL). */
  @Column(name = "profile_path", length = 255)
  private String profilePath;

  /** TMDB popularity score at last sync. */
  @Column private Double popularity;

  /**
   * Alternate names TMDB knows this person by (stage names, aliases). EAGER: small collection,
   * always needed alongside the rest of the profile, and read outside the service's transaction
   * boundary by the facade controller — LAZY (the JPA default for element collections) would throw
   * LazyInitializationException there.
   */
  @ElementCollection(fetch = FetchType.EAGER)
  @CollectionTable(name = "actor_also_known_as", joinColumns = @JoinColumn(name = "actor_tmdb_id"))
  @Column(name = "also_known_as")
  private List<String> alsoKnownAs;

  /**
   * Every profile image TMDB knows for this person (CDN references only — see {@link
   * ActorProfileImage}). EAGER for the same reason as {@link #alsoKnownAs}: the facade's images
   * endpoint reads it outside the service's transaction boundary, where LAZY would throw
   * LazyInitializationException.
   */
  @ElementCollection(fetch = FetchType.EAGER)
  @CollectionTable(name = "actor_profile_images", joinColumns = @JoinColumn(name = "actor_tmdb_id"))
  private List<ActorProfileImage> profileImages;

  /** TMDB's primary department for this person (e.g. "Acting", "Directing"). */
  @Column(name = "known_for_department", length = 100)
  private String knownForDepartment;

  /** TMDB's gender code: 0 = not specified, 1 = female, 2 = male, 3 = non-binary. */
  @Column private Integer gender;

  /** IMDB id, if TMDB knows it. */
  @Column(name = "imdb_id", length = 20)
  private String imdbId;

  /** Personal/official homepage URL, if TMDB knows it. */
  @Column(length = 512)
  private String homepage;

  /** Adult-content flag as TMDB reports it. */
  @Column private Boolean adult;

  /** When this row was last refreshed from a TMDB document. */
  @Column(name = "synced_at", nullable = false)
  private LocalDateTime syncedAt;
}

package dev.lmdb.actor.model;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.io.Serializable;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * One profile image TMDB knows for an actor, persisted as part of {@link Actor}'s image set so
 * {@code GET /person/{id}/images} is served from actor-service's own data (ADR-010) rather than
 * proxied.
 *
 * <p>Stores TMDB's CDN <em>reference</em> and metadata only — never the image bytes
 * (ARCHITECTURE.md §3.8). Clients resolve {@code filePath} against {@code image.tmdb.org}
 * themselves, exactly as they do with the real API.
 */
@Embeddable
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ActorProfileImage implements Serializable {

  /** TMDB CDN path, e.g. {@code /kU3B75TyRiCgE270EyZnHjfivoq.jpg}. */
  @Column(name = "file_path", nullable = false, length = 255)
  private String filePath;

  /** Width divided by height, as TMDB reports it. */
  @Column(name = "aspect_ratio")
  private Double aspectRatio;

  /** Image height in pixels. */
  @Column private Integer height;

  /** Image width in pixels. */
  @Column private Integer width;

  /** ISO 639-1 language tag, null for language-neutral images. */
  @Column(name = "iso_639_1", length = 10)
  private String iso6391;

  /** TMDB community vote average for this image. */
  @Column(name = "vote_average")
  private Double voteAverage;

  /** Number of TMDB community votes for this image. */
  @Column(name = "vote_count")
  private Integer voteCount;
}

package dev.lmdb.actor.repository;

import dev.lmdb.actor.model.Actor;
import org.springframework.data.jpa.repository.JpaRepository;

/** JPA repository for typed {@link Actor} profiles (keyed by TMDB person id). */
public interface ActorRepository extends JpaRepository<Actor, Long> {}

package dev.lmdb.actor.service;

import dev.lmdb.actor.client.TmdbPersonClient;
import dev.lmdb.actor.client.dto.TmdbPersonImagesResponse;
import dev.lmdb.actor.client.dto.TmdbPersonMovieCreditsResponse;
import dev.lmdb.actor.client.dto.TmdbPersonResponse;
import dev.lmdb.actor.client.dto.TmdbPersonSearchResponse;
import dev.lmdb.actor.dto.ActorDtos.ActorDto;
import dev.lmdb.actor.dto.ActorDtos.ActorImageDto;
import dev.lmdb.actor.dto.ActorDtos.ActorSearchResponse;
import dev.lmdb.actor.dto.ActorDtos.ActorSummaryDto;
import dev.lmdb.actor.dto.ActorDtos.FilmographyEntryDto;
import dev.lmdb.actor.dto.ActorDtos.FilmographyPageDto;
import dev.lmdb.actor.mapper.ActorMapper;
import dev.lmdb.actor.model.Actor;
import dev.lmdb.actor.model.ActorProfileImage;
import dev.lmdb.actor.repository.ActorRepository;
import java.time.Clock;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.Cache;
import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Native typed actor API (ARCHITECTURE.md §3.6, issue #18) and the backing service for the
 * TMDB-shaped facade — one persisted dataset behind both, as of ADR-010 (supersedes ADR-003's
 * raw-passthrough design).
 *
 * <p>Detail lookups are read-through/save-through against PostgreSQL (the {@link Actor} table): a
 * fetch maps TMDB's response into the typed entity and saves it, and a later request for the same
 * id is served locally, no TMDB call. Search results are also upserted (lightweight stubs — name,
 * profile path, popularity only), so the dataset grows from any endpoint that returns an actor.
 * Filmography stays a live TMDB call on every request: the movies it references live in
 * movie-service's own database (ADR-002), so there is nothing of actor-service's to persist there.
 *
 * <p>The TMDB API key is no longer handled here — it is injected transparently by the {@link
 * org.springframework.web.client.RestClient} interceptor configured in {@link
 * dev.lmdb.actor.client.TmdbClientConfig}, keeping this class focused on orchestration rather than
 * transport concerns.
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class ActorService {

  private final TmdbPersonClient tmdbPersonClient;
  private final ActorRepository actorRepository;
  private final ActorMapper actorMapper;
  private final Clock clock;
  private final CacheManager cacheManager;

  /**
   * Fetches an actor profile, read-through/save-through against PostgreSQL.
   *
   * @param tmdbId TMDB person id
   * @return typed actor profile
   */
  @Transactional
  public ActorDto getActor(Long tmdbId) {
    // Retrieve or fetch actor entity via internal helper and convert to DTO response.
    return actorMapper.toDto(fetchActorEntity(tmdbId));
  }

  /**
   * Core read-through/save-through lookup shared by the native API and the facade: PostgreSQL
   * first, TMDB on miss, save-through on fetch.
   *
   * <p>Results are cached in Redis ({@code actors} cache region) so that repeated lookups for the
   * same person skip both PostgreSQL and TMDB entirely. The cache is evicted when an upsert
   * modifies the entity (see {@link #upsertFromSearchResult}). Single-flight {@code sync = true}
   * prevents cache stampedes on concurrent misses.
   *
   * @param tmdbId TMDB person id
   * @return the persisted (or freshly fetched-and-saved) actor entity
   */
  @Cacheable(value = "actors", key = "#tmdbId", sync = true)
  public Actor getOrFetchActorEntity(Long tmdbId) {
    return fetchActorEntity(tmdbId);
  }

  /**
   * Internal unannotated helper method for fetching actor entity to avoid proxy self-invocation.
   * Direct {@code this.} calls bypass the Spring AOP proxy, so {@code @Cacheable} is left to public
   * entry points.
   */
  private Actor fetchActorEntity(Long tmdbId) {
    // Consult local database first; if missing, fetch from upstream TMDB client and persist
    // locally.
    return actorRepository
        .findById(tmdbId)
        .orElseGet(
            () -> {
              log.info("Actor {} not in PostgreSQL, fetching from TMDB", tmdbId);
              TmdbPersonResponse response = tmdbPersonClient.getPersonDetails(tmdbId);
              return convertAndSaveActor(response);
            });
  }

  /**
   * Fetches an actor's filmography from TMDB's {@code movie_credits}, newest release first.
   *
   * @param tmdbId TMDB person id
   * @return cast credits sorted by release date descending
   */
  public List<FilmographyEntryDto> getFilmography(Long tmdbId) {
    // Map raw cast credits to native DTO entries via MapStruct and sort newest release first.
    List<FilmographyEntryDto> entries =
        new ArrayList<>(actorMapper.toFilmographyEntryDtos(getFilmographyRaw(tmdbId).cast()));

    // Newest releases first; undated entries sink to the end.
    entries.sort(
        Comparator.comparing(
            FilmographyEntryDto::releaseDate, Comparator.nullsLast(Comparator.reverseOrder())));
    return entries;
  }

  /**
   * Returns one page of an actor's filmography.
   *
   * <p>Paginated in memory on purpose: TMDB's {@code movie_credits} has no page parameter — it
   * returns every credit in one response — so the facade must keep serving the unpaginated shape
   * while the native API still offers paging (issue #18). Requesting a page past the end yields an
   * empty page rather than an error, matching TMDB's list behavior.
   *
   * @param tmdbId TMDB person id
   * @param page 1-based page number
   * @param pageSize credits per page
   * @return the requested page of credits, newest release first
   */
  public FilmographyPageDto getFilmographyPage(Long tmdbId, int page, int pageSize) {
    // Fetch full sorted filmography list and calculate in-memory subList boundaries.
    List<FilmographyEntryDto> all = getFilmography(tmdbId);
    int totalPages = (int) Math.ceil((double) all.size() / pageSize);
    int from = Math.min((page - 1) * pageSize, all.size());
    int to = Math.min(from + pageSize, all.size());
    return new FilmographyPageDto(page, totalPages, all.size(), all.subList(from, to));
  }

  /**
   * Returns an actor's profile images, read-through/save-through against PostgreSQL like the
   * profile itself: fetched from TMDB once, persisted on the {@link Actor}, and served locally
   * afterwards (ADR-010).
   *
   * <p>Transactional and mapped to DTOs before returning, so the EAGER image collection is fully
   * resolved inside the transaction.
   *
   * @param tmdbId TMDB person id
   * @return the actor's profile-image references
   */
  @Transactional
  public List<ActorImageDto> getImages(Long tmdbId) {
    // Transform domain profile image entities into DTO representations via MapStruct.
    return actorMapper.toImageDtos(fetchImages(tmdbId));
  }

  /**
   * Core read-through/save-through image lookup shared by the native API and the facade. An actor
   * row with no persisted images triggers one TMDB fetch, which is then saved onto the actor.
   *
   * <p>Results are cached in Redis ({@code actor-images} cache region) with single-flight {@code
   * sync = true}.
   *
   * @param tmdbId TMDB person id
   * @return persisted profile images (empty if TMDB has none)
   */
  @Cacheable(value = "actor-images", key = "#tmdbId", sync = true)
  public List<ActorProfileImage> getOrFetchImages(Long tmdbId) {
    return fetchImages(tmdbId);
  }

  /**
   * Internal unannotated helper method for fetching actor images to avoid proxy self-invocation.
   */
  private List<ActorProfileImage> fetchImages(Long tmdbId) {
    // Check if profile images are already persisted on the actor entity; fetch from TMDB if absent.
    Actor actor = fetchActorEntity(tmdbId);
    if (actor.getProfileImages() != null && !actor.getProfileImages().isEmpty()) {
      return actor.getProfileImages();
    }

    log.info("Actor {} has no persisted images, fetching from TMDB", tmdbId);
    TmdbPersonImagesResponse response = tmdbPersonClient.getPersonImages(tmdbId);
    List<ActorProfileImage> images =
        response.profiles() == null
            ? List.of()
            : actorMapper.toProfileImageEntities(response.profiles());

    // Update the actor entity with the fetched images and save back to PostgreSQL.
    actor.setProfileImages(new ArrayList<>(images));
    actorRepository.save(actor);
    return actor.getProfileImages();
  }

  /**
   * Returns TMDB's currently-popular people. Like search, this is a live ranking call — TMDB's
   * popularity ordering isn't reimplemented here — but every person it returns is upserted, so the
   * local catalog grows.
   *
   * @param page TMDB page (1-based)
   * @return paged summaries
   */
  public ActorSearchResponse getPopular(int page) {
    // Map raw TMDB popular response into native ActorSearchResponse envelope.
    return toSearchResponse(getPopularRaw(page), page);
  }

  /**
   * Facade-facing popular-people lookup — TMDB's own response shape. Every result is upserted.
   *
   * @param page page number
   * @return raw TMDB popular-people response
   */
  public TmdbPersonSearchResponse getPopularRaw(int page) {
    log.info("Fetching popular actors: page={}", page);
    // Call TMDB popular persons endpoint and upsert each returned actor summary.
    TmdbPersonSearchResponse response = tmdbPersonClient.getPopularPersons(page);
    response.results().forEach(this::upsertFromSearchResult);
    return response;
  }

  /**
   * Facade-facing filmography lookup — TMDB's own response shape. Always live: the referenced
   * movies are movie-service's data, not ours.
   *
   * @param tmdbId TMDB person id
   * @return raw TMDB movie-credits response
   */
  public TmdbPersonMovieCreditsResponse getFilmographyRaw(Long tmdbId) {
    log.info("Fetching filmography for person: {}", tmdbId);
    // Execute live TMDB API call to fetch movie credits for given person id.
    return tmdbPersonClient.getPersonMovieCredits(tmdbId);
  }

  /**
   * Searches actors by name via TMDB's person search. Every result is upserted as a lightweight
   * stub (name/profile/popularity only — a search hit doesn't carry the full profile TMDB's detail
   * endpoint does).
   *
   * @param query free-text name query
   * @param page TMDB page (1-based)
   * @return paged summaries
   */
  public ActorSearchResponse search(String query, int page) {
    // Execute raw TMDB search and map output to native search response DTO.
    return toSearchResponse(searchRaw(query, page), page);
  }

  /**
   * Maps TMDB's shared person-list envelope (search and popular use the same one) into the native
   * API's paged response, defaulting the paging fields TMDB may omit.
   *
   * @param response TMDB's person-list response
   * @param requestedPage page asked for, used when TMDB doesn't echo one back
   * @return native paged summaries
   */
  private ActorSearchResponse toSearchResponse(
      TmdbPersonSearchResponse response, int requestedPage) {
    // Convert list of TmdbPersonSummary items into ActorSummaryDto instances via MapStruct.
    List<ActorSummaryDto> actors = actorMapper.toSummaryDtos(response.results());
    return new ActorSearchResponse(
        response.page() != null ? response.page() : requestedPage,
        response.totalPages() != null ? response.totalPages() : 0,
        response.totalResults() != null ? response.totalResults() : 0,
        actors);
  }

  /**
   * Facade-facing search — TMDB's own response shape. Every result is upserted.
   *
   * @param query search query
   * @param page page number
   * @return raw TMDB person-search response
   */
  public TmdbPersonSearchResponse searchRaw(String query, int page) {
    log.info("Searching actors: query={}, page={}", query, page);
    // Call TMDB search endpoint and upsert each returned actor summary to database.
    TmdbPersonSearchResponse response = tmdbPersonClient.searchPersons(query, page);
    response.results().forEach(this::upsertFromSearchResult);
    return response;
  }

  /**
   * Upserts a person-list stub into PostgreSQL (used by both search and popular). List results
   * carry only a subset of the detail endpoint's profile, so an existing, more-detailed row
   * (biography, birth date, etc. from a prior detail fetch) is updated in place rather than
   * clobbered — and fields the list omits are left untouched instead of nulled.
   *
   * <p>Evicts the actor from the Redis cache so that the next read-through lookup serves the
   * freshly-updated data.
   *
   * @param summary a single result from a TMDB person-list endpoint
   */
  private void upsertFromSearchResult(TmdbPersonSearchResponse.TmdbPersonSummary summary) {
    // Retrieve existing actor entity if present to prevent clobbering existing detailed fields.
    Actor actor =
        actorRepository
            .findById(summary.id())
            .orElseGet(
                () -> {
                  Actor fresh = new Actor();
                  fresh.setTmdbId(summary.id());
                  return fresh;
                });

    // Partially update present summary attributes on the entity via MapStruct.
    actorMapper.updateEntityFromSummary(summary, actor);
    actor.setSyncedAt(LocalDateTime.now(clock));
    actorRepository.save(actor);

    // Evict cached entity from Redis so subsequent reads fetch the updated profile.
    evictActorCache(summary.id());
  }

  /**
   * Programmatically evicts an actor from Redis cache if a cache manager is active.
   *
   * @param tmdbId TMDB person id to evict
   */
  private void evictActorCache(Long tmdbId) {
    if (cacheManager != null) {
      Cache cache = cacheManager.getCache("actors");
      if (cache != null) {
        cache.evict(tmdbId);
      }
    }
  }

  /**
   * Converts a raw TMDB person response into an {@link Actor} entity and persists it to PostgreSQL.
   *
   * @param r the TMDB person response containing profile fields
   * @return the saved {@link Actor} entity
   */
  private Actor convertAndSaveActor(TmdbPersonResponse r) {
    // Map fields from TmdbPersonResponse record into new Actor entity via ActorMapper.
    Actor actor = actorMapper.toEntity(r);
    actor.setSyncedAt(LocalDateTime.now(clock));
    Actor saved = actorRepository.save(actor);
    log.debug("Actor {} ('{}') synced to typed store", saved.getTmdbId(), saved.getName());
    return saved;
  }
}

