package dev.lmdb.ai.client;

import dev.lmdb.shared.dto.PageResponse;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.ParameterizedTypeReference;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

/**
 * Fetches recommendation candidates from movie-service's own persisted catalog (via Eureka/{@code
 * lb://}), never from TMDB directly. Calls movie-service's {@code /api/v1/movies/popular} endpoint,
 * which itself serves from its own MongoDB/Redis-backed store.
 */
@Component
@Slf4j
public class MovieCatalogClient {

  private final RestClient restClient;

  /**
   * @param movieServiceRestClient the load-balanced client from {@link
   *     dev.lmdb.ai.config.RestClientConfig}, already resolving {@code lb://movie-service} via
   *     Eureka
   */
  public MovieCatalogClient(RestClient movieServiceRestClient) {
    this.restClient = movieServiceRestClient;
  }

  /**
   * Fetches a page of currently popular movies as the candidate pool for recommendations.
   *
   * @param count how many candidates to request
   * @return the candidate movies, or an empty list if movie-service is unreachable (recommendations
   *     degrade gracefully rather than failing the whole request)
   */
  public List<CandidateMovie> fetchCandidates(int count) {
    try {
      PageResponse<CandidateMovie> page =
          restClient
              .get()
              .uri(
                  uriBuilder ->
                      uriBuilder
                          .path("/api/v1/movies/popular")
                          .queryParam("page", 1)
                          .queryParam("size", count)
                          .build())
              .retrieve()
              .body(new ParameterizedTypeReference<PageResponse<CandidateMovie>>() {});
      return page == null || page.getContent() == null ? List.of() : page.getContent();
    } catch (Exception e) {
      log.warn(
          "movie-service unreachable while fetching recommendation candidates: {}", e.getMessage());
      return List.of();
    }
  }
}

package dev.lmdb.ai.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.cloud.client.loadbalancer.BlockingLoadBalancerInterceptor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

/**
 * Configures a dedicated load-balanced {@link RestClient} for {@link
 * dev.lmdb.ai.client.MovieCatalogClient} so calls to {@code lb://movie-service} resolve via Eureka.
 *
 * <p>This deliberately does NOT declare a {@code @LoadBalanced RestClient.Builder} bean: Spring
 * Boot's {@code RestClientAutoConfiguration} only supplies its own ambient, unqualified {@code
 * RestClient.Builder} when {@code @ConditionalOnMissingBean(RestClient.Builder.class)} finds none —
 * a check that's type-only and ignores qualifiers. Defining a SECOND {@code RestClient.Builder}
 * bean here, even one qualified {@code @LoadBalanced}, suppresses that ambient bean entirely, so
 * every other unqualified {@code RestClient.Builder} injection in the app (Eureka's own
 * registration client, Spring AI's Ollama client) falls onto this one instead — both then try to
 * resolve their plain hostnames as Eureka service ids. Instead, {@link
 * BlockingLoadBalancerInterceptor} (the interface Spring Cloud LoadBalancer's auto-configured
 * interceptor bean always implements, whether or not Spring Retry ends up on the classpath) is
 * attached by hand to a fresh, private {@link RestClient.Builder} that only {@link
 * dev.lmdb.ai.client.MovieCatalogClient} ever sees — no extra {@code RestClient.Builder} bean is
 * ever registered.
 */
@Configuration
public class RestClientConfig {

  /**
   * @param loadBalancerInterceptor resolves {@code lb://} URIs to a real movie-service instance via
   *     Eureka
   * @param movieServiceBaseUrl movie-service's base URL, {@code lb://movie-service} by default
   * @return the {@link RestClient} {@link dev.lmdb.ai.client.MovieCatalogClient} calls
   *     movie-service through — load-balanced on its own, not via the shared builder
   */
  @Bean
  public RestClient movieServiceRestClient(
      BlockingLoadBalancerInterceptor loadBalancerInterceptor,
      @Value("${movie-service.base-url:lb://movie-service}") String movieServiceBaseUrl) {
    return RestClient.builder()
        .baseUrl(movieServiceBaseUrl)
        .requestInterceptor(loadBalancerInterceptor)
        .build();
  }
}

