import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

/**
 * REST surface for ai-service's features: catalog-grounded recommendations, the conversational
 * assistant, semantic search over user taste profiles, and offline speech-to-text for the
 * frontend's voice control (#68). The recommendation and chat features are also exposed over gRPC
 * by {@link dev.lmdb.ai.grpc.AiGrpcService}.
 */
@RestController
@RequestMapping("/api/v1/ai")
@RequiredArgsConstructor
@Slf4j
@Tag(
    name = "AI API",
    description = "Recommendations, chat assistant, semantic search, and speech-to-text")
public class AiController {

  private final RecommendationService recommendationService;
  private final ChatAssistantService chatAssistantService;
  private final SemanticSearchService semanticSearchService;
  private final SpeechToTextService speechToTextService;

  /**
   * Generates ranked, explained movie recommendations from LMDB's own catalog.
   *
   * @param request the user, their recent movies, and how many recommendations to return
   * @return the ranked recommendation list
   */
  @PostMapping("/recommendations")
  @Operation(
      summary = "Get movie recommendations",
      description = "Recommendations computed from LMDB's own catalog, not TMDB")
  public ResponseEntity<RecommendationResponseDto> recommend(
      @Valid @RequestBody RecommendationRequestDto request) {
    log.info("POST /api/v1/ai/recommendations - userId={}", request.userId());
    return ResponseEntity.ok(recommendationService.recommend(request));
  }

  /**
   * Continues (or starts) a conversation with the chat assistant.
   *
   * @param request the user's message, and optionally an existing conversation to continue
   * @return the assistant's reply and the conversation id
   */
  @PostMapping("/chat")
  @Operation(
      summary = "Chat with the assistant",
      description = "Persists the conversation; omit conversationId to start a new one")
  public ResponseEntity<ChatResponseDto> chat(@Valid @RequestBody ChatRequestDto request) {
    log.info("POST /api/v1/ai/chat - userId={}", request.userId());
    return ResponseEntity.ok(chatAssistantService.chat(request));
  }

  /**
   * Finds users whose taste embedding is nearest to a free-text query.
   *
   * @param query free-text description of a taste
   * @param userId the caller, excluded from its own results
   * @param k how many neighbours to return (default 5)
   * @return the nearest users, closest first
   */
  @GetMapping("/search/semantic")
  @Operation(
      summary = "Semantic search",
      description = "ANN search over user taste embeddings (pgvector)")
  public ResponseEntity<List<SimilarUserDto>> semanticSearch(
      @RequestParam String query,
      @RequestParam UUID userId,
      @RequestParam(defaultValue = "5") int k) {
    log.info("GET /api/v1/ai/search/semantic - userId={}, k={}", userId, k);
    return ResponseEntity.ok(semanticSearchService.findSimilarUsers(query, userId, k));
  }

  /**
   * Transcribes an uploaded voice-command audio clip via Vosk (#68).
   *
   * @param audio a WAV (PCM) recording of the spoken command
   * @return the recognized text
   */
  @PostMapping(value = "/speech-to-text", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
  @Operation(
      summary = "Speech to text",
      description = "Offline transcription via a local Vosk model — no cloud STT provider")
  public ResponseEntity<TranscriptionResponseDto> speechToText(
      @RequestParam("audio") MultipartFile audio) {
    log.info("POST /api/v1/ai/speech-to-text - {} bytes", audio.getSize());
    return ResponseEntity.ok(new TranscriptionResponseDto(speechToTextService.transcribe(audio)));
  }
}

package dev.lmdb.ai.controller;

import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.shared.exception.ResourceNotFoundException;
import dev.lmdb.shared.exception.ServiceUnavailableException;
import dev.lmdb.shared.exception.ValidationException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

/**
 * Maps ai-service's exceptions to the shared {@link ApiResponse} error envelope, mirroring
 * actor-service's and user-service's handlers.
 */
@RestControllerAdvice(basePackages = "dev.lmdb.ai.controller")
@Slf4j
public class GlobalExceptionHandler {

  /**
   * A requested conversation doesn't exist, or exists but is not owned by the requesting user (see
   * {@link dev.lmdb.ai.repository.ConversationRepository#findByIdAndUserId}) → 404.
   *
   * @param e not-found error
   * @return 404 error envelope
   */
  @ExceptionHandler(ResourceNotFoundException.class)
  public ResponseEntity<ApiResponse<Void>> handleNotFound(ResourceNotFoundException e) {
    return error(HttpStatus.NOT_FOUND, e.getMessage());
  }

  /**
   * A path variable or query param that won't convert to its declared type → 400, not 500.
   *
   * @param e the type-conversion failure
   * @return 400 error envelope naming the offending parameter
   */
  @ExceptionHandler(MethodArgumentTypeMismatchException.class)
  public ResponseEntity<ApiResponse<Void>> handleTypeMismatch(
      MethodArgumentTypeMismatchException e) {
    return error(
        HttpStatus.BAD_REQUEST, "Invalid value for '" + e.getName() + "': expected a number");
  }

  /**
   * A speech-to-text upload that isn't a readable audio file → 400.
   *
   * @param e audio-format validation failure
   * @return 400 error envelope
   */
  @ExceptionHandler(ValidationException.class)
  public ResponseEntity<ApiResponse<Void>> handleValidation(ValidationException e) {
    return error(HttpStatus.BAD_REQUEST, e.getMessage());
  }

  /**
   * A local, optional dependency isn't ready — the Vosk speech-to-text model hasn't been downloaded
   * yet, mirroring how an unreachable Ollama degrades rather than crashing the request thread.
   *
   * @param e dependency-not-ready error
   * @return 503 error envelope
   */
  @ExceptionHandler(ServiceUnavailableException.class)
  public ResponseEntity<ApiResponse<Void>> handleUnavailable(ServiceUnavailableException e) {
    log.warn("Dependency unavailable: {}", e.getMessage());
    return error(HttpStatus.SERVICE_UNAVAILABLE, e.getMessage());
  }

  /**
   * Anything unanticipated, including the Ollama client being unreachable — the model server is a
   * local, optional dependency, so a 500 here (rather than crashing the request thread) is the
   * correct degrade.
   *
   * @param e unexpected error
   * @return 500 error envelope
   */
  @ExceptionHandler(Exception.class)
  public ResponseEntity<ApiResponse<Void>> handleUnexpected(Exception e) {
    log.error("Unhandled exception in ai-service", e);
    return error(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected error occurred");
  }

  /**
   * Wraps a status and message in the shared {@link ApiResponse} error envelope.
   *
   * @param status the HTTP status to respond with
   * @param message the error message to surface to the caller
   * @return the fully-built error response
   */
  private static ResponseEntity<ApiResponse<Void>> error(HttpStatus status, String message) {
    return ResponseEntity.status(status).body(ApiResponse.error(message, status.value()));
  }
}

package dev.lmdb.ai.grpc;

import dev.lmdb.ai.dto.ChatRequestDto;
import dev.lmdb.ai.dto.ChatResponseDto;
import dev.lmdb.ai.dto.MovieRecommendationDto;
import dev.lmdb.ai.dto.RecommendationRequestDto;
import dev.lmdb.ai.dto.RecommendationResponseDto;
import dev.lmdb.ai.service.ChatAssistantService;
import dev.lmdb.ai.service.RecommendationService;
import io.grpc.Status;
import io.grpc.stub.StreamObserver;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

/**
 * gRPC surface for recommendations and chat (defined by {@code ai_service.proto}), delegating to
 * the same {@link RecommendationService} and {@link ChatAssistantService} the REST controller uses
 * — one set of business logic, two transports.
 */
@Component
@Slf4j
public class AiGrpcService extends AIServiceGrpc.AIServiceImplBase {

  private final RecommendationService recommendationService;
  private final ChatAssistantService chatAssistantService;

  /**
   * @param recommendationService the recommendation logic shared with the REST controller
   * @param chatAssistantService the chat logic shared with the REST controller
   */
  public AiGrpcService(
      RecommendationService recommendationService, ChatAssistantService chatAssistantService) {
    this.recommendationService = recommendationService;
    this.chatAssistantService = chatAssistantService;
  }

  /**
   * Handles the {@code GetRecommendations} RPC: validates the request's user id, delegates to
   * {@link RecommendationService}, and translates the result into the gRPC response message.
   *
   * @param request the recommendation request, with {@code user_id} as a string UUID
   * @param responseObserver receives either the ranked recommendations or an {@code
   *     INVALID_ARGUMENT} error if {@code user_id} isn't a valid UUID
   */
  @Override
  public void getRecommendations(
      RecommendationRequest request, StreamObserver<RecommendationResponse> responseObserver) {
    UUID userId;
    try {
      userId = UUID.fromString(request.getUserId());
    } catch (IllegalArgumentException _) {
      responseObserver.onError(
          Status.INVALID_ARGUMENT.withDescription("user_id must be a UUID").asRuntimeException());
      return;
    }

    RecommendationResponseDto result =
        recommendationService.recommend(
            new RecommendationRequestDto(
                userId, request.getRecentMoviesList(), request.getCount()));

    RecommendationResponse.Builder response = RecommendationResponse.newBuilder();
    for (MovieRecommendationDto rec : result.recommendations()) {
      response.addRecommendations(
          MovieRecommendation.newBuilder()
              .setMovieId(rec.movieId())
              .setScore(rec.score())
              .setReason(rec.reason())
              .build());
    }
    responseObserver.onNext(response.build());
    responseObserver.onCompleted();
  }

  /**
   * Handles the {@code ChatWithAssistant} RPC: validates the request's user and (optional)
   * conversation ids, delegates to {@link ChatAssistantService}, and translates the result into the
   * gRPC response message.
   *
   * @param request the chat request, with {@code user_id} and optional {@code conversation_id} as
   *     string UUIDs
   * @param responseObserver receives either the assistant's reply or an {@code INVALID_ARGUMENT}
   *     error if either id isn't a valid UUID
   */
  @Override
  public void chatWithAssistant(
      ChatRequest request, StreamObserver<ChatResponse> responseObserver) {
    UUID userId;
    UUID conversationId = null;
    try {
      userId = UUID.fromString(request.getUserId());
      if (!request.getConversationId().isEmpty()) {
        conversationId = UUID.fromString(request.getConversationId());
      }
    } catch (IllegalArgumentException _) {
      responseObserver.onError(
          Status.INVALID_ARGUMENT
              .withDescription("user_id/conversation_id must be UUIDs")
              .asRuntimeException());
      return;
    }

    ChatResponseDto result =
        chatAssistantService.chat(new ChatRequestDto(userId, conversationId, request.getMessage()));

    responseObserver.onNext(
        ChatResponse.newBuilder()
            .setConversationId(result.conversationId().toString())
            .setReply(result.reply())
            .build());
    responseObserver.onCompleted();
  }
}

package dev.lmdb.ai.grpc;

import io.grpc.Server;
import io.grpc.ServerBuilder;
import java.io.IOException;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.SmartLifecycle;
import org.springframework.stereotype.Component;

/**
 * Starts and stops the ai-service gRPC server ({@code grpc.server.port}, default 9084) alongside
 * the Spring application lifecycle. No third-party gRPC-Spring starter is used — {@link
 * AiGrpcService} is a small enough surface that a plain {@link SmartLifecycle} bean wrapping {@link
 * ServerBuilder} is simpler than an extra dependency.
 */
@Component
@Slf4j
public class GrpcServerLifecycle implements SmartLifecycle {

  private final AiGrpcService aiGrpcService;
  private final int port;
  private Server server;

  /**
   * @param aiGrpcService the gRPC service implementation to bind to the server
   * @param port the port to listen on, {@code grpc.server.port}, default 9084
   */
  public GrpcServerLifecycle(
      AiGrpcService aiGrpcService, @Value("${grpc.server.port:9084}") int port) {
    this.aiGrpcService = aiGrpcService;
    this.port = port;
  }

  /**
   * Builds and starts the gRPC server bound to {@link #aiGrpcService}.
   *
   * @throws IllegalStateException if the server fails to bind to {@link #port}
   */
  @Override
  public void start() {
    try {
      server = ServerBuilder.forPort(port).addService(aiGrpcService).build().start();
      log.info("gRPC server started on port {}", port);
    } catch (IOException e) {
      throw new IllegalStateException("Failed to start gRPC server on port " + port, e);
    }
  }

  /**
   * Shuts down the gRPC server, waiting up to 5 seconds for in-flight calls to finish before
   * returning. Restores the thread's interrupt status if interrupted while waiting, rather than
   * swallowing it.
   */
  @Override
  public void stop() {
    if (server != null) {
      try {
        server.shutdown().awaitTermination(5, TimeUnit.SECONDS);
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
      } finally {
        server = null;
      }
    }
  }

  /**
   * @return {@code true} if the gRPC server has been started and not yet shut down
   */
  @Override
  public boolean isRunning() {
    return server != null && !server.isShutdown();
  }
}

package dev.lmdb.ai.model;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * A conversation thread with the AI assistant — the persisted, user-owned aggregate root behind the
 * chat and recommendation features. Backed by a Flyway-managed relational schema, with {@link
 * Message} rows cascading as part of the same aggregate.
 */
@Entity
@Table(name = "conversations")
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Conversation {

  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  private UUID id;

  /** Owning user (user-service's id). No foreign key — cross-service references are id-only. */
  private UUID userId;

  @Enumerated(EnumType.STRING)
  private ConversationType type;

  /** Ordered message thread; cascaded so a conversation is one aggregate. */
  @Builder.Default
  @OneToMany(mappedBy = "conversation", cascade = CascadeType.ALL, orphanRemoval = true)
  @OrderBy("timestamp ASC")
  private List<Message> messages = new ArrayList<>();

  private Instant createdAt;

  private Instant updatedAt;

  /**
   * Appends a message to this conversation's thread, keeping both sides of the bidirectional
   * association in sync and bumping the aggregate's {@code updatedAt}.
   *
   * @param message the message to append; its {@code conversation} back-reference is set here
   */
  public void addMessage(Message message) {
    messages.add(message);
    message.setConversation(this);
    this.updatedAt = Instant.now();
  }
}

package dev.lmdb.ai.model;

/**
 * The feature a {@link Conversation} belongs to. Persisted as the conversation's {@code type}
 * column (see V2__init_ai_schema.sql).
 */
public enum ConversationType {
  /** A back-and-forth conversation with the chat assistant. */
  CHAT,
  /** The exchange that produced a set of movie recommendations. */
  RECOMMENDATION
}

