import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

/**
 * One turn in a {@link Conversation}'s thread. Always accessed through its owning conversation —
 * {@link #conversation} is {@code LAZY} because nothing reads a message without already holding the
 * conversation it belongs to.
 */
@Entity
@Table(name = "messages")
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Message {

  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  private UUID id;

  @ManyToOne(fetch = FetchType.LAZY)
  @JoinColumn(name = "conversation_id", nullable = false)
  private Conversation conversation;

  /** {@code user}, {@code assistant}, or {@code system}. */
  private String role;

  @Column(columnDefinition = "text")
  private String content;

  private Instant timestamp;

  /**
   * Provider-specific fields whose shape genuinely varies — structured where structure exists (the
   * columns above), flexible where it doesn't.
   */
  @JdbcTypeCode(SqlTypes.JSON)
  @Column(columnDefinition = "jsonb")
  private Map<String, Object> metadata;
}

package dev.lmdb.ai.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.Array;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

/**
 * A user's embedded taste vector, backing the semantic-search / "sensible neighbours" feature. One
 * row per user — {@link #userId} is both the primary key and a plain column with no foreign key,
 * since it references a user owned by a different service.
 */
@Entity
@Table(name = "user_taste_profiles")
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class UserTasteProfile {

  @Id
  @Column(name = "user_id")
  private UUID userId;

  /** pgvector column; dimension must match the embedding model in use (nomic-embed-text, 768). */
  @JdbcTypeCode(SqlTypes.VECTOR)
  @Array(length = 768)
  @Column(columnDefinition = "vector(768)")
  private float[] embedding;

  @JdbcTypeCode(SqlTypes.JSON)
  @Column(columnDefinition = "jsonb")
  private Map<String, Double> featureWeights;

  private Instant lastUpdated;
}

package dev.lmdb.ai.repository;

import dev.lmdb.ai.model.Conversation;
import java.util.Optional;
import java.util.UUID;
import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Persistence for {@link Conversation} aggregates. Messages are never queried independently — they
 * load with their owning conversation via the {@code @OneToMany} mapping.
 */
public interface ConversationRepository extends JpaRepository<Conversation, UUID> {

  /**
   * Looks up a conversation scoped to its owner, so one user can never read or append to another
   * user's conversation by guessing an id.
   *
   * @param id the conversation id
   * @param userId the expected owning user
   * @return the conversation if it exists and belongs to {@code userId}
   */
  Optional<Conversation> findByIdAndUserId(UUID id, UUID userId);
}

package dev.lmdb.ai.repository;

import java.util.stream.Collectors;
import java.util.stream.IntStream;

/**
 * Converts a Java {@code float[]} embedding to pgvector's text input format ({@code
 * "[0.1,0.2,...]"}) for binding into the native ANN query in {@link
 * UserTasteProfileRepository#findNearestNeighbours}.
 */
public final class EmbeddingFormat {

  private EmbeddingFormat() {}

  /**
   * @param embedding the vector to format
   * @return the pgvector text literal, e.g. {@code "[0.1,0.2,0.3]"}
   */
  public static String toPgvectorLiteral(float[] embedding) {
    return IntStream.range(0, embedding.length)
        .mapToObj(i -> Float.toString(embedding[i]))
        .collect(Collectors.joining(",", "[", "]"));
  }
}

package dev.lmdb.ai.repository;

import dev.lmdb.ai.model.UserTasteProfile;
import java.util.List;
import java.util.UUID;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/**
 * Persistence for {@link UserTasteProfile}, including the ANN (approximate-nearest-neighbour)
 * semantic-search query over its pgvector {@code embedding} column.
 */
public interface UserTasteProfileRepository extends JpaRepository<UserTasteProfile, UUID> {

  /**
   * Finds the {@code k} users whose taste embedding is closest (cosine distance, backed by the
   * {@code idx_user_taste_profiles_embedding} HNSW index) to {@code queryVector}. Each row is
   * {@code [user_id (UUID), distance (Double)]}, closest first.
   *
   * <p>{@code queryVector} is pgvector's text input format ({@code "[0.1,0.2,...]"}, see {@link
   * EmbeddingFormat}) bound as a parameter and cast in SQL, rather than relying on JDBC array
   * binding for a native query — the same representation the driver would produce either way, made
   * explicit. A native query (rather than a projection interface) is what returns the computed
   * distance as a plain column alongside the id.
   *
   * @param queryVector the query embedding, pgvector text format
   * @param excludeUserId a user to exclude from results (typically the caller, so "similar users"
   *     never returns yourself)
   * @param limit maximum number of neighbours to return
   * @return rows of {@code [user_id, distance]}, closest first
   */
  @Query(
      value =
          """
            SELECT user_id, embedding <=> CAST(:queryVector AS vector) AS distance
            FROM user_taste_profiles
            WHERE user_id != :excludeUserId
            ORDER BY distance
            LIMIT :limit
            """,
      nativeQuery = true)
  List<Object[]> findNearestNeighbours(
      @Param("queryVector") String queryVector,
      @Param("excludeUserId") UUID excludeUserId,
      @Param("limit") int limit);
}

package dev.lmdb.ai.service;

import dev.lmdb.ai.dto.ChatRequestDto;
import dev.lmdb.ai.dto.ChatResponseDto;
import dev.lmdb.ai.model.Conversation;
import dev.lmdb.ai.model.ConversationType;
import dev.lmdb.ai.model.Message;
import dev.lmdb.ai.repository.ConversationRepository;
import dev.lmdb.shared.exception.ResourceNotFoundException;
import java.time.Instant;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import org.springframework.ai.chat.client.ChatClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The conversational assistant feature: a user's back-and-forth with the AI, persisted as a {@link
 * Conversation} aggregate so history survives a restart. Collaborates with Spring AI's {@link
 * ChatClient} for the model call and {@link ConversationRepository} for persistence.
 */
@Service
@Slf4j
public class ChatAssistantService {

  private static final String SYSTEM_PROMPT =
      """
        You are LMDB's movie assistant. Answer questions about films,
        actors, and viewing recommendations concisely and helpfully. If asked
        about something unrelated to movies, gently steer the conversation
        back to movies.
        """;

  private final ChatClient chatClient;
  private final ConversationRepository conversationRepository;

  /**
   * @param chatClientBuilder builder for the Spring AI {@link ChatClient} used to generate replies
   * @param conversationRepository persistence for {@link Conversation} aggregates
   */
  public ChatAssistantService(
      ChatClient.Builder chatClientBuilder, ConversationRepository conversationRepository) {
    this.chatClient = chatClientBuilder.build();
    this.conversationRepository = conversationRepository;
  }

  /**
   * Continues (or starts) a conversation with one user message and one assistant reply, persisting
   * both.
   *
   * @param request the incoming user message, and optionally an existing conversation to continue
   * @return the assistant's reply and the conversation id it belongs to
   * @throws ResourceNotFoundException if {@code request.conversationId()} doesn't exist or isn't
   *     owned by {@code request.userId()}
   */
  @Transactional
  public ChatResponseDto chat(ChatRequestDto request) {
    Conversation conversation = resolveConversation(request);

    Message userMessage =
        Message.builder().role("user").content(request.message()).timestamp(Instant.now()).build();
    conversation.addMessage(userMessage);

    String history =
        conversation.getMessages().stream()
            .map(m -> m.getRole() + ": " + m.getContent())
            .collect(Collectors.joining("\n"));

    String reply = chatClient.prompt().system(SYSTEM_PROMPT).user(history).call().content();
    reply = reply == null ? "" : reply;

    Message assistantMessage =
        Message.builder().role("assistant").content(reply).timestamp(Instant.now()).build();
    conversation.addMessage(assistantMessage);

    conversationRepository.save(conversation);

    return new ChatResponseDto(conversation.getId(), reply);
  }

  /**
   * Loads the conversation named by the request, scoped to its owner, or starts a new one when
   * {@code conversationId} is absent.
   *
   * @param request the incoming chat request
   * @return an existing, owned conversation, or a new unsaved one
   * @throws ResourceNotFoundException if {@code request.conversationId()} doesn't exist or isn't
   *     owned by {@code request.userId()}
   */
  private Conversation resolveConversation(ChatRequestDto request) {
    if (request.conversationId() == null) {
      return Conversation.builder()
          .userId(request.userId())
          .type(ConversationType.CHAT)
          .createdAt(Instant.now())
          .updatedAt(Instant.now())
          .build();
    }
    return conversationRepository
        .findByIdAndUserId(request.conversationId(), request.userId())
        .orElseThrow(
            () ->
                new ResourceNotFoundException(
                    "Conversation not found: " + request.conversationId()));
  }
}

package dev.lmdb.ai.service;

import dev.lmdb.ai.client.CandidateMovie;
import dev.lmdb.ai.client.MovieCatalogClient;
import dev.lmdb.ai.dto.MovieRecommendationDto;
import dev.lmdb.ai.dto.RecommendationRequestDto;
import dev.lmdb.ai.dto.RecommendationResponseDto;
import dev.lmdb.ai.model.UserTasteProfile;
import dev.lmdb.ai.repository.UserTasteProfileRepository;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.embedding.EmbeddingModel;
import org.springframework.core.ParameterizedTypeReference;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Movie recommendations computed from LMDB's own catalog — never proxied from TMDB's own
 * recommendation endpoint. Candidates come from {@link MovieCatalogClient} (movie-service's
 * persisted data); the assistant ranks and explains them against the user's recent viewing.
 *
 * <p>As a side effect, this also refreshes the user's {@link UserTasteProfile} embedding from their
 * recent-movies text, which is what backs the semantic search / "similar users" feature ({@link
 * SemanticSearchService}) — a taste profile only exists once a user has asked for recommendations
 * at least once.
 */
@Service
@Slf4j
public class RecommendationService {

  private static final String SYSTEM_PROMPT =
      """
        You are LMDB's recommendation engine. You will be given a list of
        candidate movies and a user's recently watched movies. Pick the best
        matches from the CANDIDATES ONLY — never invent a movie not listed —
        and explain briefly why each fits the user's taste. Respond with a
        JSON array of objects: movieId (the candidate's id, as a string),
        score (0 to 1), reason (one sentence).
        """;

  private final ChatClient chatClient;
  private final EmbeddingModel embeddingModel;
  private final MovieCatalogClient movieCatalogClient;
  private final UserTasteProfileRepository tasteProfileRepository;

  /**
   * @param chatClientBuilder builder for the Spring AI {@link ChatClient} used to rank and explain
   *     candidates
   * @param embeddingModel model used to embed the user's recent-movies text into a taste vector
   * @param movieCatalogClient source of candidate movies from movie-service's own catalog
   * @param tasteProfileRepository persistence for the resulting {@link UserTasteProfile}
   */
  public RecommendationService(
      ChatClient.Builder chatClientBuilder,
      EmbeddingModel embeddingModel,
      MovieCatalogClient movieCatalogClient,
      UserTasteProfileRepository tasteProfileRepository) {
    this.chatClient = chatClientBuilder.build();
    this.embeddingModel = embeddingModel;
    this.movieCatalogClient = movieCatalogClient;
    this.tasteProfileRepository = tasteProfileRepository;
  }

  /**
   * Generates ranked, explained recommendations for a user.
   *
   * @param request the user, their recent movies, and how many recommendations to return
   * @return the ranked recommendation list; empty if movie-service has no candidates to offer
   */
  @Transactional
  public RecommendationResponseDto recommend(RecommendationRequestDto request) {
    List<CandidateMovie> candidates =
        movieCatalogClient.fetchCandidates(request.countOrDefault() * 3);
    refreshTasteProfile(request);

    if (candidates.isEmpty()) {
      log.warn("No recommendation candidates available for user {}", request.userId());
      return new RecommendationResponseDto(List.of());
    }

    String candidateList =
        candidates.stream()
            .map(
                c ->
                    "id=%d title=\"%s\" overview=\"%s\" voteAverage=%s"
                        .formatted(c.tmdbId(), c.title(), c.overview(), c.voteAverage()))
            .reduce("", (a, b) -> a + b + "\n");

    String userPrompt =
        """
            Recently watched: %s
            Candidates:
            %s
            Return exactly %d recommendations.
            """
            .formatted(
                String.join(
                    ", ", request.recentMovies() == null ? List.of() : request.recentMovies()),
                candidateList,
                request.countOrDefault());

    List<MovieRecommendationDto> recommendations =
        chatClient
            .prompt()
            .system(SYSTEM_PROMPT)
            .user(userPrompt)
            .call()
            .entity(new ParameterizedTypeReference<List<MovieRecommendationDto>>() {});

    return new RecommendationResponseDto(recommendations == null ? List.of() : recommendations);
  }

  /**
   * Embeds the user's recent-movies text and upserts it as their taste profile — the persisted
   * artifact semantic search runs its ANN query against. Does nothing if the request carries no
   * recent movies to embed.
   *
   * @param request the recommendation request whose {@code recentMovies} are embedded
   */
  private void refreshTasteProfile(RecommendationRequestDto request) {
    if (request.recentMovies() == null || request.recentMovies().isEmpty()) {
      return;
    }
    float[] embedding = embeddingModel.embed(String.join(", ", request.recentMovies()));
    UserTasteProfile profile =
        UserTasteProfile.builder()
            .userId(request.userId())
            .embedding(embedding)
            .featureWeights(Map.of())
            .lastUpdated(Instant.now())
            .build();
    tasteProfileRepository.save(profile);
  }
}

package dev.lmdb.ai.service;

import dev.lmdb.ai.dto.SimilarUserDto;
import dev.lmdb.ai.repository.EmbeddingFormat;
import dev.lmdb.ai.repository.UserTasteProfileRepository;
import java.util.List;
import java.util.UUID;
import org.springframework.ai.embedding.EmbeddingModel;
import org.springframework.stereotype.Service;

/**
 * Semantic search over {@link dev.lmdb.ai.model.UserTasteProfile} embeddings: "find users whose
 * taste is closest to this description" — an ANN query run directly against the pgvector index via
 * {@link UserTasteProfileRepository}, with no separate vector database.
 */
@Service
public class SemanticSearchService {

  private final EmbeddingModel embeddingModel;
  private final UserTasteProfileRepository tasteProfileRepository;

  /**
   * @param embeddingModel model used to embed the free-text query
   * @param tasteProfileRepository source of the ANN nearest-neighbour query
   */
  public SemanticSearchService(
      EmbeddingModel embeddingModel, UserTasteProfileRepository tasteProfileRepository) {
    this.embeddingModel = embeddingModel;
    this.tasteProfileRepository = tasteProfileRepository;
  }

  /**
   * Embeds {@code query} and returns the {@code k} nearest taste profiles, excluding the caller.
   *
   * @param query free-text description of a taste ("gritty sci-fi with practical effects")
   * @param requestingUserId the caller, excluded from its own results
   * @param k how many neighbours to return
   * @return the nearest users, closest first
   */
  public List<SimilarUserDto> findSimilarUsers(String query, UUID requestingUserId, int k) {
    float[] queryEmbedding = embeddingModel.embed(query);
    String queryVector = EmbeddingFormat.toPgvectorLiteral(queryEmbedding);

    return tasteProfileRepository.findNearestNeighbours(queryVector, requestingUserId, k).stream()
        .map(row -> new SimilarUserDto((UUID) row[0], ((Number) row[1]).doubleValue()))
        .toList();
  }
}

package dev.lmdb.ai.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.lmdb.shared.exception.ServiceUnavailableException;
import dev.lmdb.shared.exception.ValidationException;
import java.io.BufferedInputStream;
import java.io.IOException;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.DisposableBean;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import org.vosk.LibVosk;
import org.vosk.LogLevel;
import org.vosk.Model;
import org.vosk.Recognizer;

/**
 * Offline speech-to-text (#68). Runs entirely against a local <a
 * href="https://alphacephei.com/vosk/">Vosk</a> model — no audio ever leaves this service, and
 * there is no cloud STT provider or API key (ADR-004's $0 budget).
 *
 * <p>The Vosk {@link Model} is expensive to load (reads the model directory from disk) and
 * immutable once loaded, so it's loaded once, lazily, on the first transcription request rather
 * than at startup — a missing/not-yet- downloaded model must not prevent ai-service's other
 * features (chat, recommendations, semantic search) from starting. A {@link Recognizer} is NOT
 * thread-safe, so a fresh one is created per request from the shared {@link Model}.
 */
@Service
@Slf4j
public class SpeechToTextService implements DisposableBean {

  /** Vosk's small English model is trained for 16kHz mono PCM16 audio. */
  private static final float SAMPLE_RATE_HZ = 16_000f;

  private static final AudioFormat TARGET_FORMAT =
      new AudioFormat(SAMPLE_RATE_HZ, 16, 1, true, false);

  private final String modelPath;
  private final ObjectMapper objectMapper;
  private volatile Model model;

  /**
   * @param modelPath filesystem path to an unzipped Vosk model directory
   * @param objectMapper parses Vosk's {@code {"text": "..."}} result JSON
   */
  public SpeechToTextService(
      @Value("${speech-to-text.vosk.model-path}") String modelPath, ObjectMapper objectMapper) {
    this.modelPath = modelPath;
    this.objectMapper = objectMapper;
  }

  /**
   * Transcribes an uploaded audio clip to text.
   *
   * @param audioFile a WAV (PCM) upload; other sample rates/channel counts are resampled to what
   *     Vosk expects
   * @return the recognized text, empty if Vosk understood nothing
   * @throws ValidationException the upload isn't a readable audio file
   * @throws ServiceUnavailableException the Vosk model isn't downloaded yet
   */
  public String transcribe(MultipartFile audioFile) {
    // Validate the (cheap) client input before paying the model-load cost.
    byte[] pcm = toPcm16Mono16kHz(audioFile);
    Model loadedModel = getOrLoadModel();

    try (Recognizer recognizer = new Recognizer(loadedModel, SAMPLE_RATE_HZ)) {
      recognizer.acceptWaveForm(pcm, pcm.length);
      return extractText(recognizer.getFinalResult());
    } catch (IOException e) {
      throw new ServiceUnavailableException("speech-to-text", "recognizer failed to start", e);
    }
  }

  /**
   * Loads the Vosk model on first use (double-checked locking — cheap after the first call, and
   * only one thread pays the disk-read cost).
   *
   * @return the shared, immutable model
   * @throws ServiceUnavailableException the model directory is missing or unreadable
   */
  private Model getOrLoadModel() {
    Model loaded = model;
    if (loaded != null) {
      return loaded;
    }

    synchronized (this) {
      if (model == null) {
        log.info("Loading Vosk speech-to-text model from {}", modelPath);
        LibVosk.setLogLevel(LogLevel.WARNINGS);
        try {
          model = new Model(modelPath);
        } catch (IOException e) {
          throw new ServiceUnavailableException(
              "speech-to-text",
              "model not found at '"
                  + modelPath
                  + "' — run infrastructure/scripts/download-vosk-model.sh first",
              e);
        }
      }
      return model;
    }
  }

  /**
   * Reads an uploaded audio file and resamples it to the mono 16kHz PCM16 format Vosk requires,
   * regardless of what format the browser sent.
   *
   * @param audioFile the raw upload
   * @return raw little-endian PCM16 samples, no WAV header
   * @throws ValidationException the upload isn't a decodable audio file
   */
  private byte[] toPcm16Mono16kHz(MultipartFile audioFile) {
    // AudioSystem needs to read-ahead and reset while sniffing the
    // format — MultipartFile's own InputStream doesn't support that.
    try (AudioInputStream sourceStream =
        AudioSystem.getAudioInputStream(new BufferedInputStream(audioFile.getInputStream()))) {
      try (AudioInputStream pcmStream =
          AudioSystem.getAudioInputStream(TARGET_FORMAT, sourceStream)) {
        return pcmStream.readAllBytes();
      }
    } catch (UnsupportedAudioFileException | IllegalArgumentException e) {
      throw new ValidationException(
          "audio", "Unsupported audio format — expected a WAV (PCM) file: " + e.getMessage());
    } catch (IOException e) {
      throw new ValidationException(
          "audio", "Could not read the uploaded audio file: " + e.getMessage());
    }
  }

  /**
   * Pulls the {@code text} field out of Vosk's JSON result.
   *
   * @param resultJson Vosk's {@code {"text": "..."}} response
   * @return the recognized text, empty if the field is missing or the JSON is malformed
   */
  private String extractText(String resultJson) {
    try {
      JsonNode node = objectMapper.readTree(resultJson);
      return node.path("text").asText("");
    } catch (IOException e) {
      log.warn("Vosk returned unparseable result JSON: {}", resultJson, e);
      return "";
    }
  }

  /**
   * Frees the native Vosk model on shutdown — it holds an off-heap handle that the JVM's GC doesn't
   * know about.
   */
  @Override
  public void destroy() {
    if (model != null) {
      model.close();
    }
  }
}

package dev.lmdb.gateway;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * API Gateway Application. Entry point for the API Gateway service that routes requests to
 * microservices. Eureka client is auto-configured when eureka-client dependency is present.
 */
@SpringBootApplication
public class ApiGatewayApplication {

  public static void main(String[] args) {
    SpringApplication.run(ApiGatewayApplication.class, args);
  }
}

package dev.lmdb.gateway.config;

import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.ratelimit.KeyResolver;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import reactor.core.publisher.Mono;

/**
 * Rate limiting configuration for API Gateway. Implements IP-based rate limiting to prevent DDoS
 * attacks.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Configuration
public class RateLimitConfig {

  /**
   * IP-based key resolver for rate limiting. Keys rate limits by client IP address from
   * X-Forwarded-For header or remote address.
   *
   * <p>This provides per-IP rate limiting to prevent DDoS attacks where: - Single IP cannot exceed
   * rate limits - Distributed attacks are mitigated per-IP - Works with proxies (X-Forwarded-For
   * header)
   *
   * @return KeyResolver that extracts client IP address
   */
  @Primary
  @Bean
  public KeyResolver ipKeyResolver() {
    return exchange -> {
      // Try to get IP from X-Forwarded-For header (for proxied requests)
      String forwardedFor = exchange.getRequest().getHeaders().getFirst("X-Forwarded-For");

      if (forwardedFor != null && !forwardedFor.isEmpty()) {
        // X-Forwarded-For can contain multiple IPs: "client, proxy1, proxy2"
        // We want the first one (original client IP)
        String clientIp = forwardedFor.split(",")[0].trim();
        log.debug("Rate limiting key from X-Forwarded-For: {}", clientIp);
        return Mono.just(clientIp);
      }

      // Fallback to remote address if no X-Forwarded-For header
      var remoteAddressObj = exchange.getRequest().getRemoteAddress();
      if (remoteAddressObj != null && remoteAddressObj.getAddress() != null) {
        String remoteAddress = remoteAddressObj.getAddress().getHostAddress();
        log.debug("Rate limiting key from remote address: {}", remoteAddress);
        return Mono.just(remoteAddress);
      }

      // Fallback to "unknown" if remote address is not available
      log.warn("Unable to determine client IP address, using 'unknown' as rate limit key");
      return Mono.just("unknown");
    };
  }

  /**
   * Alternative key resolver based on user authentication. Can be used for authenticated endpoints
   * to rate limit by user ID.
   *
   * <p>This is not the primary resolver but can be referenced in specific routes.
   *
   * @return KeyResolver that extracts user ID from authentication
   */
  @Bean
  public KeyResolver userKeyResolver() {
    return exchange ->
        exchange
            .getPrincipal()
            .map(
                principal -> {
                  log.debug("Rate limiting key from user: {}", principal.getName());
                  return principal.getName();
                })
            .switchIfEmpty(Mono.just("anonymous"));
  }

  /**
   * Path-based key resolver for route-specific rate limiting. Combines IP with path to provide
   * per-endpoint rate limiting.
   *
   * @return KeyResolver that combines IP and path
   */
  @Bean
  public KeyResolver pathKeyResolver() {
    return exchange -> {
      String ip = "unknown";
      var remoteAddressObj = exchange.getRequest().getRemoteAddress();
      if (remoteAddressObj != null && remoteAddressObj.getAddress() != null) {
        ip = remoteAddressObj.getAddress().getHostAddress();
      }

      String path = exchange.getRequest().getURI().getPath();
      String key = ip + ":" + path;

      log.debug("Rate limiting key from IP+Path: {}", key);
      return Mono.just(key);
    };
  }
}

package dev.lmdb.gateway.config;

import org.jspecify.annotations.NonNull;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.ReactiveRedisConnectionFactory;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.data.redis.serializer.RedisSerializationContext;
import org.springframework.data.redis.serializer.StringRedisSerializer;

/**
 * Redis configuration for API Gateway. Provides ReactiveRedisTemplate for rate limiting and
 * caching.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Configuration
@ConditionalOnBean(ReactiveRedisConnectionFactory.class)
public class RedisConfig {

  /**
   * Creates a ReactiveRedisTemplate for global rate limiting. Uses String serializers for both keys
   * and values.
   *
   * @param connectionFactory the reactive redis connection factory
   * @return ReactiveRedisTemplate for String operations
   */
  @Bean
  public ReactiveRedisTemplate<String, String> reactiveRedisTemplate(
      @NonNull ReactiveRedisConnectionFactory connectionFactory) {

    StringRedisSerializer serializer = new StringRedisSerializer();

    RedisSerializationContext<String, String> serializationContext =
        RedisSerializationContext.<String, String>newSerializationContext()
            .key(serializer)
            .value(serializer)
            .hashKey(serializer)
            .hashValue(serializer)
            .build();

    return new ReactiveRedisTemplate<>(connectionFactory, serializationContext);
  }
}

package dev.lmdb.gateway.config;

import dev.lmdb.gateway.filter.JwtAuthenticationFilter;
import java.util.Arrays;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity;
import org.springframework.security.config.web.server.SecurityWebFiltersOrder;
import org.springframework.security.config.web.server.ServerHttpSecurity;
import org.springframework.security.web.server.SecurityWebFilterChain;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.reactive.CorsConfigurationSource;
import org.springframework.web.cors.reactive.UrlBasedCorsConfigurationSource;

/**
 * Security configuration for API Gateway. Configures JWT authentication, CORS, and public/private
 * endpoints.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Configuration
@EnableWebFluxSecurity
@RequiredArgsConstructor
public class SecurityConfig {

  private final JwtAuthenticationFilter jwtAuthenticationFilter;

  /** Media service API path pattern — used in three separate security rules. */
  private static final String MEDIA_API_PATH = "/api/v1/media/**";

  /**
   * Configures security filter chain for the API Gateway
   *
   * @param http the ServerHttpSecurity to configure
   * @return the configured SecurityWebFilterChain
   */
  @Bean
  public SecurityWebFilterChain securityWebFilterChain(ServerHttpSecurity http) {
    return http
        // Disable CSRF for stateless API
        .csrf(ServerHttpSecurity.CsrfSpec::disable)

        // Configure CORS
        .cors(cors -> cors.configurationSource(corsConfigurationSource()))

        // Configure authorization
        .authorizeExchange(
            exchanges ->
                exchanges
                    // Public endpoints
                    .pathMatchers(HttpMethod.POST, "/api/v1/auth/login")
                    .permitAll()
                    .pathMatchers(HttpMethod.POST, "/api/v1/auth/register")
                    .permitAll()
                    .pathMatchers(HttpMethod.POST, "/api/v1/auth/refresh")
                    .permitAll()
                    .pathMatchers("/actuator/**")
                    .permitAll()
                    .pathMatchers("/fallback/**")
                    .permitAll()

                    // Public GET endpoints (read-only access)
                    .pathMatchers(HttpMethod.GET, "/api/v1/movies/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/api/v1/genres/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/api/v1/actors/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, MEDIA_API_PATH)
                    .permitAll()

                    // Media service: upload and deletion require JWT authentication
                    .pathMatchers(HttpMethod.POST, MEDIA_API_PATH)
                    .authenticated()
                    .pathMatchers(HttpMethod.DELETE, MEDIA_API_PATH)
                    .authenticated()

                    // TMDB v3 facade (#33): bare TMDB catalog paths are public
                    // reads served by the movie/actor facade controllers.
                    .pathMatchers(HttpMethod.GET, "/movie/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/genre/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/discover/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/search/**")
                    .permitAll()
                    .pathMatchers(HttpMethod.GET, "/person/**")
                    .permitAll()

                    // TMDB auth/account proxy (#33): authentication is enforced
                    // by TMDB itself via the forwarded session_id, so the gateway
                    // does not require a local JWT on these passthrough routes.
                    .pathMatchers("/authentication/**")
                    .permitAll()
                    .pathMatchers("/account/**")
                    .permitAll()

                    // Voice control (#68): unlike the rest of ai-service, speech-to-text
                    // isn't scoped to a user (no conversation/taste-profile data touched)
                    // — voice button works for anonymous
                    // visitors too (theme toggle, genre browsing). Must be listed before
                    // the /api/v1/ai/** rule below, which requires auth for everything else.
                    .pathMatchers(HttpMethod.POST, "/api/v1/ai/speech-to-text")
                    .permitAll()

                    // AI service (#36): every other feature (chat, recommendations,
                    // semantic search) is scoped to a userId — conversations and taste
                    // profiles are user-owned data (ADR-012), so these routes are
                    // explicitly JWT-gated rather than left to the anyExchange()
                    // catch-all below.
                    .pathMatchers("/api/v1/ai/**")
                    .authenticated()

                    // Admin endpoints (require authentication - should add role check in
                    // production)
                    .pathMatchers("/admin/**")
                    .authenticated()

                    // All other endpoints require authentication
                    .anyExchange()
                    .authenticated())

        // Add JWT authentication filter
        .addFilterAt(jwtAuthenticationFilter, SecurityWebFiltersOrder.AUTHENTICATION)
        .build();
  }

  /**
   * Configures CORS for the API Gateway
   *
   * @return CorsConfigurationSource with allowed origins, methods, and headers
   */
  @Bean
  public CorsConfigurationSource corsConfigurationSource() {
    CorsConfiguration configuration = new CorsConfiguration();

    // Allowed origins (frontend applications)
    configuration.setAllowedOrigins(
        Arrays.asList(
            "http://localhost:3000",
            "http://localhost:3001",
            "http://localhost:5173",
            "http://localhost:5174",
            "https://lmdb.dev",
            "https://lmdb.dev",
            "https://www.lmdb.dev"));
    configuration.setAllowedOriginPatterns(
        Arrays.asList(
            "http://localhost:*",
            "https://*.vercel.app",
            "https://*.duckdns.org",
            "https://*.trycloudflare.com",
            "https://*.lmdb.dev"));

    // Allowed HTTP methods
    configuration.setAllowedMethods(
        Arrays.asList("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS"));

    // Allowed headers
    configuration.setAllowedHeaders(List.of("*"));

    // Allow credentials (cookies, authorization headers)
    configuration.setAllowCredentials(true);

    // How long the response from a pre-flight request can be cached
    configuration.setMaxAge(3600L);

    // Expose headers to the client
    configuration.setExposedHeaders(Arrays.asList("Authorization", "Access-Control-Allow-Origin"));

    UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
    source.registerCorsConfiguration("/**", configuration);

    return source;
  }
}

package dev.lmdb.gateway.controller;

import dev.lmdb.gateway.service.ActivityTrackingService;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Controller exposing gateway activity metrics for watchdog scripts and frontend telemetry.
 *
 * <p>Provides the {@code /actuator/activity} endpoint consumed by {@code auto-stop-watchdog.sh} to
 * decide whether to trigger cloud compute suspension after 1 hour of idle time, and by the frontend
 * footer to display real-time cloud provider, uptime, and time-to-sleep telemetry.
 *
 * @author LMDB Development Team
 * @version 1.1.0
 */
@Slf4j
@RestController
@RequestMapping("/actuator")
@RequiredArgsConstructor
public class ActivityStatusController {

  private final ActivityTrackingService activityTrackingService;

  @Value("${cloud.provider:${CLOUD_PROVIDER:azure}}")
  private String cloudProvider;

  /**
   * Resolves a human-readable display label for the active cloud provider.
   *
   * @param provider the raw provider identifier (e.g. azure, aws, minikube)
   * @return descriptive provider label
   */
  private String resolveProviderLabel(String provider) {
    if (provider == null) {
      return "Microsoft Azure (AKS)";
    }
    return switch (provider.toLowerCase()) {
      case "azure" -> "Microsoft Azure (AKS)";
      case "aws" -> "Amazon Web Services (k3s)";
      case "minikube" -> "Local Minikube Cluster";
      case "local", "docker" -> "Local Docker Infrastructure";
      default -> provider.substring(0, 1).toUpperCase() + provider.substring(1);
    };
  }

  /**
   * Returns current gateway activity, cloud provider telemetry, and auto-stop eligibility.
   *
   * @return JSON response with activity status, provider info, uptime, and threshold metrics
   */
  @GetMapping("/activity")
  public ResponseEntity<Map<String, Object>> getActivityStatus() {
    long threshold = ActivityTrackingService.DEFAULT_IDLE_THRESHOLD_SECONDS;
    long idleSeconds = activityTrackingService.getIdleSeconds();
    long remaining = activityTrackingService.getSecondsUntilAutoStop(threshold);
    String providerKey =
        (cloudProvider != null && !cloudProvider.isBlank()) ? cloudProvider.toLowerCase() : "azure";

    Map<String, Object> response = new LinkedHashMap<>();
    response.put("status", "UP");
    response.put("cloudProvider", providerKey);
    response.put("cloudProviderLabel", resolveProviderLabel(providerKey));
    response.put("serverStartTime", activityTrackingService.getStartTime().toString());
    response.put("uptimeSeconds", activityTrackingService.getUptimeSeconds());
    response.put("lastActivityTime", activityTrackingService.getLastActivityTime().toString());
    response.put("idleSeconds", idleSeconds);
    response.put("idleThresholdSeconds", threshold);
    response.put("secondsUntilAutoStop", remaining);
    response.put("autoStopEligible", idleSeconds >= threshold);

    return ResponseEntity.ok(response);
  }
}

