@Slf4j
@RestController
@RequestMapping("/admin/security")
@RequiredArgsConstructor
public class AdminController {

  private final IpFilterGlobalFilter ipFilterGlobalFilter;

  /**
   * Get current blacklist
   *
   * @return blacklisted IPs
   */
