  public ResponseEntity<ApiResponse<Set<String>>> getBlacklist() {
    Set<String> blacklist = ipFilterGlobalFilter.getBlacklist();
    return ResponseEntity.ok(ApiResponse.success(blacklist, "Current blacklist", 200));
