            "whitelistSize", ipFilterGlobalFilter.getWhitelist().size(),
            "whitelistModeEnabled", ipFilterGlobalFilter.isWhitelistModeEnabled());
    return ResponseEntity.ok(ApiResponse.success(status, "Security status", 200));
  }
