package dev.lmdb.gateway.exception;

import dev.lmdb.shared.dto.ErrorResponse;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import lombok.extern.slf4j.Slf4j;
import org.jspecify.annotations.NonNull;
import org.springframework.boot.webflux.error.ErrorWebExceptionHandler;
import org.springframework.core.annotation.Order;
import org.springframework.core.io.buffer.DataBuffer;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.server.reactive.ServerHttpResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

/**
 * Global error handler for API Gateway. Handles all exceptions and returns standardized error
 * responses.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
@Order(-2)
public class GlobalErrorWebExceptionHandler implements ErrorWebExceptionHandler {

  private final ObjectMapper objectMapper;

  public GlobalErrorWebExceptionHandler(ObjectMapper objectMapper) {
    this.objectMapper = objectMapper;
  }

  /**
   * Handles web exceptions and returns standardized error responses
   *
   * @param exchange the current server exchange
   * @param ex the exception to handle
   * @return Mono<Void> representing the completion of error handling
   */
  @Override
  @NonNull
  public Mono<Void> handle(@NonNull ServerWebExchange exchange, @NonNull Throwable ex) {
    ServerHttpResponse response = exchange.getResponse();

    // Determine HTTP status and error message
    HttpStatus httpStatus;
    String errorMessage;
    String errorCode;

    if (ex instanceof ResponseStatusException responseStatusException) {
      httpStatus = HttpStatus.valueOf(responseStatusException.getStatusCode().value());
      errorMessage = responseStatusException.getReason();
      errorCode = httpStatus.name();
    } else if (ex instanceof io.jsonwebtoken.JwtException) {
      httpStatus = HttpStatus.UNAUTHORIZED;
      errorMessage = "Invalid or expired JWT token";
      errorCode = "JWT_ERROR";
    } else if (ex instanceof IllegalArgumentException) {
      httpStatus = HttpStatus.BAD_REQUEST;
      errorMessage = ex.getMessage();
      errorCode = "BAD_REQUEST";
    } else {
      httpStatus = HttpStatus.INTERNAL_SERVER_ERROR;
      errorMessage = "An unexpected error occurred";
      errorCode = "INTERNAL_SERVER_ERROR";
    }

    // Log the error
    log.error(
        "Error handling request: {} - Status: {} - Message: {}",
        exchange.getRequest().getURI().getPath(),
        httpStatus.value(),
        errorMessage,
        ex);

    // Create error response
    ErrorResponse errorResponse =
        ErrorResponse.builder()
            .status(httpStatus.value())
            .errorCode(errorCode)
            .message(errorMessage)
            .path(exchange.getRequest().getURI().getPath())
            .build();

    // Set response status and content type
    response.setStatusCode(httpStatus);
    response.getHeaders().setContentType(MediaType.APPLICATION_JSON);

    // Write error response
    try {
      String json = objectMapper.writeValueAsString(errorResponse);
      byte[] bytes = Objects.requireNonNull(json.getBytes(StandardCharsets.UTF_8));
      DataBuffer buffer = Objects.requireNonNull(response.bufferFactory().wrap(bytes));
      return response.writeWith(Objects.requireNonNull(Mono.just(buffer)));
    } catch (JacksonException e) {
      log.error("Error serializing error response", e);
      return response.setComplete();
    }
  }
}

package dev.lmdb.gateway.filter;

import dev.lmdb.gateway.service.ActivityTrackingService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * Global filter for tracking backend user activity across the API Gateway.
 *
 * <p>Records timestamps of all real user requests (movies, actors, authentication, AI, search)
 * while intentionally ignoring internal actuator health checks, metric probes, and static fallbacks
 * so that automated monitoring does not prevent the 1-hour idle shutdown.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class ActivityTrackingFilter implements GlobalFilter, Ordered {

  private final ActivityTrackingService activityTrackingService;

  /**
   * Filters incoming requests to record activity for non-monitoring endpoints.
   *
   * @param exchange the current server exchange
   * @param chain the gateway filter chain
   * @return Mono<Void> representing filter completion
   */
  @Override
  public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
    String path = exchange.getRequest().getURI().getPath();

    // Do not count health probes or fallback error routes as user activity
    if (!isMonitoringOrFallbackPath(path)) {
      activityTrackingService.recordActivity();
      log.debug("User activity recorded on path: {}", path);
    }

    return chain.filter(exchange);
  }

  /**
   * Determines if a given URI path is an automated health check, metric query, or fallback route.
   *
   * @param path request URI path
   * @return true if the path is a monitoring probe
   */
  private boolean isMonitoringOrFallbackPath(String path) {
    if (path == null) {
      return false;
    }
    return path.startsWith("/actuator")
        || path.startsWith("/fallback")
        || path.equals("/favicon.ico");
  }

  /**
   * Sets filter precedence. Runs near the top of the filter chain.
   *
   * @return order index
   */
  @Override
  public int getOrder() {
    return Ordered.HIGHEST_PRECEDENCE + 5;
  }
}

package dev.lmdb.gateway.filter;

import java.time.Duration;
import java.util.Objects;
import java.util.Optional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * Global rate limiting filter to prevent DDoS attacks. Applies a global rate limit per IP address
 * across all routes.
 *
 * <p>This provides an additional layer of protection beyond per-service rate limits: - Prevents
 * attackers from bypassing limits by hitting multiple services - Sets a hard cap on total requests
 * per IP per second - Works in conjunction with service-specific rate limits
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
@RequiredArgsConstructor
@org.springframework.boot.autoconfigure.condition.ConditionalOnBean(
    org.springframework.data.redis.core.ReactiveRedisTemplate.class)
public class GlobalRateLimitFilter implements GlobalFilter, Ordered {

  private final ReactiveRedisTemplate<String, String> redisTemplate;

  private boolean enabled = true;

  // Global rate limit: 100 requests per second per IP
  private static final long GLOBAL_LIMIT = 100;
  private static final String REDIS_KEY_PREFIX = "global-rate-limit:";
  private static final Optional<Duration> EXPIRE_DURATION = Optional.of(Duration.ofSeconds(1L));

  /**
   * Filters requests to enforce global rate limiting
   *
   * @param exchange the current server exchange
   * @param chain the gateway filter chain
   * @return Mono<Void> representing the completion of filter processing
   */
  @Override
  public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
    // Skip if disabled (e.g., in tests)
    if (!enabled) {
      return chain.filter(exchange);
    }

    // Skip rate limiting for actuator endpoints
    String path = exchange.getRequest().getURI().getPath();
    if (path.startsWith("/actuator")) {
      return chain.filter(exchange);
    }

    String clientIp = getClientIp(exchange);
    String redisKey = REDIS_KEY_PREFIX + clientIp;

    return redisTemplate
        .opsForValue()
        .increment(redisKey)
        .flatMap(
            count -> {
              // Set expiration on first increment
              if (count == 1) {
                Duration expireDuration =
                    Objects.requireNonNull(
                        EXPIRE_DURATION.orElseGet(() -> Duration.ofSeconds(1L)),
                        "Expire duration must not be null");
                redisTemplate.expire(redisKey, expireDuration).subscribe();
              }

              // Check if limit exceeded
              if (count > GLOBAL_LIMIT) {
                log.warn(
                    "Global rate limit exceeded for IP: {} - {} requests/sec (limit: {})",
                    clientIp,
                    count,
                    GLOBAL_LIMIT);

                // Set response headers
                exchange
                    .getResponse()
                    .getHeaders()
                    .set("X-RateLimit-Limit", String.valueOf(GLOBAL_LIMIT));
                exchange.getResponse().getHeaders().set("X-RateLimit-Remaining", "0");
                exchange.getResponse().getHeaders().set("X-RateLimit-Reset", "1");

                // Return 429 Too Many Requests
                exchange.getResponse().setStatusCode(HttpStatus.TOO_MANY_REQUESTS);
                return exchange.getResponse().setComplete();
              }

              // Add rate limit headers
              long remaining = GLOBAL_LIMIT - count;
              exchange
                  .getResponse()
                  .getHeaders()
                  .set("X-RateLimit-Limit", String.valueOf(GLOBAL_LIMIT));
              exchange
                  .getResponse()
                  .getHeaders()
                  .set("X-RateLimit-Remaining", String.valueOf(remaining));

              log.debug(
                  "Global rate limit check passed for IP: {} - {}/{} requests",
                  clientIp,
                  count,
                  GLOBAL_LIMIT);

              return chain.filter(exchange);
            })
        .onErrorResume(
            e -> {
              // If Redis is down, allow the request to continue
              // (fail open to prevent service disruption)
              log.error(
                  "Redis error in global rate limiting: {}. Allowing request.", e.getMessage());
              return chain.filter(exchange);
            });
  }

  /**
   * Gets the client IP address from the request. Checks X-Forwarded-For header first (for proxied
   * requests), then remote address.
   *
   * @param exchange the server web exchange
   * @return the client IP address
   */
  private String getClientIp(ServerWebExchange exchange) {
    String forwardedFor = exchange.getRequest().getHeaders().getFirst("X-Forwarded-For");

    if (forwardedFor != null && !forwardedFor.isEmpty()) {
      // Get first IP from comma-separated list
      return forwardedFor.split(",")[0].trim();
    }

    // Fallback to remote address
    var remoteAddress = exchange.getRequest().getRemoteAddress();
    if (remoteAddress != null && remoteAddress.getAddress() != null) {
      return remoteAddress.getAddress().getHostAddress();
    }

    // Fallback to unknown if remote address cannot be determined
    log.warn("Unable to determine client IP address, using fallback");
    return "0.0.0.0";
  }

  /**
   * Sets the filter order (executes early in the filter chain, before authentication)
   *
   * @return the order value
   */
  @Override
  public int getOrder() {
    return Ordered.HIGHEST_PRECEDENCE + 2; // After logging filter
  }
}

package dev.lmdb.gateway.filter;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * IP filtering global filter for blacklist/whitelist functionality. Blocks requests from
 * blacklisted IPs and optionally restricts access to whitelisted IPs only.
 *
 * <p>Features: - IP blacklist for blocking malicious IPs - IP whitelist for restricting access to
 * trusted IPs (when enabled) - Thread-safe concurrent implementation - Logging of blocked requests
 * for security monitoring
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
public class IpFilterGlobalFilter implements GlobalFilter, Ordered {

  // Thread-safe sets for blacklist and whitelist
  private final Set<String> blacklist = ConcurrentHashMap.newKeySet();
  private final Set<String> whitelist = ConcurrentHashMap.newKeySet();

  // Control whether whitelist mode is enabled
  private boolean whitelistModeEnabled = false;

  /**
   * Filters requests based on IP blacklist/whitelist
   *
   * @param exchange the current server exchange
   * @param chain the gateway filter chain
   * @return Mono<Void> representing the completion of filter processing
   */
  @Override
  public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
    // Skip filtering for actuator endpoints (admin access)
    String path = exchange.getRequest().getURI().getPath();
    if (path.startsWith("/actuator")) {
      return chain.filter(exchange);
    }

    String clientIp = getClientIp(exchange);

    // Check whitelist mode (if enabled, only whitelisted IPs are allowed)
    if (whitelistModeEnabled && !whitelist.isEmpty() && !whitelist.contains(clientIp)) {
      log.warn("Access denied for non-whitelisted IP: {}", clientIp);
      return denyAccess(exchange, "IP not in whitelist");
    }

    // Check blacklist
    if (blacklist.contains(clientIp)) {
      log.warn("Access denied for blacklisted IP: {}", clientIp);
      return denyAccess(exchange, "IP is blacklisted");
    }

    // IP is allowed, continue filter chain
    return chain.filter(exchange);
  }

  /**
   * Denies access by returning HTTP 403 Forbidden
   *
   * @param exchange the server web exchange
   * @param reason the reason for denial
   * @return Mono<Void> with forbidden response
   */
  private Mono<Void> denyAccess(ServerWebExchange exchange, String reason) {
    exchange.getResponse().setStatusCode(HttpStatus.FORBIDDEN);
    exchange.getResponse().getHeaders().set("X-Blocked-Reason", reason);
    return exchange.getResponse().setComplete();
  }

  /**
   * Gets the client IP address from the request. Checks X-Forwarded-For header first (for proxied
   * requests), then remote address.
   *
   * @param exchange the server web exchange
   * @return the client IP address
   */
  private String getClientIp(ServerWebExchange exchange) {
    String forwardedFor = exchange.getRequest().getHeaders().getFirst("X-Forwarded-For");

    if (forwardedFor != null && !forwardedFor.isEmpty()) {
      return forwardedFor.split(",")[0].trim();
    }

    var remoteAddress = exchange.getRequest().getRemoteAddress();
    if (remoteAddress != null && remoteAddress.getAddress() != null) {
      return remoteAddress.getAddress().getHostAddress();
    }

    // Fallback to unknown if remote address cannot be determined
    log.warn("Unable to determine client IP address, using fallback");
    return "0.0.0.0";
  }

  /**
   * Adds an IP address to the blacklist
   *
   * @param ip the IP address to blacklist
   */
  public void addToBlacklist(String ip) {
    blacklist.add(ip);
    log.info("Added IP to blacklist: {}", ip);
  }

  /**
   * Removes an IP address from the blacklist
   *
   * @param ip the IP address to remove
   */
  public void removeFromBlacklist(String ip) {
    blacklist.remove(ip);
    log.info("Removed IP from blacklist: {}", ip);
  }

  /**
   * Adds an IP address to the whitelist
   *
   * @param ip the IP address to whitelist
   */
  public void addToWhitelist(String ip) {
    whitelist.add(ip);
    log.info("Added IP to whitelist: {}", ip);
  }

  /**
   * Removes an IP address from the whitelist
   *
   * @param ip the IP address to remove
   */
  public void removeFromWhitelist(String ip) {
    whitelist.remove(ip);
    log.info("Removed IP from whitelist: {}", ip);
  }

  /** Enables whitelist mode (only whitelisted IPs are allowed) */
  public void enableWhitelistMode() {
    whitelistModeEnabled = true;
    log.info("Whitelist mode enabled - only whitelisted IPs will be allowed");
  }

  /** Disables whitelist mode */
  public void disableWhitelistMode() {
    whitelistModeEnabled = false;
    log.info("Whitelist mode disabled");
  }

  /**
   * Gets the current blacklist
   *
   * @return set of blacklisted IPs
   */
  public Set<String> getBlacklist() {
    return Set.copyOf(blacklist);
  }

  /**
   * Gets the current whitelist
   *
   * @return set of whitelisted IPs
   */
  public Set<String> getWhitelist() {
    return Set.copyOf(whitelist);
  }

  /**
   * Checks if whitelist mode is enabled
   *
   * @return true if whitelist mode is enabled
   */
  public boolean isWhitelistModeEnabled() {
    return whitelistModeEnabled;
  }

  /**
   * Sets the filter order (executes first in the filter chain)
   *
   * @return the order value
   */
  @Override
  public int getOrder() {
    return Ordered.HIGHEST_PRECEDENCE; // Execute before all other filters
  }
}

package dev.lmdb.gateway.filter;

import dev.lmdb.gateway.util.JwtUtil;
import jakarta.annotation.Nonnull;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.server.reactive.ServerHttpRequest;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import org.springframework.web.server.WebFilter;
import org.springframework.web.server.WebFilterChain;
import reactor.core.publisher.Mono;

/**
 * Custom WebFilter for JWT authentication in API Gateway. Validates JWT tokens in incoming request
 * headers and populates reactive security context.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Component
@Slf4j
@RequiredArgsConstructor
public class JwtAuthenticationFilter implements WebFilter {

  private final JwtUtil jwtUtil;

  /**
   * Filters requests to validate JWT tokens
   *
   * @param exchange the current server exchange
   * @param chain the web filter chain
   * @return Mono&lt;Void&gt; representing the completion of filter processing
   */
  @Override
  @Nonnull
  public Mono<Void> filter(@Nonnull ServerWebExchange exchange, @Nonnull WebFilterChain chain) {
    ServerHttpRequest request = exchange.getRequest();
    String path = request.getURI().getPath();

    // Skip JWT validation for public endpoints
    if (isPublicPath(path)) {
      return chain.filter(exchange);
    }

    // Extract Authorization header
    String authHeader = request.getHeaders().getFirst(HttpHeaders.AUTHORIZATION);

    // If no Authorization header, continue without authentication
    if (authHeader == null || !authHeader.startsWith("Bearer ")) {
      log.debug("No valid Authorization header found for path: {}", path);
      return chain.filter(exchange);
    }

    try {
      // Extract and validate token
      String token = jwtUtil.extractTokenFromHeader(authHeader);

      if (token == null || !jwtUtil.validateToken(token)) {
        log.warn("Invalid JWT token for path: {}", path);
        exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
        return exchange.getResponse().setComplete();
      }

      // Extract user details from token
      String username = jwtUtil.extractUsername(token);
      String userId = jwtUtil.extractUserId(token);
      List<String> roles = jwtUtil.extractRoles(token);

      // Create authorities
      List<SimpleGrantedAuthority> authorities =
          roles.stream()
              .map(
                  role ->
                      role.startsWith("ROLE_")
                          ? new SimpleGrantedAuthority(role)
                          : new SimpleGrantedAuthority("ROLE_" + role))
              .toList();

      // Create Authentication object
      Authentication authentication =
          new UsernamePasswordAuthenticationToken(username, null, authorities);

      // Mutate request with user context headers for downstream microservices
      ServerHttpRequest mutatedRequest =
          request
              .mutate()
              .header("X-User-Id", userId != null ? userId : "")
              .header("X-Username", username != null ? username : "")
              .header("X-User-Roles", String.join(",", roles))
              .build();

      log.debug(
          "Successfully authenticated user: {} (ID: {}) for path: {}", username, userId, path);

      // Continue filter chain with mutated request and updated security context
      return chain
          .filter(exchange.mutate().request(mutatedRequest).build())
          .contextWrite(ReactiveSecurityContextHolder.withAuthentication(authentication));

    } catch (Exception e) {
      log.error("JWT authentication error for path: {}", path, e);
      exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
      return exchange.getResponse().setComplete();
    }
  }

  /**
   * Checks if the path is a public endpoint that doesn't require JWT validation
   *
   * @param path the request path
   * @return true if path is public, false otherwise
   */
  private boolean isPublicPath(String path) {
    return path.startsWith("/api/v1/auth/login")
        || path.startsWith("/api/v1/auth/register")
        || path.startsWith("/api/v1/auth/refresh")
        || path.startsWith("/actuator")
        || path.startsWith("/fallback")
        || (path.startsWith("/api/v1/movies") && !path.contains("/admin"))
        || (path.startsWith("/api/v1/actors") && !path.contains("/admin"));
  }
}

package dev.lmdb.gateway.filter;

import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.server.reactive.ServerHttpRequest;
import org.springframework.http.server.reactive.ServerHttpResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * Global logging filter for API Gateway. Logs all incoming requests and outgoing responses for
 * monitoring and debugging.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
public class LoggingFilter implements GlobalFilter, Ordered {

  /**
   * Filters requests and responses to log information
   *
   * @param exchange the current server exchange
   * @param chain the gateway filter chain
   * @return Mono<Void> representing the completion of filter processing
   */
  @Override
  public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
    ServerHttpRequest request = exchange.getRequest();
    ServerHttpResponse response = exchange.getResponse();

    // Log request details
    logRequest(request);

    // Record start time
    long startTime = System.currentTimeMillis();
    exchange.getAttributes().put("startTime", startTime);

    // Continue filter chain and log response
    return chain
        .filter(exchange)
        .doFinally(
            signalType -> {
              Long start = exchange.getAttribute("startTime");
              if (start != null) {
                long duration = System.currentTimeMillis() - start;
                logResponse(request, response, duration);
              }
            });
  }

  /**
   * Logs incoming request details
   *
   * @param request the server HTTP request
   */
  private void logRequest(ServerHttpRequest request) {
    String method = request.getMethod().toString();
    String path = request.getURI().getPath();
    String queryParams = request.getURI().getQuery();
    HttpHeaders headers = request.getHeaders();

    log.info("==> Incoming Request: {} {}", method, path);
    if (queryParams != null && !queryParams.isEmpty()) {
      log.debug("Query Parameters: {}", queryParams);
    }

    // Log important headers (avoid logging sensitive information)
    if (headers.containsHeader("User-Agent")) {
      log.debug("User-Agent: {}", headers.getFirst("User-Agent"));
    }
    if (headers.containsHeader("X-Forwarded-For")) {
      log.debug("X-Forwarded-For: {}", headers.getFirst("X-Forwarded-For"));
    }
  }

  /**
   * Logs outgoing response details
   *
   * @param request the server HTTP request
   * @param response the server HTTP response
   * @param duration the request processing duration in milliseconds
   */
  private void logResponse(ServerHttpRequest request, ServerHttpResponse response, long duration) {
    String method = request.getMethod().toString();
    String path = request.getURI().getPath();
    HttpStatusCode status = response.getStatusCode();
    int statusCode = status != null ? status.value() : 0;

    log.info(
        "<== Outgoing Response: {} {} - Status: {} - Duration: {}ms",
        method,
        path,
        statusCode,
        duration);

    // Log slow requests (> 1 second)
    if (duration > 1000) {
      log.warn("SLOW REQUEST DETECTED: {} {} took {}ms", method, path, duration);
    }
  }

  /**
   * Sets the filter order (executes early in the filter chain)
   *
   * @return the order value
   */
  @Override
  public int getOrder() {
    return Ordered.HIGHEST_PRECEDENCE + 1;
  }
}

package dev.lmdb.gateway.service;

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

/**
 * Service for tracking user activity on the API Gateway.
 *
 * <p>Maintains the timestamp of the most recent user request to determine if the cluster has been
 * idle for the 1-hour threshold and can be safely scaled to zero / stopped.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Service
public class ActivityTrackingService {

  /** Default auto-stop inactivity threshold: 1 hour (3600 seconds). */
  public static final long DEFAULT_IDLE_THRESHOLD_SECONDS = 3600L;

  /** Service startup timestamp. */
  private final Instant startTime = Instant.now();

  private final AtomicReference<Instant> lastActivityTime = new AtomicReference<>(Instant.now());

  /**
   * Returns the timestamp when this gateway instance started.
   *
   * @return Instant representing service start time
   */
  public Instant getStartTime() {
    return startTime;
  }

  /**
   * Calculates the total uptime in seconds since the service started.
   *
   * @return uptime duration in seconds
   */
  public long getUptimeSeconds() {
    return Duration.between(startTime, Instant.now()).getSeconds();
  }

  /** Records that an active user request was processed by the gateway. */
  public void recordActivity() {
    Instant now = Instant.now();
    lastActivityTime.set(now);
    log.trace("Recorded user activity at {}", now);
  }

  /**
   * Returns the timestamp of the latest user request.
   *
   * @return Instant of last activity
   */
  public Instant getLastActivityTime() {
    return lastActivityTime.get();
  }

  /**
   * Calculates the number of seconds elapsed since the last user request.
   *
   * @return idle duration in seconds
   */
  public long getIdleSeconds() {
    return Duration.between(lastActivityTime.get(), Instant.now()).getSeconds();
  }

  /**
   * Calculates the remaining seconds before the 1-hour auto-stop threshold is reached.
   *
   * @param thresholdSeconds the configured inactivity threshold in seconds
   * @return remaining seconds until auto-stop, or 0 if threshold is already exceeded
   */
  public long getSecondsUntilAutoStop(long thresholdSeconds) {
    long idle = getIdleSeconds();
    return Math.max(0L, thresholdSeconds - idle);
  }

  /**
   * Resets the activity timer to the current instant (used during service startup or manual
   * keep-alive).
   */
  public void reset() {
    lastActivityTime.set(Instant.now());
  }
}

package dev.lmdb.gateway.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import java.util.List;
import javax.crypto.SecretKey;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Utility class for JWT token operations. Handles token validation, extraction, and parsing.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Slf4j
@Component
public class JwtUtil {

  private final SecretKey secretKey;

  public JwtUtil(@Value("${jwt.secret}") String secret) {
    this.secretKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
  }

  /**
   * Extracts all claims from the JWT token
   *
   * @param token the JWT token
   * @return Claims object containing token claims
   */
  public Claims extractAllClaims(String token) {
    return Jwts.parser().verifyWith(secretKey).build().parseSignedClaims(token).getPayload();
  }

  /**
   * Extracts username (subject) from the JWT token
   *
   * @param token the JWT token
   * @return the username
   */
  public String extractUsername(String token) {
    return extractAllClaims(token).getSubject();
  }

  /**
   * Extracts user ID from the JWT token
   *
   * @param token the JWT token
   * @return the user ID
   */
  public String extractUserId(String token) {
    return extractAllClaims(token).get("userId", String.class);
  }

  /**
   * Extracts roles from the JWT token
   *
   * @param token the JWT token
   * @return list of roles
   */
  public List<String> extractRoles(String token) {
    Object rolesObj = extractAllClaims(token).get("roles");
    if (rolesObj instanceof List<?> rolesList) {
      return rolesList.stream()
          .map(obj -> obj instanceof String str ? str : String.valueOf(obj))
          .toList();
    }
    return List.of();
  }

  /**
   * Extracts expiration date from the JWT token
   *
   * @param token the JWT token
   * @return the expiration date
   */
  public Date extractExpiration(String token) {
    return extractAllClaims(token).getExpiration();
  }

  /**
   * Checks if the token is expired
   *
   * @param token the JWT token
   * @return true if token is expired, false otherwise
   */
  public boolean isTokenExpired(String token) {
    try {
      return extractExpiration(token).before(new Date());
    } catch (Exception e) {
      log.error("Error checking token expiration: {}", e.getMessage());
      return true;
    }
  }

  /**
   * Validates the JWT token
   *
   * @param token the JWT token
   * @return true if token is valid, false otherwise
   */
  public boolean validateToken(String token) {
    try {
      extractAllClaims(token);
      return !isTokenExpired(token);
    } catch (Exception e) {
      log.error("Token validation failed: {}", e.getMessage());
      return false;
    }
  }

  /**
   * Extracts token from Authorization header
   *
   * @param authHeader the Authorization header value
   * @return the JWT token or null if header is invalid
   */
  public String extractTokenFromHeader(String authHeader) {
    if (authHeader != null && authHeader.startsWith("Bearer ")) {
      return authHeader.substring(7);
    }
    return null;
  }
}

package dev.lmdb.discovery;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.netflix.eureka.server.EnableEurekaServer;

/**
 * Discovery Service Application - Eureka Server
 *
 * <p>This service acts as the service registry for the LMDB microservices architecture. It enables
 * service discovery and registration for all microservices in the system.
 *
 * <p>Key features:
 *
 * <ul>
 *   <li>Service registration and discovery
 *   <li>Health monitoring
 *   <li>Load balancing support
 *   <li>Web-based dashboard
 * </ul>
