package dev.lmdb.media.service;

import dev.lmdb.media.model.EntityType;
import dev.lmdb.media.model.MediaFile;
import dev.lmdb.media.model.MediaMetadata;
import dev.lmdb.media.model.MediaType;
import dev.lmdb.media.repository.MediaRepository;
import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

/**
 * Core business orchestration service responsible for handling user-uploaded media asset lifecycle
 * operations across MinIO object storage and MongoDB metadata collections.
 */
@Service
public class MediaService {

  private static final Logger log = LoggerFactory.getLogger(MediaService.class);

  private final MediaRepository mediaRepository;
  private final StorageService storageService;

  /**
   * Explicit constructor injection (no @Autowired field injection per project conventions).
   *
   * @param mediaRepository MongoDB repository interface for metadata documents.
   * @param storageService MinIO storage infrastructure operations handler.
   */
  public MediaService(MediaRepository mediaRepository, StorageService storageService) {
    this.mediaRepository = mediaRepository;
    this.storageService = storageService;
  }

  /**
   * Uploads physical binary payload to MinIO storage and records structured metadata in MongoDB.
   *
   * @param file Incoming multi-part client file payload stream.
   * @param entityId Target associated entity identifier (e.g. user UUID or review ID).
   * @param entityType Classification of target domain entity.
   * @param mediaType Classification of media content type.
   * @param metadata Technical specifications and dimensions record (optional).
   * @param uploadedBy User account identifier responsible for upload.
   * @return Persisted immutable {@link MediaFile} record document.
   * @throws IOException If accessing the file stream encounters an I/O failure.
   */
  public MediaFile uploadMedia(
      MultipartFile file,
      String entityId,
      EntityType entityType,
      MediaType mediaType,
      MediaMetadata metadata,
      String uploadedBy,
      String description)
      throws IOException {

    EntityType safeEntityType = entityType != null ? entityType : EntityType.USER;
    MediaType safeMediaType = mediaType != null ? mediaType : MediaType.IMAGE;
    String rawFilename = file.getOriginalFilename();
    String originalFilename = rawFilename != null ? rawFilename : "upload.dat";
    String rawContentType = file.getContentType();
    String contentType = rawContentType != null ? rawContentType : "application/octet-stream";

    String fileId = UUID.randomUUID().toString();
    String storagePath =
        String.format(
            "%s/%s/%s-%s",
            safeEntityType.name().toLowerCase(),
            entityId,
            fileId,
            originalFilename.replaceAll("[^a-zA-Z0-9.-]", "_"));

    log.info(
        "Starting ingestion for file '{}' (size {} bytes) targeting storage path: {}",
        originalFilename,
        file.getSize(),
        storagePath);

    // Persist raw bytes into MinIO S3 object bucket
    storageService.putObject(storagePath, file.getInputStream(), file.getSize(), contentType);

    // Generate responsive thumbnail URL references
    Map<String, String> thumbnails = storageService.generateThumbnails(fileId, originalFilename);

    MediaFile mediaFile =
        new MediaFile(
            fileId,
            entityId,
            safeEntityType,
            safeMediaType,
            originalFilename,
            storagePath,
            file.getSize(),
            contentType,
            thumbnails,
            metadata != null ? metadata : new MediaMetadata(null, null, null, null, null),
            Instant.now(),
            uploadedBy != null ? uploadedBy : "anonymous",
            description);

    MediaFile saved = mediaRepository.save(mediaFile);
    log.info("Successfully completed upload and metadata persistence for asset id: {}", saved.id());
    return saved;
  }

  /**
   * Retrieves specific media metadata document by unique file ID.
   *
   * @param id Target unique persistent UUID string.
   * @return Optional containing matching {@link MediaFile} if found.
   */
  public Optional<MediaFile> getMediaFile(String id) {
    return mediaRepository.findById(id);
  }

  /**
   * Opens raw binary streaming channel from MinIO storage for specified media asset ID.
   *
   * @param id Target persistent media asset UUID string.
   * @return Open readable {@link InputStream} delivering object bytes.
   * @throws RuntimeException If target file ID does not match any existing metadata record.
   */
  public InputStream getMediaStream(String id) {
    MediaFile mediaFile =
        mediaRepository
            .findById(id)
            .orElseThrow(() -> new RuntimeException("Media file not found for ID: " + id));
    return storageService.getObject(mediaFile.storagePath());
  }

  /**
   * Evicts media resource from both MinIO bucket storage and MongoDB database collections.
   *
   * @param id Target persistent media asset UUID string to delete.
   * @return true if resource was found and successfully purged; false otherwise.
   */
  public boolean deleteMediaFile(String id) {
    Optional<MediaFile> existing = mediaRepository.findById(id);
    if (existing.isEmpty()) {
      return false;
    }
    MediaFile mediaFile = existing.get();
    storageService.removeObject(mediaFile.storagePath());
    mediaRepository.deleteById(id);
    log.info("Purged asset '{}' from MinIO and MongoDB", id);
    return true;
  }

  /**
   * Queries all stored media uploads currently linked to a target domain entity identifier.
   *
   * @param entityId Target entity unique identifier string.
   * @return List of matching {@link MediaFile} record metadata documents.
   */
  public List<MediaFile> getMediaForEntity(String entityId) {
    return mediaRepository.findByEntityId(entityId);
  }
}

package dev.lmdb.media.service;

import io.minio.BucketExistsArgs;
import io.minio.GetObjectArgs;
import io.minio.MakeBucketArgs;
import io.minio.MinioClient;
import io.minio.PutObjectArgs;
import io.minio.RemoveObjectArgs;
import java.io.InputStream;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Low-level binary storage infrastructure service managing S3-compatible bucket persistence via
 * MinIO. Handles file ingestion streams, removal operations, retrieval downloads, and thumbnail
 * mapping.
 */
@Service
public class StorageService {

  private static final Logger log = LoggerFactory.getLogger(StorageService.class);

  private final MinioClient minioClient;
  private final String bucketName;

  /**
   * Explicit constructor injection (no @Autowired field injection per project conventions).
   *
   * @param minioClient Initialized MinIO S3 client bean.
   * @param bucketName Target storage bucket identifier from configuration properties.
   */
  public StorageService(
      MinioClient minioClient, @Value("${minio.bucket-name:lmdb-media}") String bucketName) {
    this.minioClient = minioClient;
    this.bucketName = bucketName;
  }

  /** Verifies target storage bucket existence in MinIO and initializes a new bucket if absent. */
  public void ensureBucketExists() {
    try {
      boolean found =
          minioClient.bucketExists(BucketExistsArgs.builder().bucket(bucketName).build());
      if (!found) {
        minioClient.makeBucket(MakeBucketArgs.builder().bucket(bucketName).build());
        log.info("Initialized new MinIO storage bucket: {}", bucketName);
      }
    } catch (Exception e) {
      log.error(
          "Failed executing storage bucket initialization check for '{}': {}",
          bucketName,
          e.getMessage());
      throw new RuntimeException("MinIO storage bucket verification failed", e);
    }
  }

  /**
   * Stores raw file binary stream in target MinIO storage bucket.
   *
   * @param objectKey Target persistent object identifier path in bucket.
   * @param stream Input stream delivering file payload bytes.
   * @param size Declared size footprint of payload in bytes.
   * @param contentType Standard MIME content classification header (e.g., image/jpeg).
   */
  public void putObject(String objectKey, InputStream stream, long size, String contentType) {
    ensureBucketExists();
    try {
      minioClient.putObject(
          PutObjectArgs.builder().bucket(bucketName).object(objectKey).stream(stream, size, -1)
              .contentType(contentType != null ? contentType : "application/octet-stream")
              .build());
      log.debug("Successfully persisted object '{}' to bucket '{}'", objectKey, bucketName);
    } catch (Exception e) {
      log.error("Failed uploading object '{}' to MinIO: {}", objectKey, e.getMessage(), e);
      throw new RuntimeException("Storage putObject failed for key: " + objectKey, e);
    }
  }

  /**
   * Retrieves readable binary input stream for stored media object.
   *
   * @param objectKey Persistent identifier path in bucket storage.
   * @return Open {@link InputStream} delivering object binary content.
   */
  public InputStream getObject(String objectKey) {
    try {
      return minioClient.getObject(
          GetObjectArgs.builder().bucket(bucketName).object(objectKey).build());
    } catch (Exception e) {
      log.error("Failed reading stream for object '{}' from MinIO: {}", objectKey, e.getMessage());
      throw new RuntimeException("Storage getObject failed for key: " + objectKey, e);
    }
  }

  /**
   * Evicts stored file object from target MinIO bucket storage.
   *
   * @param objectKey Persistent identifier path in bucket storage.
   */
  public void removeObject(String objectKey) {
    try {
      minioClient.removeObject(
          RemoveObjectArgs.builder().bucket(bucketName).object(objectKey).build());
      log.debug("Evicted object '{}' from bucket '{}'", objectKey, bucketName);
    } catch (Exception e) {
      log.warn(
          "Failed removing object '{}' from MinIO (may already be deleted): {}",
          objectKey,
          e.getMessage());
    }
  }

  /**
   * Generates thumbnail rendering reference URLs for uploaded media files.
   *
   * @param fileId UUID string assigned to the uploaded media resource.
   * @param originalFilename Client supplied filename used for format routing.
   * @return Immutable mapping connecting standard sizing keys to download URLs.
   */
  public Map<String, String> generateThumbnails(String fileId, String originalFilename) {
    // Generates accessible endpoint URL mappings pointing back to media-service download endpoints
    String baseUrl = "/api/v1/media/" + fileId + "/download?size=";
    return Map.of(
        "thumb", baseUrl + "small",
        "medium", baseUrl + "medium",
        "original", "/api/v1/media/" + fileId + "/download");
  }
}

