@RequiredArgsConstructor
@Slf4j
@Tag(name = "Movie API", description = "Endpoints for movie discovery, search, and details")
public class MovieController {

  private final MovieService movieService;

  /**
   * Get movie details by TMDB ID.
   *
   * @param id TMDB movie ID
   * @return Movie details as a HATEOAS resource (self + sub-resource links)
   */
  @GetMapping("/{id}")
  @Operation(
      summary = "Get movie by ID",
      description = "Retrieve detailed movie information by TMDB ID")
  public ResponseEntity<EntityModel<MovieDto>> getMovieById(
      @Parameter(description = "TMDB movie ID", example = "550") @PathVariable("id") Long id) {
    log.info("GET /api/v1/movies/{} - Fetching movie details", id);
    MovieDto movie = movieService.getMovieById(id);
    // A movie detail advertises how to reach its own sub-resources, so a
    // client never has to construct these URLs itself.
    EntityModel<MovieDto> model =
        EntityModel.of(
            movie,
            linkTo(methodOn(MovieController.class).getMovieById(id)).withSelfRel(),
            linkTo(methodOn(MovieController.class).getMovieVideos(id)).withRel("videos"),
            linkTo(methodOn(MovieController.class).getMovieCredits(id)).withRel("credits"),
            linkTo(methodOn(MovieController.class).getSimilarMovies(id, 1, 20)).withRel("similar"),
            linkTo(methodOn(MovieController.class).getRecommendedMovies(id, 1, 20))
                .withRel("recommendations"));
    return ResponseEntity.ok(model);
  }

  /**
   * Discover movies with filters.
   *
   * @param page Page number (1-based)
   * @param size Page size
   * @param genreId Genre ID filter
   * @param year Release year filter
   * @param minRating Minimum rating filter
   * @return Page of movies
   */
  @GetMapping("/discover")
  @Operation(summary = "Discover movies", description = "Discover movies with various filters")
  public ResponseEntity<PageResponse<MovieListDto>> discoverMovies(
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size,
      @Parameter(description = "Genre ID filter", example = "28")
          @RequestParam(value = "genreId", required = false)
          Long genreId,
      @Parameter(description = "Release year filter", example = "2024")
          @RequestParam(value = "year", required = false)
          Integer year,
      @Parameter(description = "Minimum rating filter", example = "7.0")
          @RequestParam(value = "minRating", required = false)
          Double minRating) {
    log.info(
        "GET /api/v1/movies/discover - page={}, size={}, genre={}, year={}, minRating={}",
        page,
        size,
        genreId,
        year,
        minRating);
    return ResponseEntity.ok(movieService.discoverMovies(page, size, genreId, year, minRating));
  }

  /**
   * Search movies by query.
   *
   * @param query Search query
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of movies
   */
  @GetMapping("/search")
  @Operation(summary = "Search movies", description = "Search movies by title or keywords")
  public ResponseEntity<PageResponse<MovieListDto>> searchMovies(
      @Parameter(description = "Search query", example = "Inception", required = true)
          @RequestParam(value = "query")
          String query,
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/search - query={}, page={}", query, page);
    return ResponseEntity.ok(movieService.searchMovies(query, page, size));
  }

  /**
   * Get trending movies.
   *
   * @param timeWindow Time window (day or week)
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of trending movies
   */
  @GetMapping("/trending")
  @Operation(
      summary = "Get trending movies",
      description = "Get trending movies for the day or week")
  public ResponseEntity<PageResponse<MovieListDto>> getTrendingMovies(
      @Parameter(description = "Time window (day or week)", example = "week")
          @RequestParam(value = "timeWindow", defaultValue = "week")
          String timeWindow,
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/trending - timeWindow={}, page={}", timeWindow, page);
    return ResponseEntity.ok(movieService.getTrendingMovies(timeWindow, page, size));
  }

  /**
   * Get popular movies.
   *
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of popular movies
   */
  @GetMapping("/popular")
  @Operation(summary = "Get popular movies", description = "Get currently popular movies")
  public ResponseEntity<PageResponse<MovieListDto>> getPopularMovies(
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/popular - page={}", page);
    return ResponseEntity.ok(movieService.getPopularMovies(page, size));
  }

  /**
   * Get top-rated movies.
   *
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of top-rated movies
   */
  @GetMapping("/top-rated")
  @Operation(summary = "Get top-rated movies", description = "Get highest-rated movies of all time")
  public ResponseEntity<PageResponse<MovieListDto>> getTopRatedMovies(
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/top-rated - page={}", page);
    return ResponseEntity.ok(movieService.getTopRatedMovies(page, size));
  }

  /**
   * Get movie videos (trailers, clips).
   *
   * @param id TMDB movie ID
   * @return List of videos
   */
  @GetMapping("/{id}/videos")
  @Operation(summary = "Get movie videos", description = "Get trailers and clips for a movie")
  public ResponseEntity<List<VideoDto>> getMovieVideos(
      @Parameter(description = "TMDB movie ID", example = "550") @PathVariable("id") Long id) {
    log.info("GET /api/v1/movies/{}/videos - Fetching videos", id);
    return ResponseEntity.ok(movieService.getMovieVideos(id));
  }

  /**
   * Get movie credits (cast and crew).
   *
   * @param id TMDB movie ID
   * @return Credits
   */
  @GetMapping("/{id}/credits")
  @Operation(
      summary = "Get movie credits",
      description = "Get cast and crew information for a movie")
  public ResponseEntity<CreditsDto> getMovieCredits(
      @Parameter(description = "TMDB movie ID", example = "550") @PathVariable("id") Long id) {
    log.info("GET /api/v1/movies/{}/credits - Fetching credits", id);
    return ResponseEntity.ok(movieService.getMovieCredits(id));
  }

  /**
   * Get similar movies.
   *
   * @param id TMDB movie ID
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of similar movies
   */
  @GetMapping("/{id}/similar")
  @Operation(
      summary = "Get similar movies",
      description = "Get movies similar to the specified movie")
  public ResponseEntity<PageResponse<MovieListDto>> getSimilarMovies(
      @Parameter(description = "TMDB movie ID", example = "550") @PathVariable("id") Long id,
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/{}/similar - page={}", id, page);
    return ResponseEntity.ok(movieService.getSimilarMovies(id, page, size));
  }

  /**
   * Get recommended movies.
   *
   * @param id TMDB movie ID
   * @param page Page number (1-based)
   * @param size Page size
   * @return Page of recommended movies
   */
  @GetMapping("/{id}/recommendations")
  @Operation(
      summary = "Get movie recommendations",
      description = "Get recommended movies based on the specified movie")
  public ResponseEntity<PageResponse<MovieListDto>> getRecommendedMovies(
      @Parameter(description = "TMDB movie ID", example = "550") @PathVariable("id") Long id,
      @Parameter(description = "Page number", example = "1")
          @RequestParam(value = "page", defaultValue = "1")
          int page,
      @Parameter(description = "Page size", example = "20")
          @RequestParam(value = "size", defaultValue = "20")
          int size) {
    log.info("GET /api/v1/movies/{}/recommendations - page={}", id, page);
    return ResponseEntity.ok(movieService.getRecommendedMovies(id, page, size));
  }

  @ExceptionHandler(ResourceNotFoundException.class)
  ProblemDetail handleNotFound(ResourceNotFoundException e) {
    return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
  }
}

package dev.lmdb.movie.event;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

/**
 * Asynchronous producer responsible for emitting TMDB save-through notifications to Kafka topic
 * {@code tmdb.document.saved}.
 *
 * <p>Event publication occurs asynchronously on a background thread, ensuring that broker
 * unavailability or slow network IO never impacts latency or stability of caller threads. Any Kafka
 * producer exceptions are logged at WARN level and suppressed without throwing.
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class TmdbEventProducer {

  public static final String TOPIC_TMDB_DOCUMENT_SAVED = "tmdb.document.saved";

  private final KafkaTemplate<String, String> kafkaTemplate;
  private final ObjectMapper objectMapper;

  /**
   * Asynchronously constructs and transmits a {@link TmdbDocumentSavedEvent} to the Kafka cluster.
   *
   * @param canonicalKey canonical resource routing key
   * @param endpointType functional categorization of the invoked facade endpoint
   * @param path relative request path executed by the client
   */
  public void publishDocumentSavedEvent(String canonicalKey, String endpointType, String path) {
    // 1. Construct immutable event payload with unique UUID for consumer deduplication
    TmdbDocumentSavedEvent event =
        TmdbDocumentSavedEvent.builder()
            .eventId(UUID.randomUUID().toString())
            .key(canonicalKey)
            .endpointType(endpointType)
            .path(path)
            .timestamp(System.currentTimeMillis())
            .build();

    // 2. Dispatch asynchronously via CompletableFuture to isolate HTTP request threads from broker
    // delays
    CompletableFuture.runAsync(
        () -> {
          try {
            String jsonPayload = objectMapper.writeValueAsString(event);
            kafkaTemplate
                .send(TOPIC_TMDB_DOCUMENT_SAVED, canonicalKey, jsonPayload)
                .whenComplete(
                    (result, ex) -> {
                      if (ex != null) {
                        log.warn(
                            "Failed to deliver save-through event to topic {} for key {}: {}",
                            TOPIC_TMDB_DOCUMENT_SAVED,
                            canonicalKey,
                            ex.getMessage());
                      } else {
                        log.debug(
                            "Successfully emitted event {} to partition {} at offset {}",
                            event.eventId(),
                            result.getRecordMetadata().partition(),
                            result.getRecordMetadata().offset());
                      }
                    });
          } catch (Exception e) {
            log.warn(
                "Exception suppressed while dispatching save-through event for key {}: {}",
                canonicalKey,
                e.getMessage());
          }
        });
  }
}

package dev.lmdb.movie.facade;

import com.fasterxml.jackson.annotation.JsonProperty;
import dev.lmdb.movie.client.TmdbClient;
import dev.lmdb.movie.client.dto.TmdbCreditsResponse;
import dev.lmdb.movie.client.dto.TmdbGenresResponse;
import dev.lmdb.movie.client.dto.TmdbMovieListResponse;
import dev.lmdb.movie.client.dto.TmdbMovieResponse;
import dev.lmdb.movie.client.dto.TmdbVideosResponse;
import dev.lmdb.movie.event.TmdbEventProducer;
import dev.lmdb.movie.model.Cast;
import dev.lmdb.movie.model.Credits;
import dev.lmdb.movie.model.Crew;
import dev.lmdb.movie.model.Movie;
import dev.lmdb.movie.model.Video;
import dev.lmdb.movie.service.MovieService;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClientResponseException;

/**
 * TMDB v3-compatible facade controller — the primary API of the platform.
 *
 * <p>Exposes the exact TMDB v3 paths the LMDB React app calls (extracted from its {@code
 * src/services/TMDB.js}; see ARCHITECTURE.md §5.1), with TMDB's own field names and response
 * envelopes preserved. As of ADR-010, the data behind these responses is our own persisted, mapped
 * {@link Movie} catalog (via {@link MovieService}) rather than a raw cached copy of TMDB's bytes:
 * detail lookups are read-through/save-through against MongoDB, and list endpoints call TMDB live
 * for ranking while upserting every result they see. Only the wire shape is TMDB's; the data is
 * ours.
 *
 * <p>Auth/account endpoints ({@code /authentication/**}, {@code /account/**}) are NOT here — those
 * are being retargeted at LMDB's own user-service JWT flow rather than proxied to real TMDB (see
 * the follow-up to #33).
 */
@RestController
@Slf4j
@RequiredArgsConstructor
public class TmdbFacadeController {

  /**
   * TMDB's fixed movie-list categories under {@code /movie/{category}}. Anything else in that path
   * position must be a numeric movie id.
   */
  private static final Set<String> MOVIE_CATEGORIES =
      Set.of("popular", "top_rated", "upcoming", "now_playing");

  private static final String PAGE_SEPARATOR = ":page:";

  @SuppressWarnings("java:S1075")
  private static final String MOVIE_PATH_PREFIX = "/movie/";

  private final MovieService movieService;
  private final TmdbEventProducer eventProducer;

  /**
   * {@code GET /genre/movie/list} — the genre catalog (React app sidebar).
   *
   * @return TMDB-shaped genre list
   */
  @GetMapping(value = "/genre/movie/list", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<TmdbGenresResponse> genreList() {
    TmdbGenresResponse response = movieService.getGenresRaw();
    eventProducer.publishDocumentSavedEvent("genre:list", "GENRE_LIST", "/genre/movie/list");
    return ResponseEntity.ok(response);
  }

  /**
   * {@code GET /movie/{idOrCategory}} — TMDB overloads this path position: a fixed category name
   * (popular, top_rated, upcoming, now_playing) yields a movie list, while a numeric id yields
   * movie details (the React app requests details with {@code append_to_response=videos,credits}).
   *
   * @param idOrCategory category name or numeric TMDB movie id
   * @param page page number, for the category-list case
   * @param appendToResponse comma-separated sub-resources to embed (videos, credits)
   * @return TMDB-shaped movie list or movie detail JSON
   */
  @GetMapping(value = "/movie/{idOrCategory}", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<Object> movieByIdOrCategory(
      @PathVariable String idOrCategory,
      @RequestParam(defaultValue = "1") int page,
      @RequestParam(name = "append_to_response", required = false) String appendToResponse) {

    // 1. Fixed category name → volatile list endpoint.
    if (MOVIE_CATEGORIES.contains(idOrCategory)) {
      TmdbMovieListResponse response = movieService.getMovieCategoryRaw(idOrCategory, page);
      eventProducer.publishDocumentSavedEvent(
          "category:" + idOrCategory + PAGE_SEPARATOR + page,
          "MOVIE_CATEGORY",
          MOVIE_PATH_PREFIX + idOrCategory);
      return ResponseEntity.ok(response);
    }

    // 2. Numeric id → near-immutable movie details, read-through/save-through.
    if (idOrCategory.chars().allMatch(Character::isDigit)) {
      Long id = Long.parseLong(idOrCategory);
      Set<String> appends = parseAppendToResponse(appendToResponse);
      Movie movie = movieService.getMovieForFacade(id, appends);
      eventProducer.publishDocumentSavedEvent(
          "movie:" + idOrCategory, "MOVIE_DETAIL", MOVIE_PATH_PREFIX + idOrCategory);
      return ResponseEntity.ok(toTmdbMovieResponse(movie, appends));
    }

    // 3. Neither → replay TMDB's own not-found error shape.
    log.debug("TMDB facade: unknown movie category/id '{}'", idOrCategory);
    return notFound();
  }

  /**
   * {@code GET /movie/{id}/recommendations} — recommendations for a movie (React app details page).
   *
   * @param id numeric TMDB movie id
   * @param page page number
   * @return TMDB-shaped movie list
   */
  @GetMapping(value = "/movie/{id}/recommendations", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<TmdbMovieListResponse> recommendations(
      @PathVariable Long id, @RequestParam(defaultValue = "1") int page) {
    TmdbMovieListResponse response = movieService.getRecommendedMoviesRaw(id, page);
    eventProducer.publishDocumentSavedEvent(
        "recommendations:" + id + PAGE_SEPARATOR + page,
        "RECOMMENDATIONS",
        MOVIE_PATH_PREFIX + id + "/recommendations");
    return ResponseEntity.ok(response);
  }

  /**
   * {@code GET /movie/{id}/similar} — similar movies (React app details page fallback when
   * recommendations are empty).
   *
   * @param id numeric TMDB movie id
   * @param page page number
   * @return TMDB-shaped movie list
   */
  @GetMapping(value = "/movie/{id}/similar", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<TmdbMovieListResponse> similar(
      @PathVariable Long id, @RequestParam(defaultValue = "1") int page) {
    TmdbMovieListResponse response = movieService.getSimilarMoviesRaw(id, page);
    eventProducer.publishDocumentSavedEvent(
        "similar:" + id + PAGE_SEPARATOR + page, "SIMILAR", MOVIE_PATH_PREFIX + id + "/similar");
    return ResponseEntity.ok(response);
  }

  /**
   * {@code GET /discover/movie} — filtered discovery. Covers both React app uses: by genre ({@code
   * with_genres}) and by cast member ({@code with_cast}).
   *
   * @param page page number
   * @param genreId {@code with_genres} filter
   * @param year release-year filter
   * @param minRating {@code vote_average.gte} filter
   * @param castId {@code with_cast} filter (TMDB person id)
   * @return TMDB-shaped movie list
   */
  @GetMapping(value = "/discover/movie", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<TmdbMovieListResponse> discover(
      @RequestParam(defaultValue = "1") int page,
      @RequestParam(name = "with_genres", required = false) Long genreId,
      @RequestParam(required = false) Integer year,
      @RequestParam(name = "vote_average.gte", required = false) Double minRating,
      @RequestParam(name = "with_cast", required = false) Long castId) {
    TmdbMovieListResponse response =
        movieService.discoverMoviesRaw(page, genreId, year, minRating, castId);
    eventProducer.publishDocumentSavedEvent(
        "discover" + PAGE_SEPARATOR + page, "DISCOVER", "/discover/movie");
    return ResponseEntity.ok(response);
  }

  /**
   * {@code GET /search/movie} — free-text search.
   *
   * @param query search query
   * @param page page number
   * @return TMDB-shaped movie list
   */
  @GetMapping(value = "/search/movie", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<TmdbMovieListResponse> search(
      @RequestParam String query, @RequestParam(defaultValue = "1") int page) {
    TmdbMovieListResponse response = movieService.searchMoviesRaw(query, page);
    eventProducer.publishDocumentSavedEvent(
        "search:query:" + query + PAGE_SEPARATOR + page, "SEARCH", "/search/movie");
    return ResponseEntity.ok(response);
  }

  /**
   * Replays a real TMDB error response byte-for-byte: {@link TmdbClient} calls go through Spring's
   * RestClient, which captures the upstream body on a non-2xx response — reusing it preserves
   * TMDB's exact error shape without us having to construct it.
   *
   * @param e the captured upstream HTTP error
   * @return response mirroring TMDB's error exactly
   */
  @ExceptionHandler(RestClientResponseException.class)
  public ResponseEntity<String> upstreamError(RestClientResponseException e) {
    return ResponseEntity.status(e.getStatusCode())
        .contentType(MediaType.APPLICATION_JSON)
        .body(e.getResponseBodyAsString());
  }

  /**
   * Maps "TMDB unreachable" to 502 Bad Gateway with a TMDB-shaped error body, so even total-failure
   * responses keep the contract's shape.
   *
   * @param e network failure reaching TMDB
   * @return 502 response with TMDB-style error JSON
   */
  @ExceptionHandler(ResourceAccessException.class)
  public ResponseEntity<TmdbErrorResponse> tmdbUnreachable(ResourceAccessException e) {
    log.error("TMDB unreachable: {}", e.getMessage());
    return ResponseEntity.status(502)
        .body(new TmdbErrorResponse(false, 502, "Upstream TMDB API is unreachable."));
  }

  /**
   * Parses TMDB's {@code append_to_response} query param into a set of requested sub-resource
   * names.
   *
   * @param appendToResponse raw comma-separated param value, or null
   * @return requested sub-resource names (empty if none requested)
   */
  private static Set<String> parseAppendToResponse(String appendToResponse) {
    if (appendToResponse == null || appendToResponse.isBlank()) {
      return Set.of();
    }
    return Arrays.stream(appendToResponse.split(","))
        .map(String::trim)
        .filter(s -> !s.isEmpty())
        .collect(java.util.stream.Collectors.toSet());
  }

  /**
   * Builds TMDB's exact detail response shape from our persisted entity, embedding videos/credits
   * only when requested (and thus populated by {@link MovieService#getMovieForFacade}) — matching
   * TMDB's own behavior of only including {@code videos}/{@code credits} keys when {@code
   * append_to_response} asked for them.
   *
   * @param movie the persisted movie
   * @param appends requested sub-resources
   * @return TMDB-shaped movie detail response
   */
  private static TmdbMovieResponse toTmdbMovieResponse(Movie movie, Set<String> appends) {
    return new TmdbMovieResponse(
        movie.getTmdbId(),
        movie.getTitle(),
        movie.getOriginalTitle(),
        movie.getOverview(),
        movie.getPosterPath(),
        movie.getBackdropPath(),
        movie.getReleaseDate(),
        movie.getVoteAverage(),
        movie.getVoteCount(),
        movie.getGenres(),
        movie.getRuntime(),
        movie.getStatus(),
        movie.getBudget(),
        movie.getRevenue(),
        movie.getSpokenLanguages(),
        movie.getProductionCompanies(),
        movie.getProductionCountries(),
        movie.getBelongsToCollection(),
        movie.getVideo(),
        movie.getOriginalLanguage(),
        movie.getPopularity(),
        movie.getAdult(),
        movie.getImdbId(),
        movie.getTagline(),
        movie.getHomepage(),
        appends.contains("videos") ? toTmdbVideosResponse(movie) : null,
        appends.contains("credits") ? toTmdbCreditsResponse(movie) : null);
  }

  private static TmdbVideosResponse toTmdbVideosResponse(Movie movie) {
    List<Video> videos = movie.getVideos() != null ? movie.getVideos() : List.of();
    return new TmdbVideosResponse(
        movie.getTmdbId(),
        videos.stream()
            .map(
                v ->
                    new TmdbVideosResponse.TmdbVideo(
                        v.getId(),
                        v.getKey(),
                        v.getName(),
                        v.getSite(),
                        v.getSize(),
                        v.getType(),
                        v.getOfficial(),
                        v.getPublishedAt()))
            .toList());
  }

  private static TmdbCreditsResponse toTmdbCreditsResponse(Movie movie) {
    Credits credits = movie.getCredits();
    List<Cast> cast = credits != null && credits.getCast() != null ? credits.getCast() : List.of();
    List<Crew> crew = credits != null && credits.getCrew() != null ? credits.getCrew() : List.of();
    return new TmdbCreditsResponse(
        movie.getTmdbId(),
        cast.stream()
            .map(
                c ->
                    new TmdbCreditsResponse.TmdbCast(
                        c.getId(),
                        c.getName(),
                        c.getCharacter(),
                        c.getProfilePath(),
                        c.getOrder(),
                        null))
            .toList(),
        crew.stream()
            .map(
                c ->
                    new TmdbCreditsResponse.TmdbCrew(
                        c.getId(),
                        c.getName(),
                        c.getJob(),
                        c.getDepartment(),
                        c.getProfilePath(),
                        null))
            .toList());
  }

  private static ResponseEntity<Object> notFound() {
    return ResponseEntity.status(HttpStatus.NOT_FOUND)
        .body(new TmdbErrorResponse(false, 34, "The resource you requested could not be found."));
  }

  /**
   * TMDB's own error envelope shape, replayed for locally-detected error cases (unknown
   * category/id, upstream unreachable) that don't have a captured upstream body to forward
   * verbatim.
   *
   * @param success always false
   * @param statusCode TMDB's numeric status code (not the HTTP status)
   * @param statusMessage human-readable message
   */
  private record TmdbErrorResponse(
      boolean success,
      @JsonProperty("status_code") int statusCode,
      @JsonProperty("status_message") String statusMessage) {}
}

