package dev.lmdb.shared.dto;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonUnwrapped;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Decorates a single-resource payload with HAL-style {@code _links} while staying inside the shared
 * {@link ApiResponse} envelope.
 *
 * <p>Spring HATEOAS's own {@code EntityModel} only gets HAL treatment ({@code _links} as a
 * rel-keyed map) from Spring Boot's hypermedia message converter when it is the controller method's
 * top-level return type; nested inside {@code ApiResponse<T>} it silently falls back to plain
 * Jackson bean serialization, i.e. a {@code "links": [...]} array instead of {@code "_links":
 * {...}}. This type sidesteps that by unwrapping the content's own fields ({@link JsonUnwrapped})
 * and serializing a hand-built {@code _links} map alongside them — the caller still uses Spring
 * HATEOAS's {@code linkTo}/{@code methodOn} to build each href, only the wrapping differs.
 *
 * @param <T> the wrapped resource type
 * @see ApiResponse
 */
public class HalResource<T> {

  @JsonUnwrapped private final T content;

  @JsonProperty("_links")
  private final Map<String, Href> links = new LinkedHashMap<>();

  private HalResource(T content) {
    this.content = content;
  }

  /**
   * Wraps a resource with no links yet.
   *
   * @param content the resource payload
   * @param <T> resource type
   * @return a new, link-less HalResource; add links with {@link #withLink}
   */
  public static <T> HalResource<T> of(T content) {
    return new HalResource<>(content);
  }

  /**
   * Adds a named relation link.
   *
   * @param rel the link relation name (e.g. {@code "self"}, {@code "movies"})
   * @param href the target URI
   * @return this instance, for fluent chaining
   */
  public HalResource<T> withLink(String rel, String href) {
    links.put(rel, new Href(href));
    return this;
  }

  /**
   * @return the wrapped resource payload
   */
  public T getContent() {
    return content;
  }

  /**
   * @return the resource's links, keyed by relation name
   */
  public Map<String, Href> getLinks() {
    return links;
  }

  /**
   * A single HAL link target — just the href, matching the subset of the HAL spec this codebase
   * currently uses (no templated or typed links).
   *
   * @param href the target URI
   */
  public record Href(String href) {}
}

package dev.lmdb.shared.dto;

import java.io.Serial;
import java.io.Serializable;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Generic paginated response wrapper for list endpoints. Provides pagination metadata and data in a
 * consistent structure.
 *
 * <p>{@code T} is bounded to {@link Serializable} deliberately. This type is returned from
 * {@code @Cacheable} service methods, and the Redis cache here uses JDK serialization — so a page
 * whose elements are not serializable fails at runtime with {@code NotSerializableException} on the
 * first cache write. Bounding the parameter turns that into a compile error at the call site
 * instead (see ADR-011 and the movie-service model classes, which had to be made {@code
 * Serializable} after exactly that failure reached production).
 *
 * @param <T> the type of items in the page; must be {@link Serializable} because pages are cached
 *     via JDK serialization
 * @author LMDB Development Team
 * @version 1.0.0
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class PageResponse<T extends Serializable> implements Serializable {
  @Serial private static final long serialVersionUID = 1L;

  /** List of items in the current page */
  private List<T> content;

  /** Current page number (zero-indexed) */
  private int pageNumber;

  /** Number of items per page */
  private int pageSize;

  /** Total number of elements across all pages */
  private long totalElements;

  /** Total number of pages */
  private int totalPages;

  /** Whether this is the first page */
  private boolean first;

  /** Whether this is the last page */
  private boolean last;

  /** Whether there are more pages after this one */
  private boolean hasNext;

  /** Whether there are pages before this one */
  private boolean hasPrevious;

  /** Number of items in the current page */
  private int numberOfElements;

  /**
   * Creates a page response from pagination data
   *
   * @param content list of items
   * @param pageNumber current page number (zero-indexed)
   * @param pageSize items per page
   * @param totalElements total number of items
   * @param <T> data type
   * @return PageResponse
   */
  public static <T extends Serializable> PageResponse<T> of(
      List<T> content, int pageNumber, int pageSize, long totalElements) {

    int totalPages = (int) Math.ceil((double) totalElements / pageSize);

    return PageResponse.<T>builder()
        .content(content)
        .pageNumber(pageNumber)
        .pageSize(pageSize)
        .totalElements(totalElements)
        .totalPages(totalPages)
        .first(pageNumber == 0)
        .last(pageNumber >= totalPages - 1)
        .hasNext(pageNumber < totalPages - 1)
        .hasPrevious(pageNumber > 0)
        .numberOfElements(content.size())
        .build();
  }

  /**
   * Creates an empty page response
   *
   * @param pageNumber current page number
   * @param pageSize items per page
   * @param <T> data type
   * @return empty PageResponse
   */
  public static <T extends Serializable> PageResponse<T> empty(int pageNumber, int pageSize) {
    return PageResponse.<T>builder()
        .content(List.of())
        .pageNumber(pageNumber)
        .pageSize(pageSize)
        .totalElements(0)
        .totalPages(0)
        .first(true)
        .last(true)
        .hasNext(false)
        .hasPrevious(false)
        .numberOfElements(0)
        .build();
  }
}

