package dev.lmdb.shared.util;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Date;

/**
 * Utility class for date and time operations.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
public final class DateUtils {

  /**
   * Private constructor to prevent instantiation of this date/time utility class.
   *
   * @throws UnsupportedOperationException always, to prevent execution via reflection
   */
  private DateUtils() {
    throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }

  private static final DateTimeFormatter ISO_DATE_TIME_FORMATTER = DateTimeFormatter.ISO_DATE_TIME;
  private static final DateTimeFormatter DEFAULT_DATE_FORMATTER =
      DateTimeFormatter.ofPattern("yyyy-MM-dd");
  private static final DateTimeFormatter DEFAULT_DATE_TIME_FORMATTER =
      DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

  /**
   * Gets the current LocalDateTime
   *
   * @return current LocalDateTime
   */
  public static LocalDateTime now() {
    return LocalDateTime.now();
  }

  /**
   * Gets the current LocalDate
   *
   * @return current LocalDate
   */
  public static LocalDate today() {
    return LocalDate.now();
  }

  /**
   * Converts LocalDateTime to Date
   *
   * @param localDateTime the LocalDateTime to convert
   * @return Date object
   */
  public static Date toDate(LocalDateTime localDateTime) {
    if (localDateTime == null) {
      return null;
    }
    return Date.from(localDateTime.atZone(ZoneId.systemDefault()).toInstant());
  }

  /**
   * Converts Date to LocalDateTime
   *
   * @param date the Date to convert
   * @return LocalDateTime object
   */
  public static LocalDateTime toLocalDateTime(Date date) {
    if (date == null) {
      return null;
    }
    return LocalDateTime.ofInstant(date.toInstant(), ZoneId.systemDefault());
  }

  /**
   * Formats LocalDateTime to string using default format
   *
   * @param dateTime the LocalDateTime to format
   * @return formatted string
   */
  public static String format(LocalDateTime dateTime) {
    if (dateTime == null) {
      return null;
    }
    return dateTime.format(DEFAULT_DATE_TIME_FORMATTER);
  }

  /**
   * Formats LocalDate to string using default format
   *
   * @param date the LocalDate to format
   * @return formatted string
   */
  public static String format(LocalDate date) {
    if (date == null) {
      return null;
    }
    return date.format(DEFAULT_DATE_FORMATTER);
  }

  /**
   * Formats LocalDateTime to string using custom pattern
   *
   * @param dateTime the LocalDateTime to format
   * @param pattern the pattern to use
   * @return formatted string
   */
  public static String format(LocalDateTime dateTime, String pattern) {
    if (dateTime == null || pattern == null) {
      return null;
    }
    return dateTime.format(DateTimeFormatter.ofPattern(pattern));
  }

  /**
   * Parses string to LocalDateTime using default format
   *
   * @param dateTimeString the string to parse
   * @return LocalDateTime object
   * @throws DateTimeParseException if the string cannot be parsed
   */
  public static LocalDateTime parseDateTime(String dateTimeString) {
    if (dateTimeString == null || dateTimeString.trim().isEmpty()) {
      return null;
    }
    return LocalDateTime.parse(dateTimeString, DEFAULT_DATE_TIME_FORMATTER);
  }

  /**
   * Parses string to LocalDate using default format
   *
   * @param dateString the string to parse
   * @return LocalDate object
   * @throws DateTimeParseException if the string cannot be parsed
   */
  public static LocalDate parseDate(String dateString) {
    if (dateString == null || dateString.trim().isEmpty()) {
      return null;
    }
    return LocalDate.parse(dateString, DEFAULT_DATE_FORMATTER);
  }

  /**
   * Parses ISO 8601 formatted string to LocalDateTime
   *
   * @param isoString the ISO string to parse
   * @return LocalDateTime object
   */
  public static LocalDateTime parseIsoDateTime(String isoString) {
    if (isoString == null || isoString.trim().isEmpty()) {
      return null;
    }
    return LocalDateTime.parse(isoString, ISO_DATE_TIME_FORMATTER);
  }

  /**
   * Calculates the difference in days between two dates
   *
   * @param start the start date
   * @param end the end date
   * @return number of days between start and end
   */
  public static long daysBetween(LocalDate start, LocalDate end) {
    if (start == null || end == null) {
      return 0;
    }
    return ChronoUnit.DAYS.between(start, end);
  }

  /**
   * Calculates the elapsed hours between two date-times.
   *
   * <p>The arguments are resolved against {@link ZoneId#systemDefault()} before the difference is
   * taken (the same convention {@link #toDate} uses). This matters across a daylight-saving
   * transition: counting on bare {@link LocalDateTime} compares wall-clock readings, so a span
   * crossing a DST boundary is off by the shift — 01:00 to 03:00 on a spring-forward day is one
   * elapsed hour, not two. Resolving to a zone first yields real elapsed time.
   *
   * @param start the start date-time
   * @param end the end date-time
   * @return number of elapsed hours between start and end
   */
  public static long hoursBetween(LocalDateTime start, LocalDateTime end) {
    if (start == null || end == null) {
      return 0;
    }
    ZoneId zone = ZoneId.systemDefault();
    return ChronoUnit.HOURS.between(start.atZone(zone), end.atZone(zone));
  }

  /**
   * Checks if a date is in the past
   *
   * @param date the date to check
   * @return true if the date is before today
   */
  public static boolean isPast(LocalDate date) {
    return date != null && date.isBefore(LocalDate.now());
  }

  /**
   * Checks if a date is in the future
   *
   * @param date the date to check
   * @return true if the date is after today
   */
  public static boolean isFuture(LocalDate date) {
    return date != null && date.isAfter(LocalDate.now());
  }

  /**
   * Checks if a date-time is within the last N hours
   *
   * @param dateTime the date-time to check
   * @param hours number of hours
   * @return true if the date-time is within the last N hours
   */
  public static boolean isWithinLastHours(LocalDateTime dateTime, long hours) {
    if (dateTime == null) {
      return false;
    }
    LocalDateTime threshold = LocalDateTime.now().minusHours(hours);
    return dateTime.isAfter(threshold);
  }

  /**
   * Adds days to a date
   *
   * @param date the date
   * @param days number of days to add
   * @return new LocalDate with days added
   */
  public static LocalDate addDays(LocalDate date, long days) {
    if (date == null) {
      return null;
    }
    return date.plusDays(days);
  }

  /**
   * Adds hours to a date-time
   *
   * @param dateTime the date-time
   * @param hours number of hours to add
   * @return new LocalDateTime with hours added
   */
  public static LocalDateTime addHours(LocalDateTime dateTime, long hours) {
    if (dateTime == null) {
      return null;
    }
    return dateTime.plusHours(hours);
  }

  /**
   * Gets the start of the day for a given date-time
   *
   * @param dateTime the date-time
   * @return LocalDateTime at 00:00:00
   */
  public static LocalDateTime startOfDay(LocalDateTime dateTime) {
    if (dateTime == null) {
      return null;
    }
    return dateTime.truncatedTo(ChronoUnit.DAYS);
  }

  /**
   * Gets the end of the day for a given date-time
   *
   * @param dateTime the date-time
   * @return LocalDateTime at 23:59:59.999999999
   */
  public static LocalDateTime endOfDay(LocalDateTime dateTime) {
    if (dateTime == null) {
      return null;
    }
    return dateTime.truncatedTo(ChronoUnit.DAYS).plusDays(1).minusNanos(1);
  }

  /**
   * Converts epoch milliseconds to LocalDateTime
   *
   * @param epochMilli epoch milliseconds
   * @return LocalDateTime object
   */
  public static LocalDateTime fromEpochMilli(long epochMilli) {
    return LocalDateTime.ofInstant(Instant.ofEpochMilli(epochMilli), ZoneId.systemDefault());
  }

  /**
   * Converts LocalDateTime to epoch milliseconds
   *
   * @param dateTime the LocalDateTime
   * @return epoch milliseconds
   */
  public static long toEpochMilli(LocalDateTime dateTime) {
    if (dateTime == null) {
      return 0;
    }
    return dateTime.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
  }
}

package dev.lmdb.shared.util;

import java.util.Arrays;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Utility class for string operations.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
public final class StringUtils {

  /**
   * Private constructor to prevent instantiation of this string utility class.
   *
   * @throws UnsupportedOperationException always, to prevent execution via reflection
   */
  private StringUtils() {
    throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }

  private static final Pattern EMAIL_PATTERN =
      Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");

  private static final Pattern URL_PATTERN =
      Pattern.compile("^(https?|ftp)://[^\\s/$.?#].[^\\s]*$");

  /**
   * Checks if a string is null or empty
   *
   * @param str the string to check
   * @return true if the string is null or empty
   */
  public static boolean isEmpty(String str) {
    return str == null || str.isEmpty();
  }

  /**
   * Checks if a string is null, empty, or contains only whitespace
   *
   * @param str the string to check
   * @return true if the string is blank
   */
  public static boolean isBlank(String str) {
    return str == null || str.trim().isEmpty();
  }

  /**
   * Checks if a string is not empty
   *
   * @param str the string to check
   * @return true if the string is not null and not empty
   */
  public static boolean isNotEmpty(String str) {
    return !isEmpty(str);
  }

  /**
   * Checks if a string is not blank
   *
   * @param str the string to check
   * @return true if the string is not null and contains non-whitespace characters
   */
  public static boolean isNotBlank(String str) {
    return !isBlank(str);
  }

  /**
   * Returns a default value if the string is null or empty
   *
   * @param str the string to check
   * @param defaultValue the default value to return
   * @return the string if not empty, otherwise the default value
   */
  public static String defaultIfEmpty(String str, String defaultValue) {
    return isEmpty(str) ? defaultValue : str;
  }

  /**
   * Returns a default value if the string is null or blank
   *
   * @param str the string to check
   * @param defaultValue the default value to return
   * @return the string if not blank, otherwise the default value
   */
  public static String defaultIfBlank(String str, String defaultValue) {
    return isBlank(str) ? defaultValue : str;
  }

  /**
   * Trims a string, returning null if the result is empty
   *
   * @param str the string to trim
   * @return trimmed string or null
   */
  public static String trimToNull(String str) {
    if (str == null) {
      return null;
    }
    String trimmed = str.trim();
    return trimmed.isEmpty() ? null : trimmed;
  }

  /**
   * Capitalizes the first letter of a string
   *
   * @param str the string to capitalize
   * @return capitalized string
   */
  public static String capitalize(String str) {
    if (isEmpty(str)) {
      return str;
    }
    return str.substring(0, 1).toUpperCase() + str.substring(1);
  }

  /**
   * Converts a string to camelCase
   *
   * @param str the string to convert
   * @return camelCase string
   */
  public static String toCamelCase(String str) {
    if (isEmpty(str)) {
      return str;
    }
    String[] parts = str.split("[\\s_-]+");
    StringBuilder result = new StringBuilder();
    boolean first = true;
    for (String part : parts) {
      if (!part.isEmpty()) {
        if (first) {
          result.append(part.toLowerCase());
          first = false;
        } else {
          result.append(capitalize(part.toLowerCase()));
        }
      }
    }
    return result.toString();
  }

  /**
   * Converts a string to snake_case
   *
   * @param str the string to convert
   * @return snake_case string
   */
  public static String toSnakeCase(String str) {
    if (isEmpty(str)) {
      return str;
    }
    return str.replaceAll("([a-z])([A-Z])", "$1_$2").replaceAll("[\\s-]+", "_").toLowerCase();
  }

  /**
   * Truncates a string to a specified length
   *
   * @param str the string to truncate
   * @param maxLength maximum length
   * @return truncated string
   */
  public static String truncate(String str, int maxLength) {
    if (isEmpty(str) || str.length() <= maxLength) {
      return str;
    }
    return str.substring(0, maxLength);
  }

  /**
   * Truncates a string and adds ellipsis
   *
   * @param str the string to truncate
   * @param maxLength maximum length (including ellipsis)
   * @return truncated string with ellipsis
   */
  public static String truncateWithEllipsis(String str, int maxLength) {
    if (isEmpty(str) || str.length() <= maxLength) {
      return str;
    }
    if (maxLength < 3) {
      return str.substring(0, maxLength);
    }
    return str.substring(0, maxLength - 3) + "...";
  }

  /**
   * Validates if a string is a valid email address
   *
   * @param email the string to validate
   * @return true if valid email format
   */
  public static boolean isValidEmail(String email) {
    if (isEmpty(email)) {
      return false;
    }
    return EMAIL_PATTERN.matcher(email).matches();
  }

  /**
   * Validates if a string is a valid URL
   *
   * @param url the string to validate
   * @return true if valid URL format
   */
  public static boolean isValidUrl(String url) {
    if (isEmpty(url)) {
      return false;
    }
    return URL_PATTERN.matcher(url).matches();
  }

  /**
   * Masks a string, showing only the first and last N characters
   *
   * @param str the string to mask
   * @param visibleChars number of visible characters at start and end
   * @param maskCharacter character to use for masking
   * @return masked string
   */
  public static String mask(String str, int visibleChars, char maskCharacter) {
    if (isEmpty(str) || str.length() <= visibleChars * 2) {
      return str;
    }
    String start = str.substring(0, visibleChars);
    String end = str.substring(str.length() - visibleChars);
    int maskLength = str.length() - (visibleChars * 2);
    String mask = String.valueOf(maskCharacter).repeat(maskLength);
    return start + mask + end;
  }

  /**
   * Masks an email address
   *
   * @param email the email to mask
   * @return masked email (e.g., "jo***@ex***.com")
   */
  public static String maskEmail(String email) {
    if (!isValidEmail(email)) {
      return email;
    }
    String[] parts = email.split("@");
    String localPart = parts[0];
    String domain = parts[1];

    String maskedLocal =
        localPart.length() >= 2 ? localPart.substring(0, 2) + "***" : localPart + "***";

    String[] domainParts = domain.split("\\.");
    String domainName = domainParts[0];
    String maskedDomainName =
        domainName.length() >= 2 ? domainName.substring(0, 2) + "***" : domainName + "***";

    // Reconstruct domain with remaining parts
    StringBuilder maskedDomain = new StringBuilder(maskedDomainName);
    for (int i = 1; i < domainParts.length; i++) {
      maskedDomain.append(".").append(domainParts[i]);
    }

    return maskedLocal + "@" + maskedDomain;
  }

  /**
   * Joins an array of strings with a delimiter
   *
   * @param delimiter the delimiter
   * @param elements the elements to join
   * @return joined string
   */
  public static String join(String delimiter, String... elements) {
    if (elements == null || elements.length == 0) {
      return "";
    }
    return Arrays.stream(elements)
        .filter(StringUtils::isNotNull)
        .collect(Collectors.joining(delimiter));
  }

  /**
   * Joins a list of strings with a delimiter
   *
   * @param delimiter the delimiter
   * @param elements the list of elements to join
   * @return joined string
   */
  public static String join(String delimiter, List<String> elements) {
    if (elements == null || elements.isEmpty()) {
      return "";
    }
    return elements.stream().filter(StringUtils::isNotNull).collect(Collectors.joining(delimiter));
  }

  /**
   * Removes all whitespace from a string
   *
   * @param str the string
   * @return string without whitespace
   */
  public static String removeWhitespace(String str) {
    if (isEmpty(str)) {
      return str;
    }
    return str.replaceAll("\\s+", "");
  }

  /**
   * Checks if a string contains only digits
   *
   * @param str the string to check
   * @return true if string contains only digits
   */
  public static boolean isNumeric(String str) {
    if (isEmpty(str)) {
      return false;
    }
    return str.matches("\\d+");
  }

  /**
   * Checks if a string contains only alphabetic characters
   *
   * @param str the string to check
   * @return true if string contains only letters
   */
  public static boolean isAlphabetic(String str) {
    if (isEmpty(str)) {
      return false;
    }
    return str.matches("[a-zA-Z]+");
  }

  /**
   * Checks if a string contains only alphanumeric characters
   *
   * @param str the string to check
   * @return true if string contains only letters and digits
   */
  public static boolean isAlphanumeric(String str) {
    if (isEmpty(str)) {
      return false;
    }
    return str.matches("[a-zA-Z0-9]+");
  }

  private static boolean isNotNull(String str) {
    return str != null;
  }
}

package dev.lmdb.shared.util;

import dev.lmdb.shared.exception.ValidationException;
import java.util.Collection;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Utility class for validation operations.
 *
 * @author LMDB Development Team
 * @version 1.0.0
 */
public final class ValidationUtils {

  /**
   * Private constructor to prevent instantiation of this validation utility class.
   *
   * @throws UnsupportedOperationException always, to prevent execution via reflection
   */
  private ValidationUtils() {
    throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }

  private static final Pattern PASSWORD_PATTERN =
      Pattern.compile("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[@$!%*?&])[A-Za-z\\d@$!%*?&]{8,}$");

  /**
   * Validates that an object is not null
   *
   * @param obj the object to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if object is null
   */
  public static void notNull(Object obj, String fieldName) {
    if (obj == null) {
      throw new ValidationException(fieldName, fieldName + " must not be null");
    }
  }

  /**
   * Validates that a string is not empty
   *
   * @param str the string to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if string is empty
   */
  public static void notEmpty(String str, String fieldName) {
    if (StringUtils.isEmpty(str)) {
      throw new ValidationException(fieldName, fieldName + " must not be empty");
    }
  }

  /**
   * Validates that a string is not blank
   *
   * @param str the string to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if string is blank
   */
  public static void notBlank(String str, String fieldName) {
    if (StringUtils.isBlank(str)) {
      throw new ValidationException(fieldName, fieldName + " must not be blank");
    }
  }

  /**
   * Validates that a collection is not empty
   *
   * @param collection the collection to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if collection is empty
   */
  public static void notEmpty(Collection<?> collection, String fieldName) {
    if (collection == null || collection.isEmpty()) {
      throw new ValidationException(fieldName, fieldName + " must not be empty");
    }
  }

  /**
   * Validates string length
   *
   * @param str the string to validate
   * @param minLength minimum length (inclusive)
   * @param maxLength maximum length (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if length is invalid
   */
  public static void length(String str, int minLength, int maxLength, String fieldName) {
    if (str == null) {
      return;
    }
    int length = str.length();
    if (length < minLength || length > maxLength) {
      throw new ValidationException(
          fieldName,
          String.format(
              "%s length must be between %d and %d characters", fieldName, minLength, maxLength));
    }
  }

  /**
   * Validates minimum string length
   *
   * @param str the string to validate
   * @param minLength minimum length (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if length is less than minimum
   */
  public static void minLength(String str, int minLength, String fieldName) {
    if (str != null && str.length() < minLength) {
      throw new ValidationException(
          fieldName, String.format("%s must be at least %d characters long", fieldName, minLength));
    }
  }

  /**
   * Validates maximum string length
   *
   * @param str the string to validate
   * @param maxLength maximum length (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if length exceeds maximum
   */
  public static void maxLength(String str, int maxLength, String fieldName) {
    if (str != null && str.length() > maxLength) {
      throw new ValidationException(
          fieldName, String.format("%s must not exceed %d characters", fieldName, maxLength));
    }
  }

  /**
   * Validates that a number is within a range
   *
   * @param value the number to validate
   * @param min minimum value (inclusive)
   * @param max maximum value (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if value is out of range
   */
  public static void range(Number value, Number min, Number max, String fieldName) {
    if (value == null) {
      return;
    }
    double val = value.doubleValue();
    double minVal = min.doubleValue();
    double maxVal = max.doubleValue();

    if (val < minVal || val > maxVal) {
      throw new ValidationException(
          fieldName, String.format("%s must be between %s and %s", fieldName, min, max));
    }
  }

  /**
   * Validates minimum value
   *
   * @param value the number to validate
   * @param min minimum value (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if value is less than minimum
   */
  public static void min(Number value, Number min, String fieldName) {
    if (value != null && value.doubleValue() < min.doubleValue()) {
      throw new ValidationException(
          fieldName, String.format("%s must be at least %s", fieldName, min));
    }
  }

  /**
   * Validates maximum value
   *
   * @param value the number to validate
   * @param max maximum value (inclusive)
   * @param fieldName the field name for error message
   * @throws ValidationException if value exceeds maximum
   */
  public static void max(Number value, Number max, String fieldName) {
    if (value != null && value.doubleValue() > max.doubleValue()) {
      throw new ValidationException(
          fieldName, String.format("%s must not exceed %s", fieldName, max));
    }
  }

  /**
   * Validates email format
   *
   * @param email the email to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if email format is invalid
   */
  public static void email(String email, String fieldName) {
    if (email != null && !StringUtils.isValidEmail(email)) {
      throw new ValidationException(fieldName, fieldName + " must be a valid email address");
    }
  }

  /**
   * Validates URL format
   *
   * @param url the URL to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if URL format is invalid
   */
  public static void url(String url, String fieldName) {
    if (url != null && !StringUtils.isValidUrl(url)) {
      throw new ValidationException(fieldName, fieldName + " must be a valid URL");
    }
  }

  /**
   * Validates password strength Requirements: At least 8 characters, one uppercase, one lowercase,
   * one digit, one special character
   *
   * @param password the password to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if password doesn't meet requirements
   */
  public static void password(String password, String fieldName) {
    if (password == null) {
      return;
    }
    if (!PASSWORD_PATTERN.matcher(password).matches()) {
      throw new ValidationException(
          fieldName,
          fieldName
              + " must be at least 8 characters long and contain uppercase, lowercase, digit, and special character");
    }
  }

  /**
   * Validates that a string matches a pattern
   *
   * @param str the string to validate
   * @param pattern the regex pattern
   * @param fieldName the field name for error message
   * @throws ValidationException if string doesn't match pattern
   */
  public static void pattern(String str, Pattern pattern, String fieldName) {
    if (str != null && !pattern.matcher(str).matches()) {
      throw new ValidationException(fieldName, fieldName + " has invalid format");
    }
  }

  /**
   * Validates that a value is positive
   *
   * @param value the number to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if value is not positive
   */
  public static void positive(Number value, String fieldName) {
    if (value != null && value.doubleValue() <= 0) {
      throw new ValidationException(fieldName, fieldName + " must be positive");
    }
  }

  /**
   * Validates that a value is non-negative
   *
   * @param value the number to validate
   * @param fieldName the field name for error message
   * @throws ValidationException if value is negative
   */
  public static void nonNegative(Number value, String fieldName) {
    if (value != null && value.doubleValue() < 0) {
      throw new ValidationException(fieldName, fieldName + " must not be negative");
    }
  }

  /**
   * Validates that a value is in a collection
   *
   * @param value the value to validate
   * @param collection the allowed values
   * @param fieldName the field name for error message
   * @throws ValidationException if value is not in collection
   */
  public static void in(Object value, Collection<?> collection, String fieldName) {
    if (value != null && !collection.contains(value)) {
      throw new ValidationException(
          fieldName, String.format("%s must be one of: %s", fieldName, collection));
    }
  }

  /**
   * Validates that two values are equal
   *
   * @param value1 first value
   * @param value2 second value
   * @param fieldName1 first field name
   * @param fieldName2 second field name
   * @throws ValidationException if values are not equal
   */
  public static void equals(Object value1, Object value2, String fieldName1, String fieldName2) {
    if (value1 == null && value2 == null) {
      return;
    }
    if (value1 == null || !value1.equals(value2)) {
      throw new ValidationException(
          fieldName1, String.format("%s and %s must match", fieldName1, fieldName2));
    }
  }

  /**
   * Validates all conditions and throws exception if any fail
   *
   * @param fieldErrors map of field names to error messages
   * @throws ValidationException if map is not empty
   */
  public static void validate(Map<String, String> fieldErrors) {
    if (fieldErrors != null && !fieldErrors.isEmpty()) {
      throw new ValidationException("Validation failed", fieldErrors);
    }
  }
}

package dev.lmdb.user;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * User Service Application. Manages user authentication, authorization, and profile data. Eureka
 * client is auto-configured when eureka-client dependency is present.
 */
@SpringBootApplication
public class UserServiceApplication {

  public static void main(String[] args) {
    SpringApplication.run(UserServiceApplication.class, args);
  }
}

package dev.lmdb.user.controller;

import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.user.dto.AuthDtos.AuthResponse;
import dev.lmdb.user.dto.AuthDtos.LoginRequest;
import dev.lmdb.user.dto.AuthDtos.RefreshRequest;
import dev.lmdb.user.dto.AuthDtos.RegisterRequest;
import dev.lmdb.user.service.AuthService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Authentication endpoints (issue #17): register, login, refresh, logout.
 *
 * <p>All routes under {@code /api/v1/auth} are public except logout, which requires the caller's
 * access token (SecurityConfig permits the path; logout itself reads the authenticated principal
 * and no-ops without one). Responses use the shared {@link ApiResponse} envelope like every native
 * LMDB endpoint.
 */
@RestController
@RequestMapping("/api/v1/auth")
@RequiredArgsConstructor
@Tag(name = "Authentication", description = "Register, login, token refresh and logout")
public class AuthController {

  private final AuthService authService;

  /**
   * Registers a new account and returns an immediate token bundle.
   *
   * @param request validated registration payload
   * @return 201 with access + refresh tokens and the new profile
   */
  @PostMapping("/register")
  @Operation(summary = "Register a new user account")
  public ResponseEntity<ApiResponse<AuthResponse>> register(
      @Valid @RequestBody RegisterRequest request) {
    AuthResponse auth = authService.register(request);
    return ResponseEntity.status(HttpStatus.CREATED)
        .body(
            ApiResponse.success(auth, "User registered successfully", HttpStatus.CREATED.value()));
  }

  /**
   * Authenticates credentials and returns a token bundle.
   *
   * @param request username + password
   * @return 200 with access + refresh tokens
   */
  @PostMapping("/login")
  @Operation(summary = "Authenticate and obtain tokens")
  public ResponseEntity<ApiResponse<AuthResponse>> login(@Valid @RequestBody LoginRequest request) {
    AuthResponse auth = authService.login(request);
    return ResponseEntity.ok(ApiResponse.success(auth, "Login successful", HttpStatus.OK.value()));
  }

  /**
   * Exchanges a refresh token for a new token pair (rotation — the presented refresh token is
   * invalidated).
   *
   * @param request the opaque refresh token
   * @return 200 with a brand-new token bundle
   */
  @PostMapping("/refresh")
  @Operation(summary = "Rotate the refresh token and obtain a new access token")
  public ResponseEntity<ApiResponse<AuthResponse>> refresh(
      @Valid @RequestBody RefreshRequest request) {
    AuthResponse auth = authService.refresh(request.refreshToken());
    return ResponseEntity.ok(ApiResponse.success(auth, "Token refreshed", HttpStatus.OK.value()));
  }

  /**
   * Logs out the authenticated caller by revoking all their refresh tokens. The current access
   * token stays valid until natural expiry — a documented property of stateless JWTs.
   *
   * @param authentication caller identity from the JWT filter (may be null when called without a
   *     token — then a no-op)
   * @return 200 acknowledgement
   */
  @PostMapping("/logout")
  @Operation(summary = "Revoke all refresh tokens of the current user")
  public ResponseEntity<ApiResponse<Void>> logout(Authentication authentication) {
    if (authentication != null) {
      authService.logout(authentication.getName());
    }
    return ResponseEntity.ok(ApiResponse.success(null, "Logged out", HttpStatus.OK.value()));
  }
}

package dev.lmdb.user.controller;

import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.shared.exception.BusinessException;
import dev.lmdb.shared.exception.ResourceNotFoundException;
import dev.lmdb.shared.exception.UnauthorizedException;
import dev.lmdb.shared.exception.ValidationException;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Maps exceptions to the shared {@link ApiResponse} error envelope with the appropriate HTTP
 * status, keeping error responses consistent across the user-service API (and with the other LMDB
 * services).
 */
@RestControllerAdvice
@Slf4j
public class GlobalExceptionHandler {

  /**
   * Bean-validation failures on request bodies → 400 with a compact field-by-field summary.
   *
   * @param e validation failure raised by {@code @Valid}
   * @return 400 error envelope listing the offending fields
   */
  @ExceptionHandler(MethodArgumentNotValidException.class)
  public ResponseEntity<ApiResponse<Void>> handleInvalidBody(MethodArgumentNotValidException e) {
    String details =
        e.getBindingResult().getFieldErrors().stream()
            .map(err -> err.getField() + ": " + err.getDefaultMessage())
            .collect(Collectors.joining("; "));
    return error(HttpStatus.BAD_REQUEST, "Validation failed — " + details);
  }

  /**
   * Domain validation failures (duplicate username/email, …) → 400.
   *
   * @param e domain validation error
   * @return 400 error envelope
   */
  @ExceptionHandler(ValidationException.class)
  public ResponseEntity<ApiResponse<Void>> handleValidation(ValidationException e) {
    return error(HttpStatus.BAD_REQUEST, e.getMessage());
  }

  /**
   * Authentication failures (bad credentials, invalid/expired refresh token, wrong current
   * password) → 401.
   *
   * @param e authentication error
   * @return 401 error envelope
   */
  @ExceptionHandler(UnauthorizedException.class)
  public ResponseEntity<ApiResponse<Void>> handleUnauthorized(UnauthorizedException e) {
    return error(HttpStatus.UNAUTHORIZED, e.getMessage());
  }

  /**
   * Missing resources (account deleted after token issue) → 404.
   *
   * @param e not-found error
   * @return 404 error envelope
   */
  @ExceptionHandler(ResourceNotFoundException.class)
  public ResponseEntity<ApiResponse<Void>> handleNotFound(ResourceNotFoundException e) {
    return error(HttpStatus.NOT_FOUND, e.getMessage());
  }

  /**
   * Business-rule conflicts → 409.
   *
   * @param e business error
   * @return 409 error envelope
   */
  @ExceptionHandler(BusinessException.class)
  public ResponseEntity<ApiResponse<Void>> handleBusiness(BusinessException e) {
    return error(HttpStatus.CONFLICT, e.getMessage());
  }

  /**
   * Anything unanticipated → 500 with a generic message; the detail goes to the log only (never
   * leak internals to clients).
   *
   * @param e unexpected error
   * @return 500 error envelope
   */
  @ExceptionHandler(Exception.class)
  public ResponseEntity<ApiResponse<Void>> handleUnexpected(Exception e) {
    log.error("Unhandled exception in user-service", e);
    return error(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected error occurred");
  }

  /**
   * Builds the standard error response.
   *
   * @param status HTTP status to return
   * @param message client-safe error description
   * @return response entity with the shared error envelope
   */
  private static ResponseEntity<ApiResponse<Void>> error(HttpStatus status, String message) {
    return ResponseEntity.status(status).body(ApiResponse.error(message, status.value()));
  }
}

package dev.lmdb.user.controller;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.linkTo;
import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.methodOn;

import dev.lmdb.shared.dto.ApiResponse;
import dev.lmdb.shared.dto.HalResource;
import dev.lmdb.user.dto.AuthDtos.ChangePasswordRequest;
import dev.lmdb.user.dto.AuthDtos.MovieListEntryResponse;
import dev.lmdb.user.dto.AuthDtos.UpdateProfileRequest;
import dev.lmdb.user.dto.AuthDtos.UserProfileResponse;
import dev.lmdb.user.service.UserAccountService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Profile, favorites and watchlist endpoints for the authenticated user (issue #17). Every route
 * requires a valid Bearer token; the acting user is always the token's subject — no cross-user
 * access exists.
 *
 * <p>The profile resource is HATEOAS-enriched (HAL {@code _links}), matching the pattern
 * established in movie-service and actor-service: it advertises links to itself and its
 * favorites/watchlist sub-resources so a client discovers navigation instead of hard-coding URLs.
 * Mutations (update profile, password change, favorites/watchlist writes) stay plain — only the
 * single-resource GET is decorated.
 */
@RestController
@RequestMapping("/api/v1/users")
@RequiredArgsConstructor
@Tag(name = "Users", description = "Profile, favorites and watchlist of the authenticated user")
public class UserController {

  private final UserAccountService userAccountService;

  /**
   * Returns the caller's profile.
   *
   * @param auth caller identity (JWT subject)
   * @return 200 with the profile as a HATEOAS resource (self + favorites/watchlist links)
   */
  @GetMapping("/profile")
  @Operation(summary = "Get the current user's profile")
  public ResponseEntity<ApiResponse<HalResource<UserProfileResponse>>> getProfile(
      Authentication auth) {
    UserProfileResponse profile = userAccountService.getProfile(auth.getName());
    // HATEOAS: the profile advertises links to itself and the account's
    // list sub-resources, so a client discovers favorites/watchlist
    // instead of building URLs. Non-path args are irrelevant to the
    // link's URI, so they're passed as null.
    HalResource<UserProfileResponse> model =
        HalResource.of(profile)
            .withLink(
                "self",
                linkTo(methodOn(UserController.class).getProfile(null)).withSelfRel().getHref())
            .withLink(
                "favorites",
                linkTo(methodOn(UserController.class).getFavorites(null))
                    .withRel("favorites")
                    .getHref())
            .withLink(
                "watchlist",
                linkTo(methodOn(UserController.class).getWatchlist(null))
                    .withRel("watchlist")
                    .getHref());
    return ok(model, "Profile retrieved");
  }

  /**
   * Updates the caller's profile.
   *
   * @param auth caller identity
   * @param request new profile values
   * @return 200 with the updated profile
   */
  @PutMapping("/profile")
  @Operation(summary = "Update the current user's profile")
  public ResponseEntity<ApiResponse<UserProfileResponse>> updateProfile(
      Authentication auth, @Valid @RequestBody UpdateProfileRequest request) {
    return ok(userAccountService.updateProfile(auth.getName(), request), "Profile updated");
  }

  /**
   * Changes the caller's password.
   *
   * @param auth caller identity
   * @param request current + new password
   * @return 200 acknowledgement
   */
  @PutMapping("/password")
  @Operation(summary = "Change the current user's password")
  public ResponseEntity<ApiResponse<Void>> changePassword(
      Authentication auth, @Valid @RequestBody ChangePasswordRequest request) {
    userAccountService.changePassword(auth.getName(), request);
    return ok(null, "Password changed");
  }

  /**
   * Lists the caller's favorite movies (TMDB ids), newest first.
   *
   * @param auth caller identity
   * @return 200 with the list
   */
  @GetMapping("/favorites")
  @Operation(summary = "List favorite movies")
  public ResponseEntity<ApiResponse<List<MovieListEntryResponse>>> getFavorites(
      Authentication auth) {
    return ok(userAccountService.getFavorites(auth.getName()), "Favorites retrieved");
  }

  /**
   * Adds a movie to favorites (idempotent — repeat adds succeed silently).
   *
   * @param auth caller identity
   * @param movieId TMDB movie id
   * @return 200 acknowledgement
   */
  @PostMapping("/favorites/{movieId}")
  @Operation(summary = "Add a movie to favorites (idempotent)")
  public ResponseEntity<ApiResponse<Void>> addFavorite(
      Authentication auth, @PathVariable Long movieId) {
    userAccountService.addFavorite(auth.getName(), movieId);
    return ok(null, "Added to favorites");
  }

  /**
   * Removes a movie from favorites (idempotent).
   *
   * @param auth caller identity
   * @param movieId TMDB movie id
   * @return 200 acknowledgement
   */
  @DeleteMapping("/favorites/{movieId}")
  @Operation(summary = "Remove a movie from favorites (idempotent)")
  public ResponseEntity<ApiResponse<Void>> removeFavorite(
      Authentication auth, @PathVariable Long movieId) {
    userAccountService.removeFavorite(auth.getName(), movieId);
    return ok(null, "Removed from favorites");
  }

  /**
   * Lists the caller's watchlist (TMDB ids), newest first.
   *
   * @param auth caller identity
   * @return 200 with the list
   */
  @GetMapping("/watchlist")
  @Operation(summary = "List watchlist movies")
  public ResponseEntity<ApiResponse<List<MovieListEntryResponse>>> getWatchlist(
      Authentication auth) {
    return ok(userAccountService.getWatchlist(auth.getName()), "Watchlist retrieved");
  }

  /**
   * Adds a movie to the watchlist (idempotent).
   *
   * @param auth caller identity
   * @param movieId TMDB movie id
   * @return 200 acknowledgement
   */
  @PostMapping("/watchlist/{movieId}")
  @Operation(summary = "Add a movie to the watchlist (idempotent)")
  public ResponseEntity<ApiResponse<Void>> addToWatchlist(
      Authentication auth, @PathVariable Long movieId) {
    userAccountService.addToWatchlist(auth.getName(), movieId);
    return ok(null, "Added to watchlist");
  }

  /**
   * Removes a movie from the watchlist (idempotent).
   *
   * @param auth caller identity
   * @param movieId TMDB movie id
   * @return 200 acknowledgement
   */
  @DeleteMapping("/watchlist/{movieId}")
  @Operation(summary = "Remove a movie from the watchlist (idempotent)")
  public ResponseEntity<ApiResponse<Void>> removeFromWatchlist(
      Authentication auth, @PathVariable Long movieId) {
    userAccountService.removeFromWatchlist(auth.getName(), movieId);
    return ok(null, "Removed from watchlist");
  }

  /**
   * Wraps a payload in the shared success envelope.
   *
   * @param data payload (may be null for acknowledgements)
   * @param message human-readable outcome
   * @param <T> payload type
   * @return 200 response
   */
  private static <T> ResponseEntity<ApiResponse<T>> ok(T data, String message) {
    return ResponseEntity.ok(ApiResponse.success(data, message, HttpStatus.OK.value()));
  }
}

package dev.lmdb.user.dto;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDateTime;
import java.util.UUID;

/**
 * Immutable request/response records for the user-service API (ARCHITECTURE.md Appendix B: all DTOs
 * are Java records).
 *
 * <p>Grouped in one container class because the records are small, always used together, and the
 * API surface reads best as a single contract page.
 */
public final class AuthDtos {

  /** Not instantiable — pure record container. */
  private AuthDtos() {}

  /**
   * Registration request.
   *
   * @param username unique login name, 3–50 chars
   * @param email unique, syntactically valid address
   * @param password raw password, min 8 chars (hashed immediately, never stored)
   */
  public record RegisterRequest(
      @NotBlank @Size(min = 3, max = 50) String username,
      @NotBlank @Email @Size(max = 255) String email,
      @NotBlank @Size(min = 8, max = 100) String password) {}

  /**
   * Login request.
   *
   * @param username login name
   * @param password raw password to verify against the stored BCrypt hash
   */
  public record LoginRequest(@NotBlank String username, @NotBlank String password) {}

  /**
   * Refresh / logout request carrying the opaque refresh token.
   *
   * @param refreshToken the raw opaque token previously issued
   */
  public record RefreshRequest(@NotBlank String refreshToken) {}

  /**
   * Successful authentication response.
   *
   * @param accessToken JWT for the {@code Authorization: Bearer} header
   * @param refreshToken opaque token for {@code POST /auth/refresh}; rotated on every use
   * @param tokenType always {@code Bearer}
   * @param expiresInMs access-token lifetime in milliseconds
   * @param user profile snapshot of the authenticated account
   */
  public record AuthResponse(
      String accessToken,
      String refreshToken,
      String tokenType,
      long expiresInMs,
      UserProfileResponse user) {}

  /**
   * Public profile representation (never exposes the password hash).
   *
   * @param id account UUID
   * @param username login name
   * @param email contact address
   * @param role RBAC role name
   * @param createdAt registration time
   * @param lastLogin last successful login, may be null
   */
  public record UserProfileResponse(
      UUID id,
      String username,
      String email,
      String role,
      LocalDateTime createdAt,
      LocalDateTime lastLogin) {}

  /**
   * Profile update request (currently: email only — username is immutable because it is the JWT
   * subject).
   *
   * @param email new contact address
   */
  public record UpdateProfileRequest(@NotBlank @Email @Size(max = 255) String email) {}

  /**
   * Password change request.
   *
   * @param currentPassword must match the stored hash
   * @param newPassword replacement, min 8 chars
   */
  public record ChangePasswordRequest(
      @NotBlank String currentPassword, @NotBlank @Size(min = 8, max = 100) String newPassword) {}

  /**
   * One favorites/watchlist entry.
   *
   * @param movieId TMDB movie id (hydrate details via the TMDB facade)
   * @param addedAt when the entry was created
   */
  public record MovieListEntryResponse(Long movieId, LocalDateTime addedAt) {}
}

