package dev.lmdb.user.security;

import io.jsonwebtoken.Claims;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.jspecify.annotations.NonNull;
import org.springframework.http.HttpHeaders;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Servlet filter that authenticates requests carrying a Bearer JWT.
 *
 * <p>On a valid token it populates the {@link SecurityContextHolder} with a {@link
 * UsernamePasswordAuthenticationToken} whose principal is the JWT subject (username) and whose
 * authorities are the {@code roles} claim with the {@code ROLE_} prefix. Invalid or absent tokens
 * simply leave the context empty — the authorization rules in {@code SecurityConfig} then produce
 * the 401.
 */
@Component
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

  private final JwtTokenProvider tokenProvider;

  /**
   * Extracts and validates the Bearer token, populating the security context on success.
   *
   * @param request incoming request
   * @param response outgoing response
   * @param filterChain remaining filter chain
   * @throws ServletException on downstream filter failure
   * @throws IOException on downstream I/O failure
   */
  @Override
  protected void doFilterInternal(
      @NonNull HttpServletRequest request,
      @NonNull HttpServletResponse response,
      @NonNull FilterChain filterChain)
      throws ServletException, IOException {

    // 1. Pull the compact JWT out of "Authorization: Bearer <token>".
    String header = request.getHeader(HttpHeaders.AUTHORIZATION);
    if (header != null && header.startsWith("Bearer ")) {
      String token = header.substring(7);

      // 2. Valid token → authenticated context; invalid → leave empty.
      tokenProvider
          .parse(token)
          .ifPresent(
              claims ->
                  SecurityContextHolder.getContext().setAuthentication(toAuthentication(claims)));
    }

    filterChain.doFilter(request, response);
  }

  /**
   * Maps JWT claims to a Spring Security authentication.
   *
   * @param claims validated claims
   * @return authentication with username principal and ROLE_* authorities
   */
  private UsernamePasswordAuthenticationToken toAuthentication(Claims claims) {
    Object rolesClaim = claims.get("roles");
    List<SimpleGrantedAuthority> authorities =
        rolesClaim instanceof List<?> roles
            ? roles.stream()
                .map(String::valueOf)
                .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
                .toList()
            : List.of();

    return new UsernamePasswordAuthenticationToken(claims.getSubject(), null, authorities);
  }
}

package dev.lmdb.user.security;

import dev.lmdb.user.model.User;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import java.util.List;
import java.util.Optional;
import javax.crypto.SecretKey;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Issues and validates JWT access tokens.
 *
 * <p>CONTRACT WITH THE GATEWAY: tokens must be verifiable by the API gateway's {@code JwtUtil},
 * which shares the same {@code jwt.secret} (HS256) and reads: {@code sub} = username, {@code
 * userId} = account UUID string, {@code roles} = list of role names. Changing any of these claim
 * names breaks gateway authentication — update both sides together.
 */
@Component
@Slf4j
public class JwtTokenProvider {

  /** HMAC-SHA key derived from the shared {@code jwt.secret}. */
  private final SecretKey secretKey;

  /** Access-token lifetime in milliseconds ({@code jwt.expiration}). */
  private final long expirationMs;

  /**
   * Creates the provider from configuration.
   *
   * @param secret shared HS256 secret (min 256 bits) — same value the gateway validates with
   * @param expirationMs access-token lifetime in milliseconds
   */
  public JwtTokenProvider(
      @Value("${jwt.secret}") String secret, @Value("${jwt.expiration}") long expirationMs) {
    this.secretKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    this.expirationMs = expirationMs;
  }

  /**
   * Issues an access token for an authenticated user.
   *
   * @param user the authenticated account
   * @return signed compact JWT
   */
  public String generateAccessToken(User user) {
    Date now = new Date();
    return Jwts.builder()
        .subject(user.getUsername())
        .claim("userId", user.getId().toString())
        .claim("roles", List.of(user.getRole().name()))
        .issuedAt(now)
        .expiration(new Date(now.getTime() + expirationMs))
        .signWith(secretKey)
        .compact();
  }

  /**
   * Validates a token and extracts its claims.
   *
   * @param token compact JWT from the Authorization header
   * @return claims if the signature is valid and the token unexpired; empty otherwise (never throws
   *     — callers treat empty as 401)
   */
  public Optional<Claims> parse(String token) {
    try {
      return Optional.of(
          Jwts.parser().verifyWith(secretKey).build().parseSignedClaims(token).getPayload());
    } catch (JwtException | IllegalArgumentException e) {
      // Invalid signature, malformed, or expired — all map to "not
      // authenticated", detail only logged at debug to avoid log noise.
      log.debug("JWT rejected: {}", e.getMessage());
      return Optional.empty();
    }
  }

  /**
   * Access-token lifetime, exposed for the auth response body.
   *
   * @return lifetime in milliseconds
   */
  public long getExpirationMs() {
    return expirationMs;
  }
}

package dev.lmdb.user.security;

import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpStatus;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.HttpStatusEntryPoint;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

/**
 * Spring Security configuration: stateless JWT authentication (ARCHITECTURE.md §3.5 / §6).
 *
 * <p>Design choices worth knowing:
 *
 * <ul>
 *   <li>CSRF disabled — no cookies/session, tokens travel in headers.
 *   <li>Auth endpoints, actuator, and Swagger are public; everything else needs a valid Bearer
 *       token.
 *   <li>Unauthenticated access yields a plain 401 (no redirect, no WWW-Authenticate browser popup).
 *   <li>BCrypt strength 12 per the security checklist.
 * </ul>
 */
@Configuration
@EnableWebSecurity
@EnableMethodSecurity
@RequiredArgsConstructor
public class SecurityConfig {

  private final JwtAuthenticationFilter jwtAuthenticationFilter;

  /**
   * The stateless filter chain.
   *
   * @param http builder
   * @return configured chain
   * @throws Exception per Spring Security contract
   */
  @Bean
  public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.csrf(csrf -> csrf.disable())
        .sessionManagement(
            session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .authorizeHttpRequests(
            auth ->
                auth.requestMatchers("/api/v1/auth/**")
                    .permitAll()
                    .requestMatchers("/actuator/**")
                    .permitAll()
                    .requestMatchers("/swagger-ui/**", "/swagger-ui.html", "/v3/api-docs/**")
                    .permitAll()
                    .anyRequest()
                    .authenticated())
        .exceptionHandling(
            ex -> ex.authenticationEntryPoint(new HttpStatusEntryPoint(HttpStatus.UNAUTHORIZED)))
        .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

    return http.build();
  }

  /**
   * BCrypt with strength 12 (security checklist requirement).
   *
   * @return password encoder used for hashing and verification
   */
  @Bean
  public PasswordEncoder passwordEncoder() {
    return new BCryptPasswordEncoder(12);
  }
}

package dev.lmdb.user.service;

import dev.lmdb.shared.exception.UnauthorizedException;
import dev.lmdb.shared.exception.ValidationException;
import dev.lmdb.user.dto.AuthDtos.AuthResponse;
import dev.lmdb.user.dto.AuthDtos.LoginRequest;
import dev.lmdb.user.dto.AuthDtos.RegisterRequest;
import dev.lmdb.user.dto.AuthDtos.UserProfileResponse;
import dev.lmdb.user.model.RefreshToken;
import dev.lmdb.user.model.Role;
import dev.lmdb.user.model.User;
import dev.lmdb.user.repository.RefreshTokenRepository;
import dev.lmdb.user.repository.UserRepository;
import dev.lmdb.user.security.JwtTokenProvider;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.time.LocalDateTime;
import java.util.Base64;
import java.util.HexFormat;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Authentication use-cases: register, login, refresh (with rotation) and logout (ARCHITECTURE.md
 * §3.5, issue #17).
 *
 * <p>Token model: short-lived JWT access tokens (stateless, validated by this service AND the
 * gateway with the shared secret) plus opaque, database-backed refresh tokens (revocable — see
 * {@link RefreshToken}). Every refresh ROTATES the token: the presented one is deleted and a new
 * one issued, so a stolen refresh token stops working the moment the legitimate client refreshes.
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class AuthService {

  /** Entropy for opaque refresh tokens (32 random bytes → 43-char value). */
  private static final int REFRESH_TOKEN_BYTES = 32;

  private final UserRepository userRepository;
  private final RefreshTokenRepository refreshTokenRepository;
  private final PasswordEncoder passwordEncoder;
  private final JwtTokenProvider tokenProvider;
  private final SecureRandom secureRandom = new SecureRandom();

  /** Refresh-token lifetime in ms ({@code jwt.refresh-expiration}, 7 days). */
  @Value("${jwt.refresh-expiration:604800000}")
  private long refreshExpirationMs;

  /**
   * Registers a new account and signs it in immediately.
   *
   * @param request validated registration data
   * @return auth response with fresh access + refresh tokens
   * @throws ValidationException if the username or email is already taken
   */
  @Transactional
  public AuthResponse register(RegisterRequest request) {
    // 1. Uniqueness guards (DB constraints back these up under race).
    if (userRepository.existsByUsername(request.username())) {
      throw new ValidationException("Username is already taken: " + request.username());
    }
    if (userRepository.existsByEmail(request.email())) {
      throw new ValidationException("Email is already registered: " + request.email());
    }

    // 2. Persist with the password BCrypt-hashed — raw password is
    //    garbage-collected with the request.
    User user =
        userRepository.save(
            User.builder()
                .username(request.username())
                .email(request.email())
                .passwordHash(passwordEncoder.encode(request.password()))
                .role(Role.USER)
                .enabled(true)
                .accountNonLocked(true)
                .createdAt(LocalDateTime.now())
                .build());

    log.info("Registered new user '{}'", user.getUsername());

    // 3. Immediate sign-in: same token bundle as login.
    return issueTokens(user);
  }

  /**
   * Authenticates username + password.
   *
   * @param request login credentials
   * @return auth response with fresh access + refresh tokens
   * @throws UnauthorizedException on unknown user, wrong password, or a disabled/locked account —
   *     deliberately the SAME message for all cases, so responses don't reveal which part failed
   */
  @Transactional
  public AuthResponse login(LoginRequest request) {
    User user =
        userRepository
            .findByUsername(request.username())
            .filter(u -> passwordEncoder.matches(request.password(), u.getPasswordHash()))
            .filter(User::isEnabled)
            .filter(User::isAccountNonLocked)
            .orElseThrow(() -> new UnauthorizedException("Invalid username or password"));

    user.setLastLogin(LocalDateTime.now());

    log.info("User '{}' logged in", user.getUsername());
    return issueTokens(user);
  }

  /**
   * Exchanges a valid refresh token for a new token pair (rotation).
   *
   * @param rawRefreshToken the opaque token presented by the client
   * @return auth response with a NEW access token and a NEW refresh token
   * @throws UnauthorizedException if the token is unknown, already rotated, or expired
   */
  @Transactional
  public AuthResponse refresh(String rawRefreshToken) {
    // 1. Look up by hash — raw tokens are never stored.
    RefreshToken stored =
        refreshTokenRepository
            .findByTokenHash(sha256(rawRefreshToken))
            .orElseThrow(() -> new UnauthorizedException("Invalid refresh token"));

    // 2. Expired tokens are rejected AND purged.
    if (stored.getExpiresAt().isBefore(LocalDateTime.now())) {
      refreshTokenRepository.delete(stored);
      throw new UnauthorizedException("Refresh token expired");
    }

    // 3. Rotate: the presented token dies with this use.
    User user = stored.getUser();
    refreshTokenRepository.delete(stored);

    log.debug("Rotated refresh token for '{}'", user.getUsername());
    return issueTokens(user);
  }

  /**
   * Logs the user out by revoking ALL their refresh tokens. Outstanding access tokens stay valid
   * until natural expiry (max 1 h) — the accepted trade-off of stateless JWTs, documented in the
   * failure-mode matrix.
   *
   * @param username account to log out
   */
  @Transactional
  public void logout(String username) {
    userRepository
        .findByUsername(username)
        .ifPresent(
            user -> {
              refreshTokenRepository.deleteByUser(user);
              log.info("User '{}' logged out (all refresh tokens revoked)", username);
            });
  }

  /**
   * Issues the standard token bundle for an authenticated user: a JWT access token plus a
   * stored-and-hashed opaque refresh token.
   *
   * @param user authenticated account
   * @return complete auth response
   */
  private AuthResponse issueTokens(User user) {
    // 1. Opaque refresh token: 32 random bytes, base64url. Client keeps
    //    the raw value; we keep only its SHA-256.
    byte[] bytes = new byte[REFRESH_TOKEN_BYTES];
    secureRandom.nextBytes(bytes);
    String rawRefreshToken = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);

    refreshTokenRepository.save(
        RefreshToken.builder()
            .user(user)
            .tokenHash(sha256(rawRefreshToken))
            .expiresAt(LocalDateTime.now().plusSeconds(refreshExpirationMs / 1000))
            .createdAt(LocalDateTime.now())
            .build());

    // 2. Access JWT with the gateway-compatible claim set.
    String accessToken = tokenProvider.generateAccessToken(user);

    return new AuthResponse(
        accessToken, rawRefreshToken, "Bearer", tokenProvider.getExpirationMs(), toProfile(user));
  }

  /**
   * Maps an account to its public profile representation.
   *
   * @param user account entity
   * @return profile DTO (no password hash)
   */
  static UserProfileResponse toProfile(User user) {
    return new UserProfileResponse(
        user.getId(),
        user.getUsername(),
        user.getEmail(),
        user.getRole().name(),
        user.getCreatedAt(),
        user.getLastLogin());
  }

  /**
   * Hex-encoded SHA-256, used to store/lookup refresh tokens.
   *
   * @param value raw token
   * @return 64-char lowercase hex digest
   */
  private static String sha256(String value) {
    try {
      MessageDigest digest = MessageDigest.getInstance("SHA-256");
      return HexFormat.of().formatHex(digest.digest(value.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException e) {
      // SHA-256 is mandated by the JCA spec — unreachable in practice.
      throw new IllegalStateException("SHA-256 unavailable", e);
    }
  }
}

package dev.lmdb.user.service;

import dev.lmdb.shared.exception.ResourceNotFoundException;
import dev.lmdb.shared.exception.UnauthorizedException;
import dev.lmdb.shared.exception.ValidationException;
import dev.lmdb.user.dto.AuthDtos.ChangePasswordRequest;
import dev.lmdb.user.dto.AuthDtos.MovieListEntryResponse;
import dev.lmdb.user.dto.AuthDtos.UpdateProfileRequest;
import dev.lmdb.user.dto.AuthDtos.UserProfileResponse;
import dev.lmdb.user.model.Favorite;
import dev.lmdb.user.model.User;
import dev.lmdb.user.model.WatchlistItem;
import dev.lmdb.user.repository.FavoriteRepository;
import dev.lmdb.user.repository.UserRepository;
import dev.lmdb.user.repository.WatchlistItemRepository;
import java.time.LocalDateTime;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Profile, favorites and watchlist use-cases for the authenticated user (ARCHITECTURE.md §3.5,
 * issue #17).
 *
 * <p>All methods take the caller's username (the JWT subject placed in the security context by
 * {@code JwtAuthenticationFilter}) — a user can only ever act on their own data; there is no
 * cross-user access path.
 *
 * <p>Favorites/watchlist adds and removes are IDEMPOTENT: adding a movie twice or removing an
 * absent one succeeds without error, which makes the endpoints safe for client retries and
 * toggle-style UIs.
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class UserAccountService {

  private final UserRepository userRepository;
  private final FavoriteRepository favoriteRepository;
  private final WatchlistItemRepository watchlistItemRepository;
  private final PasswordEncoder passwordEncoder;

  /**
   * Fetches the caller's profile.
   *
   * @param username JWT subject of the caller
   * @return profile DTO
   * @throws ResourceNotFoundException if the account vanished after token issue
   */
  @Transactional(readOnly = true)
  public UserProfileResponse getProfile(String username) {
    return AuthService.toProfile(requireUser(username));
  }

  /**
   * Updates the caller's profile (email only — username is the immutable JWT subject).
   *
   * @param username JWT subject of the caller
   * @param request new profile values
   * @return updated profile DTO
   * @throws ValidationException if the new email belongs to another account
   */
  @Transactional
  public UserProfileResponse updateProfile(String username, UpdateProfileRequest request) {
    User user = requireUser(username);

    // Allow "changing" to one's own current email; block anyone else's.
    if (!user.getEmail().equals(request.email()) && userRepository.existsByEmail(request.email())) {
      throw new ValidationException("Email is already registered: " + request.email());
    }

    user.setEmail(request.email());
    log.info("User '{}' updated profile", username);
    return AuthService.toProfile(user);
  }

  /**
   * Changes the caller's password after verifying the current one.
   *
   * @param username JWT subject of the caller
   * @param request current + new password
   * @throws UnauthorizedException if the current password does not match
   */
  @Transactional
  public void changePassword(String username, ChangePasswordRequest request) {
    User user = requireUser(username);

    if (!passwordEncoder.matches(request.currentPassword(), user.getPasswordHash())) {
      throw new UnauthorizedException("Current password is incorrect");
    }

    user.setPasswordHash(passwordEncoder.encode(request.newPassword()));
    log.info("User '{}' changed password", username);
  }

  /**
   * Lists the caller's favorites, newest first.
   *
   * @param username JWT subject of the caller
   * @return favorites as movie references
   */
  @Transactional(readOnly = true)
  public List<MovieListEntryResponse> getFavorites(String username) {
    return favoriteRepository.findByUserOrderByAddedAtDesc(requireUser(username)).stream()
        .map(f -> new MovieListEntryResponse(f.getMovieId(), f.getAddedAt()))
        .toList();
  }

  /**
   * Adds a movie to favorites (idempotent).
   *
   * @param username JWT subject of the caller
   * @param movieId TMDB movie id
   */
  @Transactional
  public void addFavorite(String username, Long movieId) {
    User user = requireUser(username);
    // Idempotent: present already → nothing to do.
    if (favoriteRepository.findByUserAndMovieId(user, movieId).isEmpty()) {
      favoriteRepository.save(
          Favorite.builder().user(user).movieId(movieId).addedAt(LocalDateTime.now()).build());
      log.debug("User '{}' favorited movie {}", username, movieId);
    }
  }

  /**
   * Removes a movie from favorites (idempotent).
   *
   * @param username JWT subject of the caller
   * @param movieId TMDB movie id
   */
  @Transactional
  public void removeFavorite(String username, Long movieId) {
    User user = requireUser(username);
    favoriteRepository.findByUserAndMovieId(user, movieId).ifPresent(favoriteRepository::delete);
  }

  /**
   * Lists the caller's watchlist, newest first.
   *
   * @param username JWT subject of the caller
   * @return watchlist as movie references
   */
  @Transactional(readOnly = true)
  public List<MovieListEntryResponse> getWatchlist(String username) {
    return watchlistItemRepository.findByUserOrderByAddedAtDesc(requireUser(username)).stream()
        .map(w -> new MovieListEntryResponse(w.getMovieId(), w.getAddedAt()))
        .toList();
  }

  /**
   * Adds a movie to the watchlist (idempotent).
   *
   * @param username JWT subject of the caller
   * @param movieId TMDB movie id
   */
  @Transactional
  public void addToWatchlist(String username, Long movieId) {
    User user = requireUser(username);
    if (watchlistItemRepository.findByUserAndMovieId(user, movieId).isEmpty()) {
      watchlistItemRepository.save(
          WatchlistItem.builder().user(user).movieId(movieId).addedAt(LocalDateTime.now()).build());
      log.debug("User '{}' watchlisted movie {}", username, movieId);
    }
  }

  /**
   * Removes a movie from the watchlist (idempotent).
   *
   * @param username JWT subject of the caller
   * @param movieId TMDB movie id
   */
  @Transactional
  public void removeFromWatchlist(String username, Long movieId) {
    User user = requireUser(username);
    watchlistItemRepository
        .findByUserAndMovieId(user, movieId)
        .ifPresent(watchlistItemRepository::delete);
  }

  /**
   * Resolves the caller's account or fails with 404 (the token was valid, so a missing row means
   * the account was deleted since issue).
   *
   * @param username JWT subject
   * @return account entity
   * @throws ResourceNotFoundException if no such account exists
   */
  private User requireUser(String username) {
    return userRepository
        .findByUsername(username)
        .orElseThrow(() -> new ResourceNotFoundException("User not found: " + username));
  }
}
